// Public type-checking facade for the embedded self compiler.
// Checker leaves own formation and inference; this file wires their services,
// runs the phases in order, and exposes only check to the package entry.

import types {
  CheckResult,
  PreviewTypedCall,
  PreviewTypedCapture,
  PreviewTypedNode,
  ResolveResult,
  SyntaxNode,
}
import checker_types { TypeValue }
import checker.model {
  CheckerRequest,
  CheckerResponse,
  CheckerService,
  CheckerState,
  ModuleSyntax,
  constructor,
  emptyType,
  functionType,
  primitive,
}
import checker.type_algebra {
  flattenedHasHole,
  resolvedFlatType,
  stringJoin,
  typeEqual,
  typeText,
}
import checker.syntax_index {
  addDiagnostic,
  child,
  children,
  moduleSyntax,
  spanKey,
  text,
  unwrapExport,
}
import checker.nominals {
  collectProtocols,
  fillNominals,
  predeclareNominals,
}
import checker.protocols_methods {
  collectProtocolImpls,
  collectReceiverImpls,
  functionDeclaration,
  predeclareFunctions,
}
import checker.members_capabilities { gateCollectionKey }
import checker.diagnostics_derives { checkDerives }
import checker.call_facts {
  builtinNamespaceObject,
  diagnoseUnboundReferences,
}
import checker.expression_control { inferExpression }
import checker.statements {
  checkBlock,
  checkBlockExpected,
}
import checker.bodies_captures {
  checkFunctionBodies,
  checkFunctionDeclaration,
  checkerIndexes,
  deriveCaptures,
  diagnoseLispexRuleFactoryEscapes,
  initialCheckerState,
}

function dispatchCheckerService(
  state: CheckerState,
  request: CheckerRequest,
) -> CheckerResponse {
  match request.kind {
    case "check-function" => {
      match state.modules.get(request.moduleIndex) {
        case Some(module) => checkFunctionDeclaration(
          dispatchCheckerService,
          state,
          module,
          request.node,
        )
        case None => ()
      }
      CheckerResponse { typeValue: emptyType("unknown"), boolValue: false }
    }
    case "infer-expression" => CheckerResponse {
      typeValue: inferExpression(
        dispatchCheckerService,
        state,
        request.moduleIndex,
        request.source,
        request.node,
      ),
      boolValue: false,
    }
    case "builtin-namespace-object" => CheckerResponse {
      typeValue: emptyType("unknown"),
      boolValue: builtinNamespaceObject(
        dispatchCheckerService,
        state,
        request.moduleIndex,
        request.source,
        request.node,
      ),
    }
    case "check-block" => CheckerResponse {
      typeValue: checkBlock(
        dispatchCheckerService,
        state,
        request.moduleIndex,
        request.source,
        request.node,
      ),
      boolValue: false,
    }
    case "check-block-expected" => CheckerResponse {
      typeValue: checkBlockExpected(
        dispatchCheckerService,
        state,
        request.moduleIndex,
        request.source,
        request.node,
        request.typeValue,
      ),
      boolValue: false,
    }
    case "gate-collection-key" => {
      gateCollectionKey(
        dispatchCheckerService,
        state,
        request.moduleIndex,
        request.node,
        request.typeValue,
      )
      CheckerResponse { typeValue: emptyType("unknown"), boolValue: false }
    }
    case _ => CheckerResponse { typeValue: emptyType("unknown"), boolValue: false }
  }
}

function checkerService() -> CheckerService {
  dispatchCheckerService
}

function runCheckerPhases(service: CheckerService, state: CheckerState) -> () {
  predeclareNominals(state)
  fillNominals(service, state)
  collectProtocols(service, state)
  collectReceiverImpls(service, state)
  collectProtocolImpls(service, state)
  checkDerives(state)
  predeclareFunctions(service, state)
  diagnoseUnboundReferences(state)
  checkFunctionBodies(service, state)
  diagnoseEntryPointSignatures(state)
  diagnoseLispexRuleFactoryEscapes(state)
  deriveCaptures(state)
  ()
}

function checkerResult(state: CheckerState) -> CheckResult {
  let mut nodes: Array<PreviewTypedNode> = []
  for node in state.nodes {
    let resolved = resolvedFlatType(node.typeValue, state.inferenceSolutions)
    nodes.push(PreviewTypedNode {
      ...node,
      typeValue: resolved,
      ambient: flattenedHasHole(resolved),
    })
  }
  let mut calls: Array<PreviewTypedCall> = []
  for call in state.calls {
    let calleeType = resolvedFlatType(call.calleeType, state.inferenceSolutions)
    let resultType = resolvedFlatType(call.resultType, state.inferenceSolutions)
    calls.push(PreviewTypedCall {
      ...call,
      calleeType: calleeType,
      resultType: resultType,
      ambient: flattenedHasHole(calleeType) || flattenedHasHole(resultType),
    })
  }
  let mut captures: Array<PreviewTypedCapture> = []
  for capture in state.captures {
    let resolved = resolvedFlatType(capture.typeValue, state.inferenceSolutions)
    captures.push(PreviewTypedCapture {
      ...capture,
      typeValue: resolved,
      ambient: flattenedHasHole(resolved),
    })
  }
  CheckResult {
    nodes: nodes,
    calls: calls,
    captures: captures,
    diagnostics: state.diagnostics,
  }
}

// The documented command-line entry point is
// `export function main(args: Array<string>, stdin: string) -> Result<int, string>`,
// so the entry module's exported `main` has exactly one admitted signature.
function explicitMainType() -> TypeValue {
  functionType(
    [constructor("Array", [primitive("string")]), primitive("string")],
    [],
    constructor("Result", [primitive("int"), primitive("string")]),
  )
}

function exportedMainNameNode(module: ModuleSyntax, statement: SyntaxNode) -> Option<SyntaxNode> {
  if statement.kind != "statement/export" {
    return None
  }
  let declaration = match functionDeclaration(unwrapExport(statement)) {
    case Some(value) => value
    case None => return None
  }
  let nameNode = match child(declaration, "name") {
    case Some(value) => value
    case None => return None
  }
  if text(module.source, nameNode) != "main" {
    return None
  }
  Some(nameNode)
}

function diagnoseExplicitMainSignature(
  state: CheckerState,
  module: ModuleSyntax,
  nameNode: SyntaxNode,
) -> () {
  let definitionIndex = match state.functionIndexes.get(spanKey(
    module.moduleIndex,
    nameNode.lo,
    nameNode.hi,
  )) {
    case Some(index) => index
    case None => -1
  }
  let definition = match state.functions.get(definitionIndex) {
    case Some(value) => value
    case None => return ()
  }
  let mut defaulted = false
  for value in definition.parameterDefaults {
    if value {
      defaulted = true
    }
  }
  let expected = explicitMainType()
  let actual = functionType(
    definition.parameterTypes,
    definition.variadic,
    definition.result,
  )
  if definition.typeParameters.length == 0 && !defaulted && typeEqual(actual, expected) {
    return ()
  }
  addDiagnostic(
    state,
    module.moduleIndex,
    "TPZ5022",
    "`export function main` must be non-generic and have signature `{typeText(expected)}`; found `{typeText(actual)}`",
    "",
    nameNode,
  )
}

// Only the entry module owns the command-line entry point; an exported `main`
// anywhere else is an ordinary function.
function diagnoseEntryPointSignatures(state: CheckerState) -> () {
  for module in state.modules {
    let entry = match state.resolved.modules.get(module.moduleIndex) {
      case Some(resolved) => resolved.entry
      case None => false
    }
    if !entry {
      continue
    }
    for statement in module.root.children {
      match exportedMainNameNode(module, statement) {
        case Some(nameNode) => diagnoseExplicitMainSignature(state, module, nameNode)
        case None => ()
      }
    }
  }
  ()
}

function externReplayError(
  modules: Array<string>,
  errors: Array<string>,
  target: string,
) -> Option<string> {
  let mut index = 0
  for module in modules {
    if module == target {
      return errors.get(index)
    }
    index += 1
  }
  None
}

function diagnoseExternReplayImport(
  state: CheckerState,
  module: ModuleSyntax,
  statement: SyntaxNode,
  externReplayModules: Array<string>,
  externReplayErrors: Array<string>,
) -> () {
  let item = match child(statement, "import") {
    case Some(value) => value
    case None => return ()
  }
  let path = match child(item, "path") {
    case Some(value) => value
    case None => return ()
  }
  let mut segments: Array<string> = []
  for segment in children(path, "segments") {
    segments.push(text(module.source, segment))
  }
  let target = stringJoin(segments, ".")
  match externReplayError(
    externReplayModules,
    externReplayErrors,
    target,
  ) {
    case Some(error) => addDiagnostic(
      state,
      module.moduleIndex,
      "TPZ5032",
      "extern module `{target}` has an invalid deterministic replay binding: {error}",
      "",
      path,
    )
    case None => ()
  }
}

function diagnoseExternReplayErrors(
  state: CheckerState,
  externReplayModules: Array<string>,
  externReplayErrors: Array<string>,
) -> Result<(), string> {
  if externReplayModules.length != externReplayErrors.length {
    return Err("checker extern replay fact columns differ in length")
  }
  for module in state.modules {
    for statement in module.root.children {
      if statement.kind == "statement/import" {
        diagnoseExternReplayImport(
          state,
          module,
          statement,
          externReplayModules,
          externReplayErrors,
        )
      }
    }
  }
  Ok(())
}

// Runs formation and body phases, preserving diagnostic and observation order.
export function check(
  resolved: ResolveResult,
  externReplayModules: Array<string>,
  externReplayErrors: Array<string>,
  maxAstNodes: int,
  maxAstDepth: int,
  languageMode: string = "topaz-5.20",
) -> Result<CheckResult, string> {
  let service = checkerService()
  let modules = moduleSyntax(resolved, maxAstNodes, maxAstDepth)?
  let state = initialCheckerState(resolved, modules, checkerIndexes(resolved), languageMode)
  diagnoseExternReplayErrors(state, externReplayModules, externReplayErrors)?
  runCheckerPhases(service, state)
  Ok(checkerResult(state))
}

// Function-body checking, initialization order, and closure capture derivation.
// Expression recursion enters through CheckerService; this leaf owns body
// sequencing and returns indexes used by the checker facade.

import types {
  PreviewResolvedReference,
  PreviewTypedCall,
  PreviewTypedCapture,
  ResolveResult,
  SyntaxNode,
}
import checker.model {
  CaptureTarget,
  CheckerService,
  CheckerState,
  constantRenderEpoch,
  advanceConstantRenderEpoch,
  restoreConstantRenderEpoch,
  FunctionDefinition,
  ModuleSyntax,
  ReturnExpectation,
  TYPE_BOUND_INDEX_STRIDE,
  constructor,
  emptyType,
  functionType,
  primitive,
}
import checker.type_algebra {
  flattenType,
  hasHole,
  joinedTypes,
  projectionType,
  stripProjectionTypes,
}
import checker.syntax_index {
  addDiagnostic,
  addNode,
  attribute,
  bindSymbol,
  boolAttribute,
  child,
  children,
  containsString,
  declarationFor,
  definitionNameKey,
  emptyStringIntMap,
  moduleIdentityAt,
  referenceFor,
  referenceTargetsPendingFunction,
  replaceNodeType,
  scopeFor,
  scopeKey,
  spanKey,
  text,
  typedNodeIndex,
  unwrapExport,
}
import checker.protocols_methods { functionDeclaration }
import checker.members_capabilities {
  bindingIndex,
}
import checker.patterns { patternBindingNodes }
import checker.call_facts {
  checkExpressionExpected,
}
import checker.expression_core { blockTerminates }
import checker.expression_control { inferExpression }
import checker.statements {
  checkBlock,
  checkBlockExpected,
  checkStatement,
  constantExpressionShape,
  foldConstantInteger,
  precheckTopLevelBindings,
}

function checkRecordDefaults(service: CheckerService, state: CheckerState, module: ModuleSyntax) -> () {
  for statement in module.root.children {
    let item = unwrapExport(statement)
    if item.kind == "statement/record" {
      for field in children(item, "fields") {
        match child(field, "default") {
          case Some(found) => {
            let _ = inferExpression(
              service,
              state,
              module.moduleIndex,
              module.source,
              found,
            )
          }
          case None => ()
        }
      }
    }
  }
  ()
}

function checkFunctionDefault(
  state: CheckerState,
  moduleIndex: int,
  node: SyntaxNode,
) -> () {
  if !constantExpressionShape(state, moduleIndex, node, true) {
    addDiagnostic(
      state,
      moduleIndex,
      "TPZ5001",
      "`const` initializers must be constant expressions (§4)",
      "",
      node,
    )
    return ()
  }
  let saved = constantRenderEpoch(state)
  advanceConstantRenderEpoch(state)
  let _ = foldConstantInteger(state, moduleIndex, node)
  restoreConstantRenderEpoch(state, saved)
  ()
}

function callsPendingReturnSince(
  state: CheckerState,
  firstCall: int,
) -> bool {
  let mut index = firstCall
  while index < state.calls.length {
    match state.calls.get(index) {
      case Some(call) => match referenceFor(
        state,
        call.moduleIndex,
        call.calleeLo,
        call.calleeHi,
      ) {
        case Some(reference) => if referenceTargetsPendingFunction(
          state,
          reference,
        ) {
          return true
        }
        case None => ()
      }
      case None => ()
    }
    index += 1
  }
  false
}

export function checkFunctionDeclaration(
  service: CheckerService, state: CheckerState, module: ModuleSyntax, declaration: SyntaxNode,
) -> () {
  let saved = constantRenderEpoch(state)
  advanceConstantRenderEpoch(state)
  checkFunctionDeclarationInner(service, state, module, declaration)
  restoreConstantRenderEpoch(state, saved)
}

function checkFunctionDeclarationInner(
  service: CheckerService,
  state: CheckerState,
  module: ModuleSyntax,
  declaration: SyntaxNode,
) -> () {
  let nameNode = match child(declaration, "name") {
    case Some(found) => found
    case None => declaration
  }
  let mut exported = false
  for published in state.resolved.exports {
    if published.moduleIndex == module.moduleIndex && published.namespace == "value" &&
      published.declarationLo == nameNode.lo && published.declarationHi == nameNode.hi {
      exported = true
    }
  }
  let mut seenBounds: Array<string> = []
  for bound in children(declaration, "typeParameterBounds") {
    let protocol = text(module.source, bound)
    if exported && protocol != "Eq" && protocol != "Order" && protocol != "Show" && protocol != "JSON" {
      addDiagnostic(state, module.moduleIndex, "TPZ5524",
        "exported functions cannot expose module-local protocol bound `{protocol}`", "", bound)
    }
    let key = "{bound.index / TYPE_BOUND_INDEX_STRIDE}:{protocol}"
    if containsString(seenBounds, key) {
      addDiagnostic(state, module.moduleIndex, "TPZ5523",
        "protocol bound `{protocol}` is repeated for the same type parameter", "", bound)
    } else {
      seenBounds.push(key)
    }
  }
  let definitionIndex = match state.functionIndexes.get(spanKey(
    module.moduleIndex,
    nameNode.lo,
    nameNode.hi,
  )) {
    case Some(index) => index
    case None => -1
  }
  match state.functions.get(definitionIndex) {
    case Some(definition) => {
      let mut fixedIndex = 0
      for parameter in children(declaration, "parameters") {
        let name = match child(parameter, "name") {
          case Some(found) => found
          case None => parameter
        }
        let parameterType = if boolAttribute(parameter, "variadic") {
          constructor("Array", [match definition.variadic.get(0) {
            case Some(found) => found
            case None => emptyType("unknown")
          }])
        } else {
          match definition.parameterTypes.get(fixedIndex) {
            case Some(found) => found
            case None => emptyType("unknown")
          }
        }
        if !boolAttribute(parameter, "variadic") {
          fixedIndex += 1
        }
        bindSymbol(
          state,
          module.moduleIndex,
          name.lo,
          name.hi,
          text(module.source, name),
          parameterType,
          false,
        )
        addNode(state, module.moduleIndex, "binding", name, parameterType)
        match child(parameter, "default") {
          case Some(found) => {
            let _ = checkExpressionExpected(
              service,
              state,
              module.moduleIndex,
              module.source,
              found,
              parameterType,
            )
            checkFunctionDefault(state, module.moduleIndex, found)
          }
          case None => ()
        }
      }
      match child(declaration, "body") {
        case Some(body) => {
          let inferredResult = definition.result.kind == "unknown"
          let firstCall = state.calls.length
          let mut activeFunctions = state.activeFunctions
          activeFunctions.push(definitionIndex)
          let mut loopFloors = state.loopFloors
          loopFloors.push(state.loopFrames.length)
          let mut expectedReturns = state.expectedReturns
          expectedReturns.push(ReturnExpectation { typeValue: definition.result, checkResult: true })
          let mut returnJoins = state.returnJoins
          returnJoins.push([])
          let bodyResult = if inferredResult {
            checkBlock(
              service,
              state,
              module.moduleIndex,
              module.source,
              body,
            )
          } else {
            checkBlockExpected(
              service,
              state,
              module.moduleIndex,
              module.source,
              body,
              definition.result,
            )
          }
          let mut returns = match returnJoins.get(returnJoins.length - 1) {
            case Some(found) => found
            case None => []
          }
          returnJoins.pop()
          expectedReturns.pop()
          loopFloors.pop()
          activeFunctions.pop()
          if inferredResult {
            match child(body, "tail") {
              case Some(_) => returns.push(bodyResult)
              case None => if !blockTerminates(body) {
                returns.push(primitive("unit"))
              }
            }
            let mut result = if returns.length == 0 {
              primitive("unit")
            } else {
              let mut unresolved = false
              for found in returns {
                if hasHole(found) {
                  unresolved = true
                }
              }
              if unresolved {
                emptyType("unknown")
              } else {
                joinedTypes(state, returns, true)
              }
            }
            if projectionType(result) {
              addDiagnostic(
                state,
                module.moduleIndex,
                "TPZ5022",
                "cannot infer a return type for `{definition.name}`: it returns a destructured generic value with no nameable type — annotate the return type",
                "",
                nameNode,
              )
              result = stripProjectionTypes(result)
            }
            if result.kind == "unknown" &&
              callsPendingReturnSince(state, firstCall) {
              addDiagnostic(
                state,
                module.moduleIndex,
                "TPZ5022",
                "`{definition.name}` is (mutually) recursive: declare its return type (§7)",
                "",
                nameNode,
              )
            }
            let mut pending = state.pendingFunctions
            pending[definitionIndex] = false
            let patched = FunctionDefinition {
              ...definition,
              result: result,
            }
            let mut functions = state.functions
            functions[definitionIndex] = patched
            let functionValue = functionType(
              definition.parameterTypes,
              definition.variadic,
              result,
            )
            bindSymbol(
              state,
              module.moduleIndex,
              nameNode.lo,
              nameNode.hi,
              definition.name,
              functionValue,
              false,
            )
            replaceNodeType(
              state,
              module.moduleIndex,
              "declaration",
              nameNode,
              functionValue,
            )
          }
        }
        case None => ()
      }
      // Publish the declaration fact after checking its body. Signatures used
      // during recursion are already available in symbols and functions.
      addNode(
        state,
        module.moduleIndex,
        "declaration",
        nameNode,
        functionType(
          definition.parameterTypes,
          definition.variadic,
          definition.result,
        ),
      )
    }
    case None => ()
  }
  ()
}

function staticTopLevelItem(item: SyntaxNode) -> bool {
  item.kind == "statement/function" ||
    item.kind == "statement/impl" ||
    item.kind == "statement/record" ||
    item.kind == "statement/enum" ||
    item.kind == "statement/newtype" ||
    item.kind == "statement/type-alias" ||
    item.kind == "statement/protocol" ||
    item.kind == "statement/const" ||
    item.kind == "statement/import"
}

function checkImplBodies(
  service: CheckerService,
  state: CheckerState,
  module: ModuleSyntax,
  statement: SyntaxNode,
) -> () {
  let item = unwrapExport(statement)
  if item.kind != "statement/impl" {
    return ()
  }
  for method in children(item, "methods") {
    match child(method, "declaration") {
      case Some(declaration) => checkFunctionDeclaration(
        service,
        state,
        module,
        declaration,
      )
      case None => ()
    }
  }
  ()
}

function topLevelRuntimeBindingIndexes(
  module: ModuleSyntax,
) -> Map<int, int> {
  let mut indexes: Map<int, int> = map {}
  let mut index = 0
  for statement in module.root.children {
    let item = unwrapExport(statement)
    match functionDeclaration(item) {
      case Some(declaration) => match child(declaration, "name") {
        case Some(name) => indexes.insert(name.lo, index)
        case None => ()
      }
      case None => if item.kind == "statement/let" {
        match child(item, "pattern") {
          case Some(pattern) => for binding in patternBindingNodes(pattern) {
            indexes.insert(binding.lo, index)
          }
          case None => ()
        }
      } else {
        ()
      }
    }
    index += 1
  }
  indexes
}

function initializationReferenceViolation(
  state: CheckerState,
  module: ModuleSyntax,
  runtimeBindingIndexes: Map<int, int>,
  cutoff: int,
  node: SyntaxNode,
) -> bool {
  match referenceFor(state, module.moduleIndex, node.lo, node.hi) {
    case Some(reference) => if reference.targetModuleIndex == module.moduleIndex {
      match runtimeBindingIndexes.get(reference.targetLo) {
        case Some(target) => target >= cutoff
        case None => false
      }
    } else {
      false
    }
    case None => false
  }
}

function initializationChildIsImmediate(
  parent: SyntaxNode,
  found: SyntaxNode,
) -> bool {
  // Conditional children are delayed under the same DIRECT rule as branch,
  // arm, loop, lambda, function, defer, and concurrent bodies.
  let kind = parent.kind
  if kind == "statement/function" || kind == "statement/defer" ||
    kind == "statement/break" || kind == "statement/continue" ||
    kind == "expression/lambda" || kind == "expression/loop" {
    return false
  }
  if kind == "statement/while" || kind == "expression/if" {
    return found.field == "condition"
  }
  if kind == "expression/match" {
    return found.field == "scrutinee"
  }
  if kind == "expression/for" || kind == "comprehension-clause/for" {
    return found.field == "iterator"
  }
  if kind == "expression/comprehension" {
    return found.field == "clauses" && found.index == 0 &&
      found.kind == "comprehension-clause/for"
  }
  if kind == "expression/concurrent" {
    return found.field == "timeout"
  }
  if kind == "expression/binary" && found.field == "right" {
    let operator = attribute(parent, "operator")
    return operator != "and" && operator != "or" && operator != "coalesce"
  }
  if kind == "expression/call" && found.field == "arguments" {
    match child(parent, "callee") {
      case Some(callee) => return callee.kind != "expression/optional-access"
      case None => ()
    }
  }
  if kind == "statement/let" || kind == "statement/const" ||
    kind == "statement/return" {
    return found.field == "value"
  }
  if kind == "statement/assign" {
    return found.field == "target" || found.field == "value"
  }
  if kind == "statement/using" {
    return found.field == "value" || found.field == "body"
  }
  if kind.startsWith("statement/") {
    return kind == "statement/expression"
  }
  true
}

function initializationViolation(
  state: CheckerState,
  module: ModuleSyntax,
  runtimeBindingIndexes: Map<int, int>,
  cutoff: int,
  node: SyntaxNode,
) -> Option<SyntaxNode> {
  if node.kind == "expression/identifier" {
    return if initializationReferenceViolation(
      state,
      module,
      runtimeBindingIndexes,
      cutoff,
      node,
    ) {
      Some(node)
    } else {
      None
    }
  }
  for found in node.children {
    if initializationChildIsImmediate(node, found) {
      match initializationViolation(
        state,
        module,
        runtimeBindingIndexes,
        cutoff,
        found,
      ) {
        case Some(violation) => return Some(violation)
        case None => ()
      }
    }
  }
  None
}

function reportInitializationViolation(
  state: CheckerState,
  module: ModuleSyntax,
  violation: Option<SyntaxNode>,
) -> () {
  match violation {
    case Some(found) => addDiagnostic(
      state,
      module.moduleIndex,
      "TPZ5002",
      "`{text(module.source, found)}` is not bound",
      "",
      found,
    )
    case None => ()
  }
}

function checkTopLevelInitializationOrder(
  state: CheckerState,
  module: ModuleSyntax,
) -> () {
  let runtimeBindingIndexes = topLevelRuntimeBindingIndexes(module)
  let mut cutoff = 0
  for statement in module.root.children {
    let item = unwrapExport(statement)
    if item.kind == "statement/let" {
      match child(item, "value") {
        case Some(found) => reportInitializationViolation(
          state,
          module,
          initializationViolation(
            state,
            module,
            runtimeBindingIndexes,
            cutoff,
            found,
          ),
        )
        case None => ()
      }
    } else if item.kind == "statement/using" {
      match child(item, "value") {
        case Some(found) => reportInitializationViolation(
          state,
          module,
          initializationViolation(
            state,
            module,
            runtimeBindingIndexes,
            cutoff,
            found,
          ),
        )
        case None => ()
      }
      match child(item, "body") {
        case Some(found) => reportInitializationViolation(
          state,
          module,
          initializationViolation(
            state,
            module,
            runtimeBindingIndexes,
            cutoff,
            found,
          ),
        )
        case None => ()
      }
    } else if item.kind == "statement/assign" {
      for field in ["target", "value"] {
        match child(item, field) {
          case Some(found) => reportInitializationViolation(
            state,
            module,
            initializationViolation(
              state,
              module,
              runtimeBindingIndexes,
              cutoff,
              found,
            ),
          )
          case None => ()
        }
      }
    } else if item.kind == "statement/while" {
      match child(item, "condition") {
        case Some(found) => reportInitializationViolation(
          state,
          module,
          initializationViolation(
            state,
            module,
            runtimeBindingIndexes,
            cutoff,
            found,
          ),
        )
        case None => ()
      }
    } else if item.kind == "statement/expression" ||
      item.kind == "statement/return" {
      for found in item.children {
        reportInitializationViolation(
          state,
          module,
          initializationViolation(
            state,
            module,
            runtimeBindingIndexes,
            cutoff,
            found,
          ),
        )
      }
    }
    cutoff += 1
  }
  ()
}

function checkModuleBodies(service: CheckerService, state: CheckerState, module: ModuleSyntax) -> () {
  checkRecordDefaults(service, state, module)
  for statement in module.root.children {
    checkImplBodies(service, state, module, statement)
    match functionDeclaration(unwrapExport(statement)) {
      case Some(declaration) => checkFunctionDeclaration(
        service,
        state,
        module,
        declaration,
      )
      case None => if !staticTopLevelItem(unwrapExport(statement)) {
        checkStatement(
          service,
          state,
          module.moduleIndex,
          module.source,
          statement,
        )
      }
    }
  }
  checkTopLevelInitializationOrder(state, module)
  ()
}

export function checkFunctionBodies(service: CheckerService, state: CheckerState) -> () {
  // The resolver supplies dependency order, so inferred exported bindings
  // are available before a consumer checks its own initializers.
  let ordered = state.modules
  for module in ordered {
    precheckTopLevelBindings(service, state, module)
  }
  advanceConstantRenderEpoch(state)
  for module in ordered {
    checkModuleBodies(service, state, module)
  }
  ()
}

function captureScopeAncestors(
  state: CheckerState,
  indexes: Map<string, Set<int>>,
  moduleIndex: int,
  ordinal: int,
) -> Set<int> {
  let key = scopeKey(moduleIndex, ordinal)
  match indexes.get(key) {
    case Some(found) => return found
    case None => ()
  }
  let mut ancestors: Set<int> = set {}
  let mut current = ordinal
  while current >= 0 {
    ancestors.add(current)
    match scopeFor(state, moduleIndex, current) {
      case Some(scope) => {
        current = scope.parentOrdinal
      }
      case None => {
        current = -1
      }
    }
  }
  let mut target = indexes
  target.insert(key, ancestors)
  ancestors
}

function namespaceCaptureTarget(
  state: CheckerState,
  reference: PreviewResolvedReference,
) -> Option<CaptureTarget> {
  let segments = reference.name.split(".")
  if segments.length < 2 {
    return None
  }
  let alias = match segments.get(0) {
    case Some(found) => found
    case None => return None
  }
  let index = match state.namespaceImportIndexes.get(
      definitionNameKey(reference.moduleIndex, alias),
  ) {
    case Some(found) => found
    case None => return None
  }
  let declaration = match state.resolved.declarations.get(index) {
    case Some(found) => found
    case None => return None
  }
  let unknown = emptyType("unknown")
  Some(CaptureTarget {
    declaration: declaration,
    name: declaration.name,
    typeValue: flattenType(unknown),
    ambient: true,
  })
}

function captureTargetForReference(
  state: CheckerState,
  reference: PreviewResolvedReference,
) -> Option<CaptureTarget> {
  if reference.namespace != "value" {
    return None
  }
  if reference.role == "namespace-member" {
    return namespaceCaptureTarget(state, reference)
  }
  if reference.targetModuleIndex != reference.moduleIndex {
    return None
  }
  let bindingIndex = typedNodeIndex(
    state,
    reference.targetModuleIndex,
    "binding",
    reference.targetLo,
    reference.targetHi,
  )
  let declarationIndex = typedNodeIndex(
    state,
    reference.targetModuleIndex,
    "declaration",
    reference.targetLo,
    reference.targetHi,
  )
  let declaredIndex = if bindingIndex > declarationIndex {
    bindingIndex
  } else {
    declarationIndex
  }
  let observedIndex = if declaredIndex >= 0 {
    declaredIndex
  } else {
    typedNodeIndex(
      state,
      reference.moduleIndex,
      "expression",
      reference.lo,
      reference.hi,
    )
  }
  let typedNode = match state.nodes.get(observedIndex) {
    case Some(found) => found
    case None => return None
  }
  let declaration = match declarationFor(
      state,
      reference.targetModuleIndex,
      reference.targetLo,
      reference.targetHi,
  ) {
    case Some(found) => found
    case None => return None
  }
  Some(CaptureTarget {
    declaration: declaration,
    name: reference.name,
    typeValue: typedNode.typeValue,
    ambient: typedNode.ambient,
  })
}

function capturesForReference(
  state: CheckerState,
  scopeAncestorIndexes: Map<string, Set<int>>,
  reference: PreviewResolvedReference,
) -> Array<PreviewTypedCapture> {
  let mut captures: Array<PreviewTypedCapture> = []
  let target = match captureTargetForReference(state, reference) {
    case Some(found) => found
    case None => return captures
  }
  let declarationAncestors = captureScopeAncestors(
    state,
    scopeAncestorIndexes,
    reference.moduleIndex,
    target.declaration.scopeOrdinal,
  )
  let mut current = reference.scopeOrdinal
  while current >= 0 {
    match scopeFor(state, reference.moduleIndex, current) {
      case Some(scope) => {
        if (scope.kind == "function" || scope.kind == "lambda") &&
          !declarationAncestors.contains(scope.ordinal) {
          captures.push(PreviewTypedCapture {
            moduleIndex: reference.moduleIndex,
            closureLo: scope.lo,
            closureHi: scope.hi,
            referenceLo: reference.lo,
            referenceHi: reference.hi,
            declarationLo: target.declaration.lo,
            declarationHi: target.declaration.hi,
            name: target.name,
            typeValue: target.typeValue,
            ambient: target.ambient,
          })
        }
        current = scope.parentOrdinal
      }
      case None => {
        current = -1
      }
    }
  }
  captures
}

function capturesAreSame(
  left: PreviewTypedCapture,
  right: PreviewTypedCapture,
) -> bool {
  left.moduleIndex == right.moduleIndex &&
  left.closureLo == right.closureLo &&
  left.closureHi == right.closureHi &&
  left.referenceLo == right.referenceLo &&
  left.referenceHi == right.referenceHi &&
  left.declarationLo == right.declarationLo &&
  left.declarationHi == right.declarationHi &&
  left.name == right.name
}

function sortAndDeduplicateCaptures(state: CheckerState) -> () {
  let mut target = state.captures
  target.sortBy((capture) => capture.name)
  target.sortBy((capture) => capture.declarationHi)
  target.sortBy((capture) => capture.declarationLo)
  target.sortBy((capture) => capture.referenceHi)
  target.sortBy((capture) => capture.referenceLo)
  target.sortBy((capture) => capture.closureHi)
  target.sortBy((capture) => capture.closureLo)
  target.sortBy((capture) => capture.moduleIndex)
  target.sortBy((capture) => moduleIdentityAt(state, capture.moduleIndex))
  let mut index = 1
  while index < target.length {
    let previous = match target.get(index - 1) {
      case Some(value) => value
      case None => return ()
    }
    let current = match target.get(index) {
      case Some(value) => value
      case None => return ()
    }
    if capturesAreSame(previous, current) {
      target.removeAt(index)
    } else {
      index += 1
    }
  }
}

export function deriveCaptures(state: CheckerState) -> () {
  let mut scopeAncestorIndexes: Map<string, Set<int>> = map {}
  let mut captures = state.captures
  for reference in state.resolved.references {
    for capture in capturesForReference(
      state,
      scopeAncestorIndexes,
      reference,
    ) {
      captures.push(capture)
    }
  }
  sortAndDeduplicateCaptures(state)
  ()
}

function lispexRuleFactoryCallIndexes(
  calls: Array<PreviewTypedCall>,
) -> Map<string, Array<int>> {
  let mut indexes: Map<string, Array<int>> = map {}
  let mut index = 0
  for call in calls {
    if call.arguments.length == 0 &&
      call.targetIdentity.startsWith("topaz.lispex-rule-handle/v1:") {
      let key = definitionNameKey(call.moduleIndex, call.targetIdentity)
      match indexes.get(key) {
        case Some(found) => {
          let mut targets = found
          targets.push(index)
        }
        case None => indexes.insert(key, [index])
      }
    }
    index += 1
  }
  indexes
}

export function diagnoseLispexRuleFactoryEscapes(state: CheckerState) -> () {
  let callIndexes = lispexRuleFactoryCallIndexes(state.calls)
  for reference in state.resolved.references {
    if reference.namespace != "value" ||
      reference.targetModule != "std.lispex.rules" ||
      reference.targetName == "" {
      continue
    }
    let expected = "topaz.lispex-rule-handle/v1:{reference.targetName}"
    let mut direct = false
    match callIndexes.get(definitionNameKey(reference.moduleIndex, expected)) {
      case Some(indexes) => for index in indexes {
        match state.calls.get(index) {
          case Some(call) => if reference.lo >= call.calleeLo &&
            reference.hi <= call.calleeHi {
            direct = true
          }
          case None => ()
        }
      }
      case None => ()
    }
    if !direct {
      addDiagnostic(
        state,
        reference.moduleIndex,
        "TPZ5500",
        "a generated Lispex rule factory may only appear as the direct callee of a zero-argument call",
        "",
        SyntaxNode {
          kind: "identifier",
          lo: reference.lo,
          hi: reference.hi,
          field: "",
          index: 0,
          attributes: [],
          children: [],
        },
      )
    }
  }
  ()
}

record DeclarationIndexes {
  spans: Map<string, int>,
  valuesByModule: Map<string, Array<int>>,
  namespaceImports: Map<string, int>,
}

export record CheckerIndexes {
  declarations: Map<string, int>,
  valueDeclarationsByModule: Map<string, Array<int>>,
  namespaceImports: Map<string, int>,
  references: Map<string, int>,
  scopes: Map<string, int>,
}

function declarationIndexes(resolved: ResolveResult) -> DeclarationIndexes {
  let mut spans = emptyStringIntMap()
  let mut valuesByModule: Map<string, Array<int>> = map {}
  let mut namespaceImports = emptyStringIntMap()
  let mut index = 0
  for declaration in resolved.declarations {
    let span = spanKey(declaration.moduleIndex, declaration.lo, declaration.hi)
    match spans.get(span) {
      case Some(_) => ()
      case None => spans.insert(span, index)
    }
    let scopeName = "lexical:{declaration.moduleIndex}:{declaration.scopeOrdinal}:{declaration.namespace}:{declaration.name}"
    match spans.get(scopeName) {
      case Some(_) => ()
      case None => spans.insert(scopeName, index)
    }
    if declaration.scopeOrdinal == 0 {
      let name = "original:{declaration.moduleIndex}:{declaration.namespace}:{declaration.name}"
      match spans.get(name) {
        case Some(_) => ()
        case None => spans.insert(name, index) }
    }
    if declaration.namespace == "value" {
      let key = "{declaration.moduleIndex}"
      match valuesByModule.get(key) {
        case Some(found) => {
          let mut targets = found
          targets.push(index)
        }
        case None => valuesByModule.insert(key, [index])
      }
    }
    if declaration.namespace == "module" &&
      declaration.declarationKind == "namespace-import" {
      let name = definitionNameKey(declaration.moduleIndex, declaration.name)
      match namespaceImports.get(name) {
        case Some(_) => ()
        case None => namespaceImports.insert(name, index)
      }
    }
    index += 1
  }
  DeclarationIndexes {
    spans: spans,
    valuesByModule: valuesByModule,
    namespaceImports: namespaceImports,
  }
}

function referenceSpanIndexes(resolved: ResolveResult) -> Map<string, int> {
  let mut indexes = emptyStringIntMap()
  let mut index = 0
  for reference in resolved.references {
    let key = spanKey(reference.moduleIndex, reference.lo, reference.hi)
    match indexes.get(key) {
      case Some(_) => ()
      case None => indexes.insert(key, index)
    }
    index += 1
  }
  indexes
}

function scopeOrdinalIndexes(resolved: ResolveResult) -> Map<string, int> {
  let mut indexes = emptyStringIntMap()
  let mut index = 0
  for scope in resolved.scopes {
    let key = scopeKey(scope.moduleIndex, scope.ordinal)
    match indexes.get(key) {
      case Some(_) => ()
      case None => indexes.insert(key, index)
    }
    index += 1
  }
  indexes
}

export function checkerIndexes(resolved: ResolveResult) -> CheckerIndexes {
  let declarations = declarationIndexes(resolved)
  CheckerIndexes {
    declarations: declarations.spans,
    valueDeclarationsByModule: declarations.valuesByModule,
    namespaceImports: declarations.namespaceImports,
    references: referenceSpanIndexes(resolved),
    scopes: scopeOrdinalIndexes(resolved),
  }
}

export function initialCheckerState(
  resolved: ResolveResult,
  modules: Array<ModuleSyntax>,
  indexes: CheckerIndexes,
  languageMode: string = "topaz-5.20",
) -> CheckerState {
  CheckerState {
    languageMode: languageMode,
    constantRenderEpoch: [0],
    resolved: resolved,
    modules: modules,
    declarationIndexes: indexes.declarations,
    valueDeclarationIndexesByModule: indexes.valueDeclarationsByModule,
    namespaceImportIndexes: indexes.namespaceImports,
    referenceIndexes: indexes.references,
    scopeIndexes: indexes.scopes,
    symbolIndexes: emptyStringIntMap(),
    nodeIndexes: emptyStringIntMap(),
    callIndexes: emptyStringIntMap(),
    functionIndexes: emptyStringIntMap(),
    functionNameIndexes: emptyStringIntMap(),
    receiverMethodIndexes: emptyStringIntMap(),
    protocolIndexes: emptyStringIntMap(),
    conformanceIndexes: emptyStringIntMap(),
    conformanceTypeIndexes: emptyStringIntMap(),
    recordIndexes: emptyStringIntMap(),
    enumIndexes: emptyStringIntMap(),
    newtypeIndexes: emptyStringIntMap(),
    aliasIndexes: emptyStringIntMap(),
    symbols: [],
    records: [],
    enums: [],
    newtypes: [],
    aliases: [],
    functions: [],
    receiverMethods: [],
    protocols: [],
    pendingFunctions: [],
    functionAliases: emptyStringIntMap(),
    boundBuiltins: map {},
    conformances: [],
    typeParameters: [],
    activeFunctions: [],
    expectedReturns: [],
    returnJoins: [],
    expectedExpressions: [],
    bareBindingExpressions: [],
    literalJoinContexts: [],
    branchJoinContexts: [],
    statementExpressionContexts: [],
    typeCapabilitySuppressions: [],
    loopFrames: [],
    loopFloors: [],
    pipeValues: [],
    nodes: [],
    calls: [],
    captures: [],
    diagnostics: [],
    inferenceSolutions: map {},
    nextInference: 0,
  }
}

// Pure parameter/default metadata shared by direct and bound builtin calls.
import checker_types { TypeValue }
import checker.model { CallSignature, lengthUnit }

export function stringElementType(value: TypeValue) -> bool {
  if value.kind == "primitive" || value.kind == "literal" { return value.name == "string" }
  if value.kind != "union" || value.members.length == 0 { return false }
  for member in value.members { if !stringElementType(member) { return false } }
  true
}

export function builtinNamespaceFamily(namespace: string) -> string {
  match namespace {
    case "Array" | "Set" | "Bytes" | "ByteBuffer" | "Map" =>
      "collection"
    case "Math" | "Codec" | "Hash" => "numeric-binary"
    case "FS" | "Encoding" | "Cli" | "Path" | "Regex" => "host"
    case "CSV" | "TOML" | "JSON" => "structured-data"
    case "URL" | "Date" | "BigInt" | "Decimal" | "RoundingMode" |
      "Test" => "scalar"
    case "Show" | "Eq" | "Order" => "protocol"
    case _ => ""
  }
}

export function requiredCallSignature(
  parameterNames: Array<string>,
  variadic: bool,
) -> CallSignature {
  let mut defaults: Array<bool> = []
  for _ in parameterNames {
    defaults.push(false)
  }
  CallSignature {
    parameterNames: parameterNames,
    parameterDefaults: defaults,
    parameterCount: parameterNames.length,
    variadic: variadic,
    positionalOnlyIdentity: "",
  }
}

export function defaultedCallSignature(
  parameterNames: Array<string>,
  parameterDefaults: Array<bool>,
) -> CallSignature {
  CallSignature {
    parameterNames: parameterNames,
    parameterDefaults: parameterDefaults,
    parameterCount: parameterNames.length,
    variadic: false,
    positionalOnlyIdentity: "",
  }
}

export function positionalOnlyCallSignature(
  identity: string,
  parameterNames: Array<string>,
) -> CallSignature {
  CallSignature {
    ...requiredCallSignature(parameterNames, false),
    positionalOnlyIdentity: identity,
  }
}

function collectionStaticCallSignature(
  namespace: string,
  name: string,
) -> Option<CallSignature> {
  if (namespace == "Array" || namespace == "Set") && name == "of" {
    return Some(requiredCallSignature([], true))
  }
  if namespace == "Map" {
    return match name {
      case "new" => Some(requiredCallSignature([], false))
      case "ofEntries" => Some(requiredCallSignature(["entries"], false))
      case _ => None
    }
  }
  if namespace == "Bytes" {
    return match name {
      case "empty" => Some(requiredCallSignature([], false))
      case "encodeUtf8" | "fromHex" | "fromBase64" =>
        Some(requiredCallSignature(["s"], false))
      case "fromArray" => Some(requiredCallSignature(["values"], false))
      case "concat" => Some(requiredCallSignature(["a", "b"], false))
      case _ => None
    }
  }
  if namespace == "ByteBuffer" {
    return match name {
      case "allocate" => Some(defaultedCallSignature(
        ["length", "value"],
        [false, true],
      ))
      case "fromBytes" => Some(requiredCallSignature(["value"], false))
      case _ => None
    }
  }
  None
}

function numericBinaryStaticCallSignature(
  namespace: string,
  name: string,
) -> Option<CallSignature> {
  if namespace == "Math" {
    return match name {
      case "sqrt" | "abs" | "floor" | "ceil" | "round" |
        "sin" | "cos" | "tan" | "isNaN" | "isFinite" =>
        Some(requiredCallSignature(["x"], false))
      case "parseFloat" => Some(requiredCallSignature(["s"], false))
      case "min" | "max" => Some(requiredCallSignature(["a", "b"], false))
      case _ => None
    }
  }
  if namespace == "Codec" {
    return match name {
      case "zstdCompress" => Some(defaultedCallSignature(
        ["bytes", "level"],
        [false, true],
      ))
      case "gzipCompress" | "gzipDecompress" | "deflateCompress" |
        "deflateFixedCompress" | "zlibFixedCompress" |
        "reedSolomon255223Protect" | "deflateDecompress" |
        "zstdDecompress" => Some(requiredCallSignature(["bytes"], false))
      case _ => None
    }
  }
  if namespace == "Hash" {
    return match name {
      case "sha256" | "sha512" | "crc32" =>
        Some(requiredCallSignature(["data"], false))
      case "hmacSha256" => Some(requiredCallSignature(
        ["key", "message"],
        false,
      ))
      case _ => None
    }
  }
  None
}

function hostStaticCallSignature(
  namespace: string,
  name: string,
) -> Option<CallSignature> {
  if namespace == "FS" {
    return match name {
      case "readText" | "readBytes" | "list" =>
        Some(requiredCallSignature(["path"], false))
      case "writeText" => Some(requiredCallSignature(
        ["path", "text"],
        false,
      ))
      case "writeBytes" => Some(requiredCallSignature(
        ["path", "bytes"],
        false,
      ))
      case _ => None
    }
  }
  if namespace == "Encoding" {
    return match name {
      case "utf8Encode" | "hexDecode" | "base64Decode" =>
        Some(requiredCallSignature(["text"], false))
      case "utf8Decode" | "hexEncode" | "base64Encode" =>
        Some(requiredCallSignature(["bytes"], false))
      case _ => None
    }
  }
  if namespace == "Cli" {
    return match name {
      case "hasFlag" | "option" | "options" =>
        Some(requiredCallSignature(["args", "name"], false))
      case "positionals" => Some(requiredCallSignature(["args"], false))
      case _ => None
    }
  }
  if namespace == "Path" &&
    (name == "from" || name == "cwdRelative" || name == "project") {
    return Some(requiredCallSignature(["text"], false))
  }
  if namespace == "Regex" && name == "compile" {
    return Some(requiredCallSignature(["pattern"], false))
  }
  None
}

function structuredDataStaticCallSignature(
  namespace: string,
  name: string,
) -> Option<CallSignature> {
  if namespace == "CSV" {
    return match name {
      case "parse" | "parseWithHeader" =>
        Some(requiredCallSignature(["text"], false))
      case "stringify" => Some(requiredCallSignature(["rows"], false))
      case "stringifyWithHeader" => Some(requiredCallSignature(
        ["rows", "columns"],
        false,
      ))
      case _ => None
    }
  }
  if namespace == "TOML" {
    return match name {
      case "parse" => Some(requiredCallSignature(["text"], false))
      case "stringify" | "toJson" | "fromJson" =>
        Some(requiredCallSignature(["value"], false))
      case _ => None
    }
  }
  if namespace == "JSON" {
    return match name {
      case "parseAs" | "parse" =>
        Some(requiredCallSignature(["text"], false))
      case "decode" | "stringify" =>
        Some(requiredCallSignature(["value"], false))
      case _ => None
    }
  }
  None
}

function scalarTestStaticCallSignature(
  namespace: string,
  name: string,
) -> Option<CallSignature> {
  if namespace == "URL" && name == "parse" {
    return Some(requiredCallSignature(["text"], false))
  }
  if namespace == "Date" {
    return match name {
      case "fromYmd" => Some(requiredCallSignature(
        ["year", "month", "day"],
        false,
      ))
      case "parseIso" => Some(requiredCallSignature(["text"], false))
      case _ => None
    }
  }
  if namespace == "BigInt" {
    return match name {
      case "fromInt" => Some(requiredCallSignature(["n"], false))
      case "parse" => Some(requiredCallSignature(["text", "radix"], false))
      case _ => None
    }
  }
  if namespace == "Decimal" {
    return match name {
      case "fromInt" => Some(requiredCallSignature(["n"], false))
      case "parse" => Some(requiredCallSignature(["text"], false))
      case _ => None
    }
  }
  if namespace == "Test" {
    return match name {
      case "assert" => Some(defaultedCallSignature(
        ["condition", "message"],
        [false, true],
      ))
      case "assertEq" | "assertNe" => Some(requiredCallSignature(
        ["actual", "expected"],
        false,
      ))
      case "assertContains" => Some(requiredCallSignature(
        ["text", "needle"],
        false,
      ))
      case "assertOk" | "assertErr" | "assertSome" | "assertNone" =>
        Some(requiredCallSignature(["value"], false))
      case "assertGolden" => Some(requiredCallSignature(
        ["path", "actual"],
        false,
      ))
      case _ => None
    }
  }
  None
}

function containerReceiverCallSignature(
  receiver: TypeValue,
  name: string,
) -> Option<CallSignature> {
  if receiver.kind != "constructor" {
    return None
  }
  if receiver.name == "Option" {
    return match name {
      case "okOr" => Some(requiredCallSignature(["error"], false))
      case "okOrElse" | "map" | "flatMap" =>
        Some(requiredCallSignature(["f"], false))
      case _ => None
    }
  }
  if receiver.name == "Result" {
    return match name {
      case "map" | "flatMap" => Some(requiredCallSignature(["f"], false))
      case _ => None
    }
  }
  if receiver.name == "Array" {
    return match name {
      case "get" => Some(requiredCallSignature(["i"], false))
      case "slice" => Some(requiredCallSignature(["start", "end"], false))
      case "map" | "sortedBy" | "filter" | "sortBy" | "retain" =>
        Some(requiredCallSignature(["f"], false))
      case "join" => Some(requiredCallSignature(["sep"], false))
      case "reduce" => Some(requiredCallSignature(["initial", "f"], false))
      case "indexOf" | "push" => Some(requiredCallSignature(["x"], false))
      case "insert" => Some(requiredCallSignature(
        ["index", "value"],
        false,
      ))
      case "removeAt" => Some(requiredCallSignature(["index"], false))
      case "sorted" | "pop" | "clear" | "reverse" | "sort" =>
        Some(requiredCallSignature([], false))
      case _ => None
    }
  }
  if receiver.name == "Map" {
    return match name {
      case "insert" => Some(requiredCallSignature(["k", "v"], false))
      case "get" | "remove" | "containsKey" =>
        Some(requiredCallSignature(["k"], false))
      case "getOr" => Some(requiredCallSignature(["k", "default"], false))
      case "isEmpty" | "clear" => Some(requiredCallSignature([], false))
      case "update" => Some(requiredCallSignature(
        ["k", "initial", "f"],
        false,
      ))
      case "mapValues" | "filter" =>
        Some(requiredCallSignature(["f"], false))
      case _ => None
    }
  }
  if receiver.name == "Set" {
    return match name {
      case "add" | "remove" | "contains" =>
        Some(requiredCallSignature(["x"], false))
      case "union" | "intersection" | "difference" =>
        Some(requiredCallSignature(["other"], false))
      case "isEmpty" | "toArray" | "clear" =>
        Some(requiredCallSignature([], false))
      case _ => None
    }
  }
  None
}

function scalarReceiverCallSignature(
  receiver: TypeValue,
  name: string,
) -> Option<CallSignature> {
  if (receiver.kind == "primitive" || receiver.kind == "literal") &&
    receiver.name == "int" {
    return match name {
      case "atLeast" => Some(requiredCallSignature(["min"], false))
      case "atMost" => Some(requiredCallSignature(["max"], false))
      case _ => None
    }
  }
  if (receiver.kind == "primitive" || receiver.kind == "literal") &&
    receiver.name == "string" {
    return match name {
      case "startsWith" => Some(requiredCallSignature(["prefix"], false))
      case "endsWith" => Some(requiredCallSignature(["suffix"], false))
      case "contains" | "indexOf" | "lastIndexOf" =>
        Some(requiredCallSignature(["sub"], false))
      case "codePointAt" => Some(requiredCallSignature(["i"], false))
      case "split" => Some(requiredCallSignature(["sep"], false))
      case "slice" => Some(requiredCallSignature(["start", "end"], false))
      case "replace" => Some(requiredCallSignature(["old", "new"], false))
      case "scalars" | "trim" | "trimStart" | "trimEnd" | "byteLength" =>
        Some(requiredCallSignature([], false))
      case _ => None
    }
  }
  None
}

function runtimeReceiverCallSignature(
  receiver: TypeValue,
  name: string,
) -> Option<CallSignature> {
  if receiver.kind == "file" {
    return match name {
      case "write" => Some(requiredCallSignature(["s"], false))
      case "read" | "close" => Some(requiredCallSignature([], false))
      case _ => None
    }
  }
  if receiver.kind == "json-value" {
    return match name {
      case "get" => Some(requiredCallSignature(["key"], false))
      case "at" => Some(requiredCallSignature(["index"], false))
      case "kind" | "isNull" | "asString" | "asBool" | "asInt" |
        "numberText" | "length" | "asArray" | "keys" | "values" =>
        Some(requiredCallSignature([], false))
      case _ => None
    }
  }
  if receiver.kind == "bytes" {
    return match name {
      case "get" => Some(requiredCallSignature(["index"], false))
      case "slice" => Some(requiredCallSignature(["start", "end"], false))
      case "decodeUtf8" | "toHex" | "toBase64" | "length" |
        "isEmpty" | "toArray" => Some(requiredCallSignature([], false))
      case _ => None
    }
  }
  if receiver.kind == "byte-buffer" {
    return match name {
      case "get" => Some(requiredCallSignature(["index"], false))
      case "set" => Some(requiredCallSignature(["index", "value"], false))
      case "fill" => Some(requiredCallSignature(
        ["start", "length", "value"],
        false,
      ))
      case "copy" => Some(requiredCallSignature(
        ["source", "sourceStart", "targetStart", "length"],
        false,
      ))
      case "length" | "toBytes" => Some(requiredCallSignature([], false))
      case _ => None
    }
  }
  if receiver.kind == "path" {
    return match name {
      case "join" => Some(requiredCallSignature(["child"], false))
      case "withExtension" => Some(requiredCallSignature(["ext"], false))
      case "parent" | "fileName" | "extension" | "normalize" | "toString" =>
        Some(requiredCallSignature([], false))
      case _ => None
    }
  }
  if receiver.kind == "regex" {
    return match name {
      case "isMatch" | "find" | "findAll" | "split" =>
        Some(requiredCallSignature(["text"], false))
      case "replaceAll" => Some(requiredCallSignature(
        ["text", "replacement"],
        false,
      ))
      case _ => None
    }
  }
  if receiver.kind == "url" {
    return match name {
      case "scheme" | "path" | "toString" | "host" | "fragment" | "query" =>
        Some(requiredCallSignature([], false))
      case _ => None
    }
  }
  if receiver.kind == "date" {
    return match name {
      case "addDays" => Some(requiredCallSignature(["days"], false))
      case "toIso" | "year" | "month" | "day" =>
        Some(requiredCallSignature([], false))
      case _ => None
    }
  }
  if receiver.kind == "big-int" {
    return match name {
      case "toString" => Some(requiredCallSignature(["radix"], false))
      case "div" | "mod" => Some(requiredCallSignature(["other"], false))
      case "toInt" => Some(requiredCallSignature([], false))
      case _ => None
    }
  }
  if receiver.kind == "decimal" {
    return match name {
      case "round" => Some(defaultedCallSignature(
        ["scale", "mode"],
        [false, true],
      ))
      case "div" => Some(defaultedCallSignature(
        ["other", "scale", "mode"],
        [false, false, true],
      ))
      case "toString" | "scale" | "toInt" =>
        Some(requiredCallSignature([], false))
      case _ => None
    }
  }
  None
}

export function builtinReceiverCallSignature(
  receiver: TypeValue,
  name: string,
  languageMode: string = "topaz-5.20",
) -> Option<CallSignature> {
  if languageMode == "topaz-5.21" {
    if receiver.name == "int" {
      if name == "and" || name == "or" || name == "xor" { return Some(requiredCallSignature(["other"], false)) }
      if name == "shift" { return Some(requiredCallSignature(["count"], false)) }
      if name == "toBigInt" || name == "toDecimal" { return Some(requiredCallSignature([], false)) }
    }
    if receiver.name == "string" && name == "encodeUtf8" { return Some(requiredCallSignature([], false)) }
    if receiver.kind == "constructor" && (receiver.name == "Set" || receiver.name == "Range") {
      if name == "map" || name == "filter" { return Some(requiredCallSignature(["f"], false)) }
      if name == "reduce" { return Some(requiredCallSignature(["initial", "f"], false)) }
    }
    if receiver.kind == "constructor" && receiver.name == "Result" {
      if name == "mapErr" { return Some(requiredCallSignature(["f"], false)) }
      if name == "unwrapOr" { return Some(requiredCallSignature(["default"], false)) }
    }
    if receiver.kind == "constructor" && receiver.name == "Array" && receiver.arguments.length == 1 && stringElementType(receiver.arguments[0]) {
      if name == "hasFlag" || name == "option" || name == "options" { return Some(requiredCallSignature(["name"], false)) }
      if name == "positionals" { return Some(requiredCallSignature([], false)) }
    }
    if receiver.kind == "bytes" {
      if name == "concat" { return Some(requiredCallSignature(["b"], false)) }
      if name == "hmacSha256" { return Some(requiredCallSignature(["message"], false)) }
      if name == "zstdCompress" { return Some(defaultedCallSignature(["level"], [true])) }
      if name == "sha256" || name == "sha512" || name == "crc32" || name == "gzipCompress" || name == "gzipDecompress" || name == "deflateCompress" || name == "deflateFixedCompress" || name == "zlibFixedCompress" || name == "reedSolomon255223Protect" || name == "deflateDecompress" || name == "zstdDecompress" { return Some(requiredCallSignature([], false)) }
    }
    if (receiver.kind == "json-value" && name == "decode") || (receiver.kind == "toml-value" && name == "toJson") { return Some(requiredCallSignature([], false)) }
    if lengthUnit(receiver) != "" {return if name == "resolve" {Some(requiredCallSignature(["fontSize"],false))} else {Some(requiredCallSignature([],false))}}
    if receiver.name == "float" {
      if name == "atMost" || name == "atLeast" { return Some(requiredCallSignature(["b"], false)) }
      if name == "trunc" || name == "floor" || name == "ceil" || name == "round" || name == "sqrt" || name == "abs" || name == "sin" || name == "cos" || name == "tan" || name == "isNaN" || name == "isFinite" { return Some(requiredCallSignature([], false)) }
    }
    if receiver.name == "int" && (name == "toFloat" || name == "toCodePoint") { return Some(requiredCallSignature([], false)) }
    if receiver.name == "string" {
      if name == "parseFloat" || name == "toInt" { return Some(requiredCallSignature([], false)) }
      if name == "toIntRadix" { return Some(requiredCallSignature(["radix"], false)) }
    }
  }
  if receiver.kind == "union" {
    for member in receiver.members {
      match builtinReceiverCallSignature(member, name, languageMode) {
        case Some(found) => return Some(found)
        case None => ()
      }
    }
    return None
  }
  match containerReceiverCallSignature(receiver, name) {
    case Some(found) => return Some(found)
    case None => ()
  }
  match scalarReceiverCallSignature(receiver, name) {
    case Some(found) => return Some(found)
    case None => ()
  }
  runtimeReceiverCallSignature(receiver, name)
}


export function staticBuiltinDataCallSignature(namespace: string, name: string) -> Option<CallSignature> {
  match builtinNamespaceFamily(namespace) {
    case "collection" => collectionStaticCallSignature(namespace, name)
    case "numeric-binary" => numericBinaryStaticCallSignature(namespace, name)
    case "host" => hostStaticCallSignature(namespace, name)
    case "structured-data" => structuredDataStaticCallSignature(namespace, name)
    case "scalar" => scalarTestStaticCallSignature(namespace, name)
    case _ => None
  }
}

