export function memberType(
  state: CheckerState,
  moduleIndex: int,
  object: TypeValue,
  name: string,
) -> TypeValue {
  let unit = lengthUnit(object)
  if state.languageMode == "topaz-5.21" && unit != "" {
    if unit == "Em" { return if name == "resolve" { functionType([lengthType("Pt")],[],lengthType("Pt")) } else { emptyType("unknown") } }
    return match name {
      case "toPt" => functionType([],[],lengthType("Pt"))
      case "toMm" => functionType([],[],lengthType("Mm"))
      case "toCm" => functionType([],[],lengthType("Cm"))
      case "toIn" => functionType([],[],lengthType("In"))
      case "scaledPoints" => functionType([],[],primitive("int"))
      case "toMilliPoints" => if unit == "Pt" { functionType([],[],primitive("int")) } else { emptyType("unknown") }
      case _ => emptyType("unknown")
    }
  }
  if state.languageMode == "topaz-5.21" && (object.kind == "primitive" || object.kind == "literal") {
    if object.name == "float" {
      return match name {
        case "trunc" | "floor" | "ceil" | "round" => functionType([], [], primitive("int"))
        case "abs" | "sin" | "cos" | "tan" => functionType([], [], primitive("float"))
        case "sqrt" => functionType([], [], constructor("Result", [primitive("float"), primitive("string")]))
        case "isNaN" | "isFinite" => functionType([], [], primitive("bool"))
        case "atMost" | "atLeast" => functionType([primitive("float")], [], primitive("float"))
        case _ => emptyType("unknown")
      }
    }
    if object.name == "int" && (name == "and" || name == "or" || name == "xor" || name == "shift") { return functionType([primitive("int")], [], primitive("int")) }
    if object.name == "int" && name == "toBigInt" { return movedReceiverType("BigInt", "fromInt") }
    if object.name == "int" && name == "toDecimal" { return movedReceiverType("Decimal", "fromInt") }
    if object.name == "string" && name == "encodeUtf8" { return movedReceiverType("Bytes", "encodeUtf8") }
    if object.name == "int" && name == "toFloat" { return functionType([], [], primitive("float")) }
    if object.name == "int" && name == "toCodePoint" { return functionType([], [], constructor("Option", [primitive("string")])) }
    if object.name == "string" {
      if name == "parseFloat" { return functionType([], [], constructor("Result", [primitive("float"), primitive("string")])) }
      if name == "toInt" { return functionType([], [], constructor("Option", [primitive("int")])) }
      if name == "toIntRadix" { return functionType([primitive("int")], [], constructor("Option", [primitive("int")])) }
    }
  }
  match declaredMemberType(state, moduleIndex, object, name) {
    case Some(found) => return found
    case None => ()
  }
  if state.languageMode == "topaz-5.21" {
    if object.kind == "constructor" && (object.name == "Set" || object.name == "Range") && (name == "map" || name == "filter" || name == "reduce") {
      return arrayMemberType(constructor("Array", [if object.name == "Range" { primitive("int") } else { typeArgument(object, 0) }]), name)
    }
    if object.kind == "constructor" && object.name == "Result" {
      if name == "unwrapOr" { let value = typeArgument(object, 0); return functionType([value], [], value) }
      if name == "mapErr" { let error = rigid("F", "builtin::Result.mapErr"); return functionType([functionType([typeArgument(object, 1)], [], error)], [], constructor("Result", [typeArgument(object, 0), error])) }
    }
    if object.kind == "constructor" && object.name == "Array" && stringElementType(typeArgument(object, 0)) && (name == "hasFlag" || name == "option" || name == "options" || name == "positionals") { return movedReceiverType("Cli", name) }
    if object.kind == "bytes" {
      if name == "concat" { return movedReceiverType("Bytes", name) }
      if name == "sha256" || name == "sha512" || name == "hmacSha256" || name == "crc32" { return movedReceiverType("Hash", name) }
      if name == "gzipCompress" || name == "gzipDecompress" || name == "deflateCompress" || name == "deflateFixedCompress" || name == "zlibFixedCompress" || name == "reedSolomon255223Protect" || name == "deflateDecompress" || name == "zstdCompress" || name == "zstdDecompress" { return movedReceiverType("Codec", name) }
    }
    if object.kind == "toml-value" && name == "toJson" { return movedReceiverType("TOML", name) }
    if object.kind == "json-value" && name == "decode" { return functionType([], [], constructor("Result", [rigid("T", "builtin::JSONValue.decode"), primitive("string")])) }
  }
  if (object.kind == "primitive" || object.kind == "literal") &&
    object.name == "int" {
    return match name {
      case "atLeast" | "atMost" => functionType(
        [primitive("int")],
        [],
        primitive("int"),
      )
      case _ => emptyType("unknown")
    }
  }
  if object.kind == "constructor" && object.name == "Option" {
    return optionMemberType(object, name)
  }
  if object.kind == "constructor" && object.name == "Result" {
    return resultMemberType(object, name)
  }
  if object.kind == "constructor" && object.name == "Array" {
    return arrayMemberType(object, name)
  }
  if object.kind == "constructor" && object.name == "Set" {
    return setMemberType(object, name)
  }
  if object.kind == "constructor" && object.name == "Map" {
    return mapMemberType(object, name)
  }
  if (object.kind == "primitive" || object.kind == "literal") &&
    object.name == "string" {
    return stringMemberType(name)
  }
  if object.kind == "bytes" {
    return bytesMemberType(name)
  }
  if object.kind == "byte-buffer" {
    return byteBufferMemberType(name)
  }
  if object.kind == "file" {
    return fileMemberType(name)
  }
  if object.kind == "path" {
    return pathMemberType(name)
  }
  if object.kind == "regex" {
    return regexMemberType(name)
  }
  if object.kind == "url" {
    return urlMemberType(name)
  }
  if object.kind == "date" {
    return dateMemberType(name)
  }
  if object.kind == "big-int" {
    return bigIntMemberType(name)
  }
  if object.kind == "decimal" {
    return decimalMemberType(name)
  }
  if object.kind == "json-value" {
    return jsonValueMemberType(name)
  }
  if object.kind == "match" || object.kind == "template" {
    return dataProjectionMemberType(object, name)
  }
  if object.kind == "rigid" || object.kind == "foreign" {
    let projection = "MemberOf<{typeText(object)}, {name}>"
    return rigid(
      projection,
      "projection:{projection}",
    )
  }
  if object.kind == "union" {
    let mut projected: Array<TypeValue> = []
    for member in object.members {
      let found = memberType(state, moduleIndex, member, name)
      // A concrete missing arm invalidates the projection. Gradual arms stay
      // gradual; rigid arms retain their MemberOf projection.
      if found.kind == "unknown" && !hasHole(member) {
        return emptyType("unknown")
      }
      projected.push(found)
    }
    return unionType(projected)
  }
  emptyType("unknown")
}

export function rigidOrUnionRigid(value: TypeValue) -> bool {
  if value.kind == "rigid" || value.kind == "foreign" {
    return true
  }
  if value.kind == "union" {
    for member in value.members {
      if rigidOrUnionRigid(member) {
        return true
      }
    }
  }
  false
}

export function rigidUnionMissingConcreteMember(
  state: CheckerState,
  moduleIndex: int,
  value: TypeValue,
  memberName: string,
) -> bool {
  if value.kind != "union" {
    return false
  }
  for arm in value.members {
    if arm.kind == "rigid" || arm.kind == "foreign" ||
      arm.kind == "unknown" || arm.kind == "inference-variable" ||
      rigidOrUnionRigid(arm) {
      continue
    }
    let declared = match declaredMemberType(state, moduleIndex, arm, memberName) {
      case Some(_) => true
      case None => false
    }
    if declared { continue }
    let receiverMethod = match receiverMethodType(
      state,
      moduleIndex,
      arm,
      memberName,
    ) {
      case Some(_) => true
      case None => false
    }
    if receiverMethod { continue }
    if memberType(state, moduleIndex, arm, memberName).kind == "unknown" {
      return true
    }
  }
  false
}

function collectionNamespaceMemberType(
  namespace: string,
  name: string,
) -> Option<TypeValue> {
  let bytes = emptyType("bytes")
  let textValue = primitive("string")
  let bytesResult = constructor("Result", [bytes, textValue])
  if namespace == "Array" || namespace == "Set" {
    let item = rigid("T", "builtin::{namespace}.of")
    return match name {
      case "of" => Some(functionType(
        [],
        [item],
        constructor(namespace, [item]),
      ))
      case _ => None
    }
  }
  if namespace == "Bytes" {
    return match name {
      case "empty" => Some(functionType([], [], bytes))
      case "encodeUtf8" => Some(functionType([textValue], [], bytes))
      case "fromArray" => Some(functionType(
        [constructor("Array", [primitive("int")])],
        [],
        bytesResult,
      ))
      case "fromHex" | "fromBase64" => Some(functionType(
        [textValue],
        [],
        bytesResult,
      ))
      case "concat" => Some(functionType([bytes, bytes], [], bytes))
      case _ => None
    }
  }
  if namespace == "ByteBuffer" {
    return match name {
      case "allocate" => Some(functionType(
        [primitive("int"), primitive("int")],
        [],
        emptyType("byte-buffer"),
      ))
      case "fromBytes" => Some(functionType(
        [bytes],
        [],
        emptyType("byte-buffer"),
      ))
      case _ => None
    }
  }
  if namespace == "Map" {
    let key = rigid("K", "builtin::Map.new")
    let value = rigid("V", "builtin::Map.new")
    return match name {
      case "new" => Some(functionType(
        [],
        [],
        constructor("Map", [key, value]),
      ))
      case "ofEntries" => Some(functionType(
        [constructor("Array", [structural(
          ["key", "value"],
          [key, value],
        )])],
        [],
        constructor("Map", [key, value]),
      ))
      case _ => None
    }
  }
  None
}

function numericAndBinaryNamespaceMemberType(
  namespace: string,
  name: string,
) -> Option<TypeValue> {
  let bytes = emptyType("bytes")
  let textValue = primitive("string")
  let bytesResult = constructor("Result", [bytes, textValue])
  if namespace == "Math" {
    let floatValue = primitive("float")
    return match name {
      case "sqrt" => Some(functionType(
        [floatValue],
        [],
        constructor("Result", [floatValue, textValue]),
      ))
      case "abs" | "floor" | "ceil" | "round" |
        "sin" | "cos" | "tan" => Some(functionType(
        [floatValue],
        [],
        floatValue,
      ))
      case "isNaN" | "isFinite" => Some(functionType(
        [floatValue],
        [],
        primitive("bool"),
      ))
      case "parseFloat" => Some(functionType(
        [textValue],
        [],
        constructor("Result", [floatValue, textValue]),
      ))
      case "min" | "max" => Some(functionType(
        [floatValue, floatValue],
        [],
        floatValue,
      ))
      case _ => None
    }
  }
  if namespace == "Codec" {
    return match name {
      case "zstdCompress" => Some(functionType(
        [bytes, primitive("int")],
        [],
        bytesResult,
      ))
      case "gzipCompress" |
        "gzipDecompress" |
        "deflateCompress" |
        "deflateFixedCompress" |
        "zlibFixedCompress" |
        "reedSolomon255223Protect" |
        "deflateDecompress" |
        "zstdDecompress" => Some(functionType([bytes], [], bytesResult))
      case _ => None
    }
  }
  if namespace == "Hash" {
    return match name {
      case "sha256" | "sha512" => Some(functionType([bytes], [], bytes))
      case "hmacSha256" => Some(functionType([bytes, bytes], [], bytes))
      case "crc32" => Some(functionType([bytes], [], primitive("int")))
      case _ => None
    }
  }
  None
}

function hostNamespaceMemberType(
