export function builtinNamespaceMemberType(
  namespace: string,
  name: string,
  languageMode: string = "topaz-5.20",
) -> Option<TypeValue> {
  if languageMode == "topaz-5.21" && removedStandardStatic(namespace, name) { return None }
  match builtinNamespaceFamily(namespace) {
    case "collection" => collectionNamespaceMemberType(namespace, name)
    case "numeric-binary" => numericAndBinaryNamespaceMemberType(namespace, name)
    case "host" => hostNamespaceMemberType(namespace, name)
    case "structured-data" => structuredDataNamespaceMemberType(namespace, name)
    case "scalar" => scalarNamespaceMemberType(namespace, name)
    case _ => None
  }
}

export function bindingIndex(bindings: Array<TypeBinding>, name: string) -> int {
  let mut index = 0
  for binding in bindings {
    if binding.name == name {
      return index
    }
    index += 1
  }
  -1
}

export function typeBindingKey(parameter: TypeValue) -> string {
  "{parameter.origin.byteLength()}:{parameter.origin}{parameter.name}"
}

export function scopeCallParameters(
  parameters: Array<TypeValue>,
  moduleIndex: int,
  node: SyntaxNode,
) -> Array<TypeValue> {
  let mut scoped: Array<TypeValue> = []
  for parameter in parameters {
    scoped.push(TypeValue {
      ...parameter,
      origin: "call-scheme:{moduleIndex}:{node.lo}:{node.hi}:{parameter.origin}",
    })
  }
  scoped
}

export function instantiateCallType(
  value: TypeValue,
  parameters: Array<TypeValue>,
  scoped: Array<TypeValue>,
) -> TypeValue {
  let mut bindings: Array<TypeBinding> = []
  let mut index = 0
  for parameter in parameters {
    match scoped.get(index) {
      case Some(variable) => bindTypeVariable(bindings, parameter, variable, false)
      case None => ()
    }
    index += 1
  }
  applyBindings(value, bindings)
}

export function bindTypeVariable(
  bindings: Array<TypeBinding>,
  parameter: TypeValue,
  typeValue: TypeValue,
  widenLiteral: bool,
) -> () {
  let mut target = bindings
  let name = typeBindingKey(parameter)
  let index = bindingIndex(target, name)
  if index >= 0 {
    return ()
  }
  target.push(TypeBinding {
    name: name,
    typeValue: if widenLiteral { widen(typeValue) } else { typeValue },
  })
}

function collectTypeArrayBindings(
  expected: Array<TypeValue>,
  actual: Array<TypeValue>,
  bindings: Array<TypeBinding>,
  widenLiteral: bool,
  parameters: Array<TypeValue>,
) -> () {
  let mut index = 0
  for nested in expected {
    match actual.get(index) {
      case Some(found) => collectTypeBindings(
        nested,
        found,
        bindings,
        widenLiteral,
        parameters,
      )
      case None => ()
    }
    index += 1
  }
  ()
}

export function collectTypeBindings(
  expected: TypeValue,
  actual: TypeValue,
  bindings: Array<TypeBinding>,
  widenLiteral: bool,
  parameters: Array<TypeValue>,
) -> () {
  // An unsolved expected component provides no evidence for a scheme slot.
  // Actual unknown inputs still retain their uncertainty during input binding.
  if !widenLiteral && actual.kind == "unknown" { return () }
  // This marker carries an unsolved call slot, not evidence about its type.
  // A concrete sibling (for example the callback result) may still solve it.
  if actual.kind == "unknown" && actual.origin == "generic-call-expectation" {
    return ()
  }
  if expected.kind == "rigid" {
    // Only this invocation's instantiated scheme is solvable. Caller rigids
    // remain rigid even during recursion through the same declaration.
    let mut owned = false
    for parameter in parameters {
      if typeEqual(expected, parameter) { owned = true }
    }
    if !owned { return () }
    // Stage 0 leaves an Unknown-fed scheme slot empty. Self-host builtin
    // generics are rigid values, so binding Unknown preserves the same
    // unresolved result as an observable hole.
    if typeEqual(expected, actual) || typeContains(
      actual,
      (component: TypeValue) => typeEqual(component, expected),
    ) {
      return ()
    }
    bindTypeVariable(bindings, expected, actual, widenLiteral)
    return ()
  }
  if expected.kind == "union" {
    for member in expected.members {
      collectTypeBindings(member, actual, bindings, widenLiteral, parameters)
    }
    return ()
  }
  if expected.kind == "constructor" && actual.kind == "constructor" &&
    expected.name == actual.name &&
    expected.arguments.length == actual.arguments.length {
    return collectTypeArrayBindings(
      expected.arguments,
      actual.arguments,
      bindings,
      widenLiteral,
      parameters,
    )
  }
  if (expected.kind == "enum" || expected.kind == "nominal-record" ||
    expected.kind == "newtype") &&
    expected.kind == actual.kind && expected.identity == actual.identity &&
    expected.origin == actual.origin &&
    expected.arguments.length == actual.arguments.length {
    return collectTypeArrayBindings(
      expected.arguments,
      actual.arguments,
      bindings,
      widenLiteral,
      parameters,
    )
  }
  if expected.kind == "record" && actual.kind == "record" &&
    expected.fields.length == actual.fields.length {
    let mut index = 0
    while index < expected.fields.length {
      match [expected.fieldNames.get(index), actual.fieldNames.get(index)] {
        case [Some(expectedName), Some(actualName)] => if expectedName ==
          actualName {
          match [expected.fields.get(index), actual.fields.get(index)] {
            case [Some(expectedField), Some(actualField)] => collectTypeBindings(
              expectedField,
              actualField,
              bindings,
              widenLiteral,
              parameters,
            )
            case _ => ()
          }
        }
        case _ => ()
      }
      index += 1
    }
    return ()
  }
  if expected.kind == "function" && actual.kind == "function" {
    collectTypeArrayBindings(
      expected.parameters,
      actual.parameters,
      bindings,
      widenLiteral,
      parameters,
    )
    match [expected.variadic.get(0), actual.variadic.get(0)] {
      case [Some(expectedVariadic), Some(actualVariadic)] => collectTypeBindings(
        expectedVariadic,
        actualVariadic,
        bindings,
        widenLiteral,
        parameters,
      )
      case _ => ()
    }
    match [expected.result.get(0), actual.result.get(0)] {
      case [Some(expectedResult), Some(actualResult)] => collectTypeBindings(
        expectedResult,
        actualResult,
        bindings,
        widenLiteral,
        parameters,
      )
      case _ => ()
    }
  }
  ()
}

function typeBindingComponentReplacement(
  value: TypeValue,
  bindings: Array<TypeBinding>,
) -> Option<TypeValue> {
  if value.kind != "rigid" {
    return None
  }
  for binding in bindings {
    if typeBindingKey(value) == binding.name {
      return Some(binding.typeValue)
    }
  }
  Some(value)
}

export function applyBindings(value: TypeValue, bindings: Array<TypeBinding>) -> TypeValue {
  transformTypeComponents(
    value,
    (component: TypeValue) => typeBindingComponentReplacement(
      component,
      bindings,
    ),
  )
}

function nominalDefinitionModule(
  state: CheckerState,
  moduleIndex: int,
  value: TypeValue,
) -> int {
  match recordDefinitionForType(state, moduleIndex, value) {
    case Some(definition) => return definition.moduleIndex
    case None => ()
  }
  match enumDefinitionForType(state, moduleIndex, value) {
    case Some(definition) => return definition.moduleIndex
    case None => ()
  }
  match newtypeDefinitionForType(state, moduleIndex, value) {
    case Some(definition) => return definition.moduleIndex
    case None => ()
  }
  -1
}

export function typeConforms(
  state: CheckerState,
  moduleIndex: int,
  value: TypeValue,
  protocol: string,
) -> bool {
  let widened = widen(value)
  if widened.kind == "rigid" {
    return rigidProtocolBound(state, widened, protocol)
  }
  if widened.kind == "nominal-record" ||
    widened.kind == "enum" || widened.kind == "newtype" ||
    widened.kind == "foreign" {
    let definitionModule = nominalDefinitionModule(
      state,
      moduleIndex,
      widened,
    )
    if widened.kind == "foreign" {
      for conformance in state.conformances {
        let owner = moduleIdentityAt(state, conformance.moduleIndex)
        if conformance.protocol == protocol &&
          (widened.identity == "{owner}::{conformance.typeName}" ||
            widened.origin == owner && widened.identity == conformance.typeName) {
          return conformance.moduleIndex == moduleIndex || conformance.derived
        }
      }
      return false
    }
    let index = protocolConformanceIndex(
      state,
      definitionModule,
      widened.identity,
      protocol,
    )
    return match state.conformances.get(index) {
      case Some(conformance) => definitionModule == moduleIndex || conformance.derived
      case None => false
    }
  }
  false
}

export function conformanceTypeText(
  state: CheckerState,
  moduleIndex: int,
  value: TypeValue,
) -> string {
  let owner = nominalDefinitionModule(state, moduleIndex, value)
  if owner >= 0 && owner != moduleIndex {
    return "{moduleIdentityAt(state, owner)}::{typeText(value)}"
  }
  typeText(value)
}

export function checkFunctionBounds(
  state: CheckerState,
  moduleIndex: int,
  node: SyntaxNode,
  definition: FunctionDefinition,
  parameters: Array<TypeValue>,
  bindings: Array<TypeBinding>,
) -> () {
  for bound in definition.bounds {
    let mut index = -1
    for parameter in parameters {
      if parameter.name == bound.parameterName {
        index = bindingIndex(bindings, typeBindingKey(parameter))
      }
    }
    if index >= 0 {
      match bindings.get(index) {
        case Some(binding) => if !typeConforms(
          state,
          moduleIndex,
          binding.typeValue,
          bound.protocol,
        ) {
          addDiagnostic(
            state,
            moduleIndex,
            "TPZ5522",
            "`{conformanceTypeText(state, moduleIndex, binding.typeValue)}` does not satisfy protocol bound `{bound.protocol}`",
            "",
            node,
          )
        }
        case None => ()
      }
    }
  }
  ()
}

export function protocolCallResult(
  service: CheckerService,
  state: CheckerState,
  moduleIndex: int,
  source: Bytes,
  callee: SyntaxNode,
) -> Option<TypeValue> {
  if callee.kind != "expression/member" {
    return None
  }
  let object = match child(callee, "object") {
    case Some(found) => found
    case None => return None
  }
  let field = match child(callee, "field") {
    case Some(found) => text(source, found)
    case None => return None
  }
  if !serviceBuiltinNamespaceObject(service, state, moduleIndex, source, object) {
    return None
  }
  let protocol = text(source, object)
  match protocolStaticMemberType(protocol, field) {
    case Some(method) => return method.result.get(0)
    case None => ()
  }
  if protocol == "JSON" && field == "stringify" {
    return Some(constructor(
      "Result",
      [primitive("string"), primitive("string")],
    ))
  }
  None
}

export function protocolStaticMemberType(
  namespace: string,
  member: string,
) -> Option<TypeValue> {
  match builtinProtocolDefinition(namespace) {
    case Some(definition) => match protocolMethodDefinition(definition, member) {
      case Some(method) => Some(method.typeValue)
      case None => None
    }
    case None => None
  }
}

export function rigidProtocolBound(
  state: CheckerState,
  value: TypeValue,
  protocol: string,
) -> bool {
  if value.kind != "rigid" {
    return false
  }
  for definition in state.functions {
    let mut parameterIndex = 0
    for parameterName in definition.typeParameters {
      if parameterName == value.name {
        match definition.typeParameterOrigins.get(parameterIndex) {
          case Some(parameterOrigin) => if parameterOrigin == value.origin {
            for bound in definition.bounds {
              if bound.parameterName == value.name &&
                bound.protocol == protocol {
                return true
              }
            }
          }
          case None => ()
        }
      }
      parameterIndex += 1
    }
  }
  false
}

