  }).typeValue
}

export function serviceCheckBlockExpected(
  service: CheckerService,
  state: CheckerState,
  moduleIndex: int,
  source: Bytes,
  block: SyntaxNode,
  expected: TypeValue,
) -> TypeValue {
  serviceCheckBlockExpectedResult(service, state, moduleIndex, source, block, expected, true)
}

export function serviceCheckBlockExpectedResult(
  service: CheckerService,
  state: CheckerState,
  moduleIndex: int,
  source: Bytes,
  block: SyntaxNode,
  expected: TypeValue,
  checkResult: bool,
) -> TypeValue {
  let mut contexts = state.expectedExpressions
  contexts.push(ExpectedExpressionContext {
    kind: block.kind, lo: block.lo, hi: block.hi,
    typeValue: expected, checkResult: checkResult,
  })
  let result = service(state, CheckerRequest {
    kind: "check-block-expected",
    moduleIndex: moduleIndex,
    source: source,
    node: block,
    typeValue: expected,
  }).typeValue
  contexts.pop()
  result
}

