export function structural(fieldNames: Array<string>, fields: Array<TypeValue>) -> TypeValue {
  let mut orderedNames: Array<string> = []
  let mut orderedFields: Array<TypeValue> = []
  let mut sourceIndex = 0
  for name in fieldNames {
    let field = match fields.get(sourceIndex) {
      case Some(found) => found
      case None => emptyType("unknown")
    }
    let mut inserted = false
    let mut index = 0
    while index < orderedNames.length {
      let existing = match orderedNames.get(index) {
        case Some(found) => found
        case None => name
      }
      if name < existing {
        orderedNames.insert(index, name)
        orderedFields.insert(index, field)
        inserted = true
        break
      }
      index += 1
    }
    if !inserted {
      orderedNames.push(name)
      orderedFields.push(field)
    }
    sourceIndex += 1
  }
  TypeValue {
    kind: "record",
    name: "",
    value: "",
    identity: "",
    origin: "",
    arguments: [],
    members: [],
    fieldNames: orderedNames,
    fields: orderedFields,
    parameters: [],
    variadic: [],
    result: [],
  }
}


// Mutable aggregate contents are facts for one evaluation phase, not cached
// runtime values. Calls end their validity; callable checks restore the parent.
export function constantRenderEpoch(state: CheckerState) -> int {
  match state.constantRenderEpoch.get(0) { case Some(value) => value; case None => 0 }
}
export function advanceConstantRenderEpoch(state: CheckerState) -> () {
  let current = constantRenderEpoch(state)
  let mut epoch = state.constantRenderEpoch
  epoch[0] = current + 1
}
export function restoreConstantRenderEpoch(state: CheckerState, saved: int) -> () {
  let mut epoch = state.constantRenderEpoch
  epoch[0] = saved
}

export function lengthType(unit: string) -> TypeValue {
  nominal("newtype", "builtin:Length", [nominal("newtype", "builtin:{unit}", [])])
}
export function lengthUnit(value: TypeValue) -> string {
  if value.kind != "newtype" || value.identity != "builtin:Length" || value.origin != "" || value.arguments.length != 1 { return "" }
  let unit = value.arguments[0]
  if unit.kind != "newtype" || unit.origin != "" || unit.arguments.length != 0 { return "" }
  match unit.identity { case "builtin:Pt" => "Pt"; case "builtin:Mm" => "Mm"; case "builtin:Cm" => "Cm"; case "builtin:In" => "In"; case "builtin:Em" => "Em"; case _ => "" }
}

