  namedNominalTarget,
  newtypeDefinitionIndex,
  protocolDefinitionIndex,
  recordDefinitionIndex,
  referenceFor,
  registerTypeParameters,
  replaceEnumDefinition,
  replaceNewtypeDefinition,
  replaceRecordDefinition,
  text,
  typeParameterNames,
  typeParameterOrigin,
  unwrapExport,
}

function primitiveNamedType(name: string) -> Option<TypeValue> {
  match name {
    case "int" => Some(primitive("int"))
    case "float" => Some(primitive("float"))
    case "string" => Some(primitive("string"))
    case "bool" => Some(primitive("bool"))
    case _ => None
  }
}

function terminalNamedType(name: string) -> Option<TypeValue> {
  match name {
    case "template" => Some(emptyType("template"))
    case "JSONValue" => Some(emptyType("json-value"))
    case "File" => Some(emptyType("file"))
    case "Bytes" => Some(emptyType("bytes"))
    case "ByteBuffer" => Some(emptyType("byte-buffer"))
    case "Path" => Some(emptyType("path"))
    case "Regex" => Some(emptyType("regex"))
    case "Match" => Some(emptyType("match"))
    case "TOMLValue" => Some(emptyType("toml-value"))
    case "URL" => Some(emptyType("url"))
    case "Date" => Some(emptyType("date"))
    case "BigInt" => Some(emptyType("big-int"))
    case "Decimal" => Some(emptyType("decimal"))
    case "RoundingMode" => Some(emptyType("rounding-mode"))
    case _ => None
  }
}

function builtinTypeConstructorArity(name: string) -> int {
  match name {
    case "Array" | "Set" | "Option" => 1
    case "Map" | "Result" => 2
    case _ => -1
  }
}

export function addTypeArgumentArityDiagnostic(
  state: CheckerState,
  moduleIndex: int,
  subject: string,
  expected: int,
  found: int,
  node: SyntaxNode,
) -> () {
  let suffix = if expected == 1 { "" } else { "s" }
  addDiagnostic(
    state,
    moduleIndex,
    "TPZ5022",
    "{subject} takes {expected} type argument{suffix}, found {found}",
    "",
    node,
  )
}

function typeParameterComponentReplacement(
  value: TypeValue,
  names: Array<string>,
  arguments: Array<TypeValue>,
) -> Option<TypeValue> {
  if value.kind != "rigid" {
    return None
  }
  let mut index = 0
  for name in names {
    if value.name == name {
      return Some(match arguments.get(index) {
        case Some(found) => found
        case None => emptyType("unknown")
      })
    }
    index += 1
  }
  Some(value)
}

export function substitute(
  value: TypeValue,
  names: Array<string>,
  arguments: Array<TypeValue>,
) -> TypeValue {
  transformTypeComponents(
    value,
    (component: TypeValue) => typeParameterComponentReplacement(
      component,
      names,
      arguments,
    ),
  )
}

function typeDeclarationForName(
  state: CheckerState,
  moduleIndex: int,
  name: string,
) -> Option<PreviewResolvedDeclaration> {
  for declaration in state.resolved.declarations {
    if declaration.moduleIndex == moduleIndex &&
      declaration.namespace == "type" && declaration.name == name {
      return Some(declaration)
    }
  }
  None
}

export function targetType(
  state: CheckerState,
  moduleIndex: int,
  node: SyntaxNode,
) -> TypeTarget {
  let sourceName = match moduleAt(state, moduleIndex) {
    case Some(module) => text(module.source, node)
    case None => ""
  }
  match referenceFor(state, moduleIndex, node.lo, node.hi) {
    case Some(reference) => {
      let mut target = TypeTarget {
        moduleIndex: if reference.targetModuleIndex >= 0 {
          reference.targetModuleIndex
        } else {
          moduleIndex
        },
        name: if reference.targetName != "" {
          reference.targetName
        } else {
          sourceName
        },
      }
      match declarationFor(
        state,
        reference.targetModuleIndex,
        reference.targetLo,
        reference.targetHi,
      ) {
        case Some(declaration) => {
          if declaration.targetModule != "" {
            target = TypeTarget {
              moduleIndex: moduleIndexByIdentity(
                state,
                declaration.targetModule,
              ),
              name: target.name,
            }
          }
          if declaration.targetName != "" {
            target = TypeTarget {
              moduleIndex: target.moduleIndex,
              name: declaration.targetName,
            }
          }
        }
        case None => ()
      }
      target
    }
    case None => match typeDeclarationForName(state, moduleIndex, sourceName) {
      case Some(declaration) => TypeTarget {
        moduleIndex: if declaration.targetModule != "" {
          moduleIndexByIdentity(state, declaration.targetModule)
        } else {
          moduleIndex
        },
        name: if declaration.targetName != "" {
          declaration.targetName
        } else {
          sourceName
        },
      }
      case None => TypeTarget {
        moduleIndex: moduleIndex,
        name: sourceName,
      }
    }
  }
}

function formLiteralType(state: CheckerState, moduleIndex: int, source: Bytes, node: SyntaxNode) -> TypeValue {
  for attr in node.attributes { if attr.name == "cooked" { return literal("string",attr.value) } }
  let kind = literalAttribute(node,"literalKind")
  let spelling = if kind == "" { text(source,node) } else { literalAttribute(node,"literalSpelling") }
  if kind == "bool" {
    return literal("bool", spelling)
  }
  if kind == "null" {
    return literal("null", "")
  }
  if kind == "float" {
    literal("float", match decodeDecimalFloatLiteral(spelling) {case Some(value)=>"{value}";case None=>""})
  } else {
    match decodeIntegerLiteral(spelling,false) {
      case Some(value) => literal("int", "{value}")
      case None => {
        addDiagnostic(state,moduleIndex,if state.languageMode == "topaz-5.21" { "TPZ5001" } else { "TPZ5022" },"integer literal type `{spelling}` is out of range","",node)
        emptyType("unknown")
      }
    }
  }
}

function formUnionType(
  service: CheckerService,
  state: CheckerState,
  moduleIndex: int,
  source: Bytes,
  node: SyntaxNode,
  parameters: Array<string>,
  origin: string,
) -> TypeValue {
  let mut members: Array<TypeValue> = []
  for member in children(node, "members") {
    members.push(formType(
      service,
      state,
      moduleIndex,
      source,
      member,
      parameters,
      origin,
    ))
  }
  unionType(members)
}

function formRecordType(
  service: CheckerService,
  state: CheckerState,
  moduleIndex: int,
  source: Bytes,
  node: SyntaxNode,
  parameters: Array<string>,
  origin: string,
) -> TypeValue {
  let mut names: Array<string> = []
  let mut values: Array<TypeValue> = []
  for field in children(node, "fields") {
    let name = match child(field, "name") {
      case Some(found) => text(source, found)
      case None => ""
    }
    if containsString(names, name) {
      addDiagnostic(
        state,
        moduleIndex,
        "TPZ5022",
        "record type declares field `{name}` twice",
        "",
        field,
      )
      continue
    }
    let value = match child(field, "type") {
      case Some(typeNode) => formType(
        service,
        state,
        moduleIndex,
        source,
        typeNode,
        parameters,
        origin,
      )
      case None => emptyType("unknown")
    }
    names.push(name)
    values.push(value)
  }
  structural(names, values)
}

function formFunctionType(
  service: CheckerService,
  state: CheckerState,
  moduleIndex: int,
  source: Bytes,
  node: SyntaxNode,
  parameters: Array<string>,
  origin: string,
) -> TypeValue {
  let mut fixed: Array<TypeValue> = []
  let mut variadic: Array<TypeValue> = []
  for parameter in children(node, "parameters") {
    let formed = match child(parameter, "type") {
      case Some(typeNode) => formType(
        service,
        state,
        moduleIndex,
        source,
        typeNode,
        parameters,
        origin,
      )
      case None => emptyType("unknown")
    }
    if boolAttribute(parameter, "variadic") {
      variadic.push(formed)
    } else {
      fixed.push(formed)
    }
  }
  let result = match child(node, "returnType") {
    case Some(typeNode) => formType(
      service,
      state,
      moduleIndex,
      source,
      typeNode,
      parameters,
      origin,
    )
    case None => primitive("unit")
  }
  functionType(fixed, variadic, result)
}

function formNamedType(
  service: CheckerService,
  state: CheckerState,
  moduleIndex: int,
  source: Bytes,
  node: SyntaxNode,
  parameters: Array<string>,
  origin: string,
) -> TypeValue {
  let nameNode = match child(node, "name") {
    case Some(found) => found
    case None => node
  }
  let name = text(source, nameNode)
  let argumentNodes = children(node, "arguments")
  let argumentCount = argumentNodes.length
  if state.languageMode == "topaz-5.21" && name == "Length" {
    if argumentCount == 1 {
      let written = formType(service,state,moduleIndex,source,argumentNodes[0],parameters,origin)
      if written.kind == "newtype" && written.origin == "" && written.arguments.length == 0 {
        let marker=written.identity.replace("builtin:","")
        if written.identity == "builtin:{marker}" && (marker == "Pt" || marker == "Mm" || marker == "Cm" || marker == "In" || marker == "Em") {return lengthType(marker)}
      }
    }
    addDiagnostic(state,moduleIndex,"TPZ5001","Length requires one compiler-owned Pt, Mm, Cm, In or Em marker","",nameNode)
    return emptyType("unknown")
  }
  if state.languageMode == "topaz-5.21" && (name == "Pt" || name == "Mm" || name == "Cm" || name == "In" || name == "Em") {
    if argumentCount != 0 { addTypeArgumentArityDiagnostic(state,moduleIndex,"unit marker `{name}`",0,argumentCount,nameNode) }
    return nominal("newtype","builtin:{name}",[])
  }
  if containsString(parameters, name) {
    if argumentCount > 0 {
      addDiagnostic(
        state,
        moduleIndex,
        "TPZ5022",
        "type parameter `{name}` takes no type arguments",
        "",
        nameNode,
      )
    }
    return rigid(name, typeParameterOrigin(state, moduleIndex, name, origin))
  }
  match activeTypeParameter(state, moduleIndex, name) {
    case Some(value) => {
      if argumentCount > 0 {
        addDiagnostic(
          state,
          moduleIndex,
          "TPZ5022",
          "type parameter `{name}` takes no type arguments",
          "",
          nameNode,
        )
      }
      return value
    }
    case None => ()
  }
  match primitiveNamedType(name) {
    case Some(value) => {
      if argumentCount > 0 {
        addDiagnostic(
          state,
          moduleIndex,
          "TPZ5022",
          "primitive type `{name}` takes no type arguments",
          "",
          nameNode,
        )
      }
      return value
    }
    case None => ()
  }
  match terminalNamedType(name) {
    case Some(value) => {
      if argumentCount > 0 {
        addDiagnostic(
          state,
          moduleIndex,
          "TPZ5022",
          "`{name}` takes no type arguments",
          "",
          nameNode,
        )
      }
      return value
    }
    case None => ()
  }
  let constructorArity = builtinTypeConstructorArity(name)
  if constructorArity >= 0 && argumentCount != constructorArity {
    addTypeArgumentArityDiagnostic(
      state,
      moduleIndex,
      "`{name}`",
      constructorArity,
      argumentCount,
      nameNode,
    )
    return emptyType("unknown")
  }
  if constructorArity >= 0 {
    let mut arguments: Array<TypeValue> = []
    for argument in argumentNodes {
      arguments.push(formType(
        service,
        state,
        moduleIndex,
        source,
        argument,
        parameters,
        origin,
      ))
    }
    let formed = constructor(name, arguments)
    if (name == "Map" || name == "Set") &&
      state.typeCapabilitySuppressions.length == 0 {
      match arguments.get(0) {
        case Some(key) => serviceGateCollectionKey(
          service,
          state,
          moduleIndex,
          nameNode,
          key,
        )
        case None => ()
      }
    }
    return formed
  }
  let target = targetType(state, moduleIndex, nameNode)
  let targetModule = target.moduleIndex
  let targetName = target.name
  let displayName = if node.kind == "type/qualified" {
    let namespace = match child(node, "namespace") {
      case Some(found) => text(source, found)
      case None => ""
    }
    "{namespace}.{name}"
  } else {
    name
  }
  let aliasIndex = aliasDefinitionIndex(state, targetModule, targetName)
  if aliasIndex >= 0 && targetModule == moduleIndex &&
    node.kind != "type/qualified" {
    match state.aliases.get(aliasIndex) {
      case Some(alias) => if argumentCount != alias.typeParameters.length {
        addTypeArgumentArityDiagnostic(
          state,
          moduleIndex,
          "type alias `{displayName}`",
          alias.typeParameters.length,
          argumentCount,
          nameNode,
        )
        return emptyType("unknown")
      }
      case None => ()
    }
  }
  let mut arguments: Array<TypeValue> = []
  for argument in argumentNodes {
    arguments.push(formType(
      service,
      state,
      moduleIndex,
      source,
      argument,
      parameters,
      origin,
    ))
  }
  match namedNominalTarget(state, targetModule, targetName) {
    case Some(target) => {
      if arguments.length != target.typeArgumentCount {
        addTypeArgumentArityDiagnostic(
          state,
          moduleIndex,
          "{target.diagnosticKind} `{displayName}`",
          target.typeArgumentCount,
          arguments.length,
          nameNode,
        )
        return emptyType("unknown")
      }
      return nominalInModule(
        target.semanticKind,
        targetName,
        arguments,
        moduleIdentityAt(state, targetModule),
      )
    }
    case None => ()
  }
  if aliasIndex >= 0 {
    return match state.aliases.get(aliasIndex) {
      case Some(alias) => {
        if arguments.length != alias.typeParameters.length {
          let subject = if targetModule == moduleIndex &&
            node.kind != "type/qualified" {
            "type alias `{displayName}`"
          } else {
            "`{displayName}`"
          }
          addTypeArgumentArityDiagnostic(
            state,
            moduleIndex,
            subject,
            alias.typeParameters.length,
            arguments.length,
            nameNode,
          )
          emptyType("unknown")
        } else {
          substitute(alias.body, alias.typeParameters, arguments)
        }
      }
      case None => emptyType("unknown")
    }
  }
  if node.kind == "type/qualified" {
    let namespace = match child(node, "namespace") {
      case Some(found) => text(source, found)
      case None => ""
    }
    return nominal("foreign", "{namespace}.{name}", arguments)
  }
  nominal("foreign", name, arguments)
}

export function formType(
  service: CheckerService,
  state: CheckerState,
  moduleIndex: int,
  source: Bytes,
  node: SyntaxNode,
  parameters: Array<string>,
  origin: string,
) -> TypeValue {
  match node.kind {
    case "type/unit" => primitive("unit")
    case "type/literal" => formLiteralType(state, moduleIndex, source, node)
    case "type/union" =>
      formUnionType(service, state, moduleIndex, source, node, parameters, origin)
    case "type/record" =>
      formRecordType(service, state, moduleIndex, source, node, parameters, origin)
    case "type/function" =>
      formFunctionType(service, state, moduleIndex, source, node, parameters, origin)
    case "type/named" | "type/qualified" =>
      formNamedType(service, state, moduleIndex, source, node, parameters, origin)
    case _ => emptyType("unknown")
  }
}

export function predeclareNominals(state: CheckerState) -> () {
  let mut records = state.records
  let mut enums = state.enums
  let mut newtypes = state.newtypes
  let mut aliases = state.aliases
  let mut recordIndexes = state.recordIndexes
  let mut enumIndexes = state.enumIndexes
  let mut newtypeIndexes = state.newtypeIndexes
  let mut aliasIndexes = state.aliasIndexes
  for module in state.modules {
    for statement in module.root.children {
      let item = unwrapExport(statement)
      let nameNode = child(item, "name")
      let name = match nameNode {
        case Some(found) => text(module.source, found)
        case None => ""
      }
      let parameters = typeParameterNames(module.source, item)
      let nominalKind = match item.kind {
        case "statement/record" => "record"
        case "statement/enum" => "enum"
        case "statement/newtype" => "newtype"
        case _ => ""
      }
      let typeDeclaration = nominalKind != "" || item.kind == "statement/type-alias"
      let reservedNominal = (nominalKind != "" && name == "template") || (typeDeclaration && state.languageMode == "topaz-5.21" && (name == "Length" || name == "Pt" || name == "Mm" || name == "Cm" || name == "In" || name == "Em"))
      if reservedNominal {
        let collision = if name == "template" {
          "the builtin `template` type"
        } else {
          "a compiler-owned type"
        }
        addDiagnostic(
          state,
          module.moduleIndex,
          "TPZ5022",
          "{nominalKind} name `{name}` collides with {collision}; choose another name",
          "",
          match nameNode {
            case Some(found) => found
            case None => item
          },
        )
      }
      if !reservedNominal &&
        (item.kind == "statement/record" || item.kind == "statement/enum" ||
        item.kind == "statement/newtype" ||
        item.kind == "statement/type-alias") {
        registerTypeParameters(
          state,
          module.moduleIndex,
          module.source,
          item,
        )
      }
      if !reservedNominal && item.kind == "statement/record" {
        recordIndexes.insert(
          definitionNameKey(module.moduleIndex, name),
          records.length,
        )
        records.push(RecordDefinition {
          moduleIndex: module.moduleIndex,
          name: name,
          typeParameters: parameters,
          fields: [],
        })
      } else if !reservedNominal && item.kind == "statement/enum" {
        enumIndexes.insert(
          definitionNameKey(module.moduleIndex, name),
          enums.length,
        )
        enums.push(EnumDefinition {
          moduleIndex: module.moduleIndex,
          name: name,
          typeParameters: parameters,
          variants: [],
        })
      } else if !reservedNominal && item.kind == "statement/newtype" {
        newtypeIndexes.insert(
          definitionNameKey(module.moduleIndex, name),
          newtypes.length,
        )
        newtypes.push(NewtypeDefinition {
          moduleIndex: module.moduleIndex,
          name: name,
          typeParameters: parameters,
          base: emptyType("unknown"),
        })
      } else if !reservedNominal && item.kind == "statement/type-alias" {
        aliasIndexes.insert(
          definitionNameKey(module.moduleIndex, name),
          aliases.length,
        )
        aliases.push(AliasDefinition {
          moduleIndex: module.moduleIndex,
          name: name,
          typeParameters: parameters,
          body: emptyType("unknown"),
        })
      }
    }
  }
  ()
}

record NominalFillContext {
  state: CheckerState,
  module: ModuleSyntax,
  item: SyntaxNode,
  name: string,
  origin: string,
  parameters: Array<string>,
}

function nominalFillContext(
  state: CheckerState,
  module: ModuleSyntax,
  item: SyntaxNode,
) -> NominalFillContext {
  let name = match child(item, "name") {
    case Some(found) => text(module.source, found)
    case None => ""
  }
  NominalFillContext {
    state: state,
    module: module,
    item: item,
    name: name,
    origin: "source:{module.sourceOrdinal}:{item.lo}:{item.hi}",
    parameters: typeParameterNames(module.source, item),
  }
}

function formNominalChildType(
  service: CheckerService,
  context: NominalFillContext,
  node: SyntaxNode,
  field: string,
) -> TypeValue {
  match child(node, field) {
    case Some(found) => formType(
      service,
      context.state,
      context.module.moduleIndex,
      context.module.source,
      found,
      context.parameters,
      context.origin,
    )
    case None => emptyType("unknown")
  }
}

function fillRecordNominal(service: CheckerService, context: NominalFillContext) -> () {
  let index = recordDefinitionIndex(
    context.state,
    context.module.moduleIndex,
    context.name,
  )
  let mut fields: Array<RecordField> = []
  let mut names: Array<string> = []
  for field in children(context.item, "fields") {
    let name = match child(field, "name") {
      case Some(found) => text(context.module.source, found)
      case None => ""
    }
    if containsString(names, name) {
      addDiagnostic(context.state, context.module.moduleIndex, "TPZ5008",
        "record field `{name}` is declared twice in `{context.name}`", "", field)
      continue
    }
    names.push(name)
    let typeValue = formNominalChildType(service, context, field, "type")
    match child(field, "type") {
      case Some(typeNode) => addNode(
        context.state,
        context.module.moduleIndex,
        "type",
        typeNode,
        typeValue,
      )
      case None => ()
    }
    fields.push(RecordField {
      name: name,
      typeValue: typeValue,
      hasDefault: match child(field, "default") {
        case Some(_) => true
        case None => false
      },
    })
  }
  if index >= 0 {
    replaceRecordDefinition(context.state, index, RecordDefinition {
      moduleIndex: context.module.moduleIndex,
      name: context.name,
      typeParameters: context.parameters,
      fields: fields,
    })
  }
}

function fillEnumNominal(service: CheckerService, context: NominalFillContext) -> () {
  let index = enumDefinitionIndex(
    context.state,
    context.module.moduleIndex,
    context.name,
  )
  let mut variants: Array<EnumVariant> = []
  for variant in children(context.item, "variants") {
    let nameNode = match child(variant, "name") { case Some(found) => found; case None => variant }
    let name = text(context.module.source, nameNode)
    if name == "None" || name == "Some" || name == "Ok" || name == "Err" {
      addDiagnostic(context.state, context.module.moduleIndex, "TPZ5022",
        "enum variant `{name}` collides with a reserved prelude constructor; choose another variant name",
        "", nameNode)
      continue
    }
    let mut payloads: Array<TypeValue> = []
    for payload in children(variant, "payload") {
      let typeValue = formType(
        service,
        context.state,
        context.module.moduleIndex,
        context.module.source,
        payload,
        context.parameters,
        context.origin,
      )
      addNode(
        context.state,
        context.module.moduleIndex,
        "type",
        payload,
        typeValue,
      )
      payloads.push(typeValue)
      if typeValue.kind == "union" {
        let mut containsEnum = false
        for member in typeValue.members {
          if member.kind == "enum" { containsEnum = true }
        }
        if containsEnum {
          addDiagnostic(context.state, context.module.moduleIndex, "TPZ5022",
            "enum variant `{name}` has a payload `{typeText(typeValue)}` that is a union containing an enum — enum-in-union payloads are not supported",
            "", nameNode)
        }
      }
    }
    variants.push(EnumVariant {
      name: name,
      payloads: payloads,
    })
  }
  if index >= 0 {
    replaceEnumDefinition(context.state, index, EnumDefinition {
      moduleIndex: context.module.moduleIndex,
      name: context.name,
      typeParameters: context.parameters,
      variants: variants,
    })
  }
}

function fillNewtypeNominal(service: CheckerService, context: NominalFillContext) -> () {
  let index = newtypeDefinitionIndex(
    context.state,
    context.module.moduleIndex,
    context.name,
  )
  if index >= 0 {
    let base = formNominalChildType(service, context, context.item, "base")
    match child(context.item, "base") {
      case Some(typeNode) => addNode(
        context.state,
        context.module.moduleIndex,
        "type",
        typeNode,
        base,
      )
      case None => ()
    }
    replaceNewtypeDefinition(context.state, index, NewtypeDefinition {
      moduleIndex: context.module.moduleIndex,
      name: context.name,
      typeParameters: context.parameters,
      base: base,
    })
  }
}

function fillAliasNominal(service: CheckerService, context: NominalFillContext) -> () {
  let index = aliasDefinitionIndex(
    context.state,
    context.module.moduleIndex,
    context.name,
  )
  if index >= 0 {
    let body = formNominalChildType(service, context, context.item, "type")
    match child(context.item, "type") {
      case Some(typeNode) => addNode(
        context.state,
        context.module.moduleIndex,
        "type",
        typeNode,
        body,
      )
      case None => ()
    }
    let mut aliases = context.state.aliases
    aliases[index] = AliasDefinition {
      moduleIndex: context.module.moduleIndex,
      name: context.name,
      typeParameters: context.parameters,
      body: body,
    }
  }
}

function fillNominalDefinition(
  service: CheckerService,
  state: CheckerState,
  module: ModuleSyntax,
  item: SyntaxNode,
) -> () {
  if item.kind != "statement/record" && item.kind != "statement/enum" &&
    item.kind != "statement/newtype" && item.kind != "statement/type-alias" {
    return ()
  }
  let context = nominalFillContext(state, module, item)
  match item.kind {
    case "statement/record" => fillRecordNominal(service, context)
    case "statement/enum" => fillEnumNominal(service, context)
    case "statement/newtype" => fillNewtypeNominal(service, context)
    case "statement/type-alias" => fillAliasNominal(service, context)
    case _ => ()
  }
}

export function fillNominals(service: CheckerService, state: CheckerState) -> () {
  for module in state.modules {
    for statement in module.root.children {
      fillNominalDefinition(service, state, module, unwrapExport(statement))
    }
  }
  ()
}

function normalizedProtocolType(
  service: CheckerService,
  state: CheckerState,
  module: ModuleSyntax,
  node: SyntaxNode,
  explicitParameter: string,
  origin: string,
  conformingType: TypeValue,
) -> TypeValue {
  let mut parameters: Array<string> = ["Self"]
  let mut replacements: Array<TypeValue> = [conformingType]
  if explicitParameter != "" {
    parameters.push(explicitParameter)
    replacements.push(conformingType)
  }
  substitute(
    formType(
      service,
      state,
      module.moduleIndex,
      module.source,
      node,
      parameters,
      origin,
    ),
    parameters,
    replacements,
  )
}

function checkProtocolMethod(
  service: CheckerService,
  state: CheckerState,
  module: ModuleSyntax,
  protocolName: string,
  explicitParameter: string,
  origin: string,
  method: SyntaxNode,
  methodIndexes: Map<string, int>,
) -> Option<ProtocolMethodDefinition> {
  let methodNameNode = match child(method, "name") {
    case Some(found) => found
    case None => return None
  }
  let methodName = text(module.source, methodNameNode)
  match methodIndexes.get(methodName) {
    case Some(_) => {
      addDiagnostic(
        state,
        module.moduleIndex,
        "TPZ5008",
        "method `{methodName}` is already declared in protocol `{protocolName}`",
        "",
        methodNameNode,
      )
      return None
    }
    case None => ()
  }
  if children(method, "typeParameters").length > 0 {
    addDiagnostic(
      state,
      module.moduleIndex,
      "TPZ5022",
      "protocol method `{protocolName}.{methodName}` cannot be generic",
      "",
      methodNameNode,
    )
    return None
  }
  let methodParameters = children(method, "parameters")
  if methodParameters.length == 0 {
    addDiagnostic(
      state,
      module.moduleIndex,
      "TPZ5022",
      "protocol method `{protocolName}.{methodName}` must take the conforming value as its first parameter",
      "",
      methodNameNode,
    )
    return None
  }
  let firstParameter = methodParameters[0]
  let returnTypeNodes = children(method, "returnType")
  if returnTypeNodes.length == 0 {
    addDiagnostic(
      state,
      module.moduleIndex,
      "TPZ5022",
      "protocol method `{protocolName}.{methodName}` requires an explicit return type (use `-> ()` for unit)",
      "",
      methodNameNode,
    )
    return None
  }
  let returnTypeNode = returnTypeNodes[0]
  for parameter in methodParameters {
    if boolAttribute(parameter, "variadic") {
      addDiagnostic(
        state,
        module.moduleIndex,
        "TPZ5022",
        "protocol method `{protocolName}.{methodName}` cannot be variadic",
        "",
        parameter,
      )
      return None
    }
  }
  for parameter in methodParameters {
    match child(parameter, "default") {
      case Some(_) => {
        addDiagnostic(
          state,
          module.moduleIndex,
          "TPZ5022",
          "protocol method `{protocolName}.{methodName}` cannot declare parameter defaults",
          "",
          parameter,
        )
        return None
      }
      case None => ()
    }
  }
  let conformingType = rigid("Self", origin)
  let mut parameterTypes: Array<TypeValue> = []
  for parameter in methodParameters {
    parameterTypes.push(match child(parameter, "type") {
      case Some(found) => normalizedProtocolType(
        service,
        state,
        module,
        found,
        explicitParameter,
        origin,
        conformingType,
      )
      case None => emptyType("unknown")
    })
  }
  let firstTypeNode = match child(firstParameter, "type") {
    case Some(found) => found
    case None => firstParameter
  }
  let firstType = match parameterTypes.get(0) {
    case Some(found) => found
    case None => emptyType("unknown")
  }
  if !typeEqual(firstType, conformingType) {
    addDiagnostic(
      state,
      module.moduleIndex,
      "TPZ5022",
      "protocol method `{protocolName}.{methodName}` must use `Self` or the protocol's type parameter as its first parameter type",
      "",
      firstTypeNode,
    )
    return None
  }
  let resultType = normalizedProtocolType(
    service,
    state,
    module,
    returnTypeNode,
    explicitParameter,
    origin,
    conformingType,
  )
  let mut indexes = methodIndexes
  indexes.insert(methodName, 1)
  let mut parameterNames: Array<string> = []
  for parameter in methodParameters {
    parameterNames.push(match child(parameter, "name") {
      case Some(found) => text(module.source, found)
      case None => ""
    })
  }
  Some(ProtocolMethodDefinition {
    name: methodName,
    parameterNames: parameterNames,
    typeValue: functionType(parameterTypes, [], resultType),
  })
}

function collectProtocol(
  service: CheckerService,
  state: CheckerState,
  module: ModuleSyntax,
  statement: SyntaxNode,
) -> () {
  let item = unwrapExport(statement)
  if item.kind != "statement/protocol" {
    return ()
  }
  let nameNode = match child(item, "name") {
    case Some(found) => found
    case None => return ()
  }
  let name = text(module.source, nameNode)
  if name == "Show" || name == "Eq" || name == "Order" || name == "JSON" {
    addDiagnostic(
      state,
      module.moduleIndex,
      "TPZ5008",
      "`{name}` is a builtin protocol and cannot be redeclared",
      "",
      nameNode,
    )
    return ()
  }
  if protocolDefinitionIndex(state, module.moduleIndex, name) >= 0 {
    addDiagnostic(
      state,
      module.moduleIndex,
      "TPZ5008",
      "protocol `{name}` is already declared",
      "",
      nameNode,
    )
    return ()
  }
  if recordDefinitionIndex(state, module.moduleIndex, name) >= 0 ||
    enumDefinitionIndex(state, module.moduleIndex, name) >= 0 ||
    newtypeDefinitionIndex(state, module.moduleIndex, name) >= 0 ||
    aliasDefinitionIndex(state, module.moduleIndex, name) >= 0 {
    addDiagnostic(
      state,
      module.moduleIndex,
      "TPZ5022",
      "`{name}` is already a type and cannot also be a protocol",
      "",
      nameNode,
    )
    return ()
  }
  let typeParameters = typeParameterNames(module.source, item)
  if typeParameters.length > 1 {
    addDiagnostic(
      state,
      module.moduleIndex,
      "TPZ5022",
      "protocol `{name}` takes at most one conforming-type parameter; found {typeParameters.length}",
      "",
      nameNode,
    )
    return ()
  }
  let explicitParameter = match typeParameters.get(0) {
    case Some(found) => found
    case None => ""
  }
  let origin = "{module.identity}::{name}::protocol"
  let mut methodIndexes: Map<string, int> = map {}
  let mut protocolMethods: Array<ProtocolMethodDefinition> = []
  for method in children(item, "methods") {
    match checkProtocolMethod(
      service,
      state,
      module,
      name,
      explicitParameter,
      origin,
      method,
      methodIndexes,
    ) {
      case Some(found) => protocolMethods.push(found)
      case None => ()
    }
  }
  let mut indexes = state.protocolIndexes
  let mut protocols = state.protocols
  indexes.insert(definitionNameKey(module.moduleIndex, name), protocols.length)
  protocols.push(ProtocolDefinition {
    name: name,
    methods: protocolMethods,
  })
  ()
}

export function collectProtocols(service: CheckerService, state: CheckerState) -> () {
  for module in state.modules {
    for statement in module.root.children {
      collectProtocol(service, state, module, statement)
    }
  }
  ()
}

// Pattern typing, bindings, narrowing, coverage, and exhaustiveness.
// Nominal catalogs enter as checker state; match control and diagnostics consume
// the coverage result without duplicating pattern traversal.

import types { SyntaxNode }
import checker_types { TypeValue }
import unicode { didYouMean }
import resolver.modules_tables { collectPatternBindings }
import checker.model {
  CheckerService,
  CheckerState,
  CoverageGap,
  EnumDefinition,
  EnumVariant,
  PatternCoverage,
  RecordDefinition,
  constructor,
  emptyType,
  inference,
  literal,
  nominal,
  primitive,
  rigid,
  serviceInferExpression,
}
import checker.type_algebra {
  typeDecidable,
  typesOverlap,
  assignable,
  hasHole,
  stringJoin,
  typeText,
  unionType,
}
import checker.syntax_index {
  addDiagnostic,
  addNode,
  bindSymbol,
  child,
  children,
  containsString,
  moduleIdentityAt,
  newtypeDefinitionIndex,
  recordDefinitionIndex,
  symbolTypeAt,
  text,
}
import checker.nominals {
  formType,
  substitute,
  targetType,
}
import checker.protocols_methods {
  enumDefinitionForType,
  newtypeDefinitionForType,
}
import checker.members_capabilities {
  typeArgument,
}

export function patternBindingNodes(pattern: SyntaxNode) -> Array<SyntaxNode> {
  let mut output: Array<SyntaxNode> = []
  if pattern.kind == "pattern/binding" || pattern.kind == "pattern/typed" {
    match child(pattern, "name") {
      case Some(found) => output.push(found)
      case None => ()
    }
    return output
  }
  for nested in pattern.children {
    for found in patternBindingNodes(nested) {
      output.push(found)
    }
  }
  output
}

function patternAlternativeBindingNodes(
  state: CheckerState,
  moduleIndex: int,
  source: Bytes,
  pattern: SyntaxNode,
  expected: TypeValue,
) -> Array<SyntaxNode> {
  if pattern.kind == "pattern/binding" {
    let nameNode = match child(pattern, "name") {
      case Some(found) => found
      case None => pattern
    }
    let name = text(source, nameNode)
    match enumDefinitionForType(state, moduleIndex, expected) {
      case Some(definition) => for variant in definition.variants {
        if variant.name == name && variant.payloads.length == 0 {
          let empty: Array<SyntaxNode> = []
          return empty
        }
      }
      case None => ()
    }
  }
  patternBindingNodes(pattern)
}

function patternAlternativeHasBinding(
  state: CheckerState,
  moduleIndex: int,
  source: Bytes,
  pattern: SyntaxNode,
  expected: TypeValue,
  name: string,
) -> bool {
  for found in patternAlternativeBindingNodes(
    state,
    moduleIndex,
    source,
    pattern,
    expected,
  ) {
    if text(source, found) == name {
      return true
    }
  }
  false
}

// Let bindings use the same type-aware coverage as match patterns. In
// particular, record fields are wrappers and pure-rest arrays and single
// constructor types can be irrefutable despite their surface syntax.
export function patternIsIrrefutable(
  state: CheckerState,
  moduleIndex: int,
  expected: TypeValue,
  coverage: PatternCoverage,
) -> bool {
  hasHole(expected) || coverageCoversAt(state, moduleIndex, coverage, expected, "")
}

export function emptyPatternCoverage() -> PatternCoverage {
  PatternCoverage { irrefutable: false, keys: [] }
}

function irrefutablePatternCoverage() -> PatternCoverage {
  PatternCoverage { irrefutable: true, keys: [] }
}

function coverageHasKey(coverage: PatternCoverage, key: string) -> bool {
  containsString(coverage.keys, key)
}

function coverageWithKey(key: string) -> PatternCoverage {
  PatternCoverage { irrefutable: false, keys: [key] }
}

export function mergePatternCoverage(
  left: PatternCoverage,
  right: PatternCoverage,
) -> PatternCoverage {
  let mut keys = left.keys
  for key in right.keys {
    if !containsString(keys, key) {
      keys.push(key)
    }
  }
  PatternCoverage {
    irrefutable: left.irrefutable || right.irrefutable,
    keys: keys,
  }
}

function coveragePath(prefix: string, part: string) -> string {
  if prefix == "" { part } else { "{prefix}/{part}" }
}

function prefixPatternCoverage(
  prefix: string,
  nested: PatternCoverage,
) -> PatternCoverage {
  let mut keys: Array<string> = []
  if nested.irrefutable {
    keys.push("{prefix}/*")
  }
  for key in nested.keys {
    keys.push("{prefix}/{key}")
  }
  PatternCoverage { irrefutable: false, keys: keys }
}

function patternTypeOpaque(value: TypeValue) -> bool {
  value.kind == "unknown" || value.kind == "inference-variable" ||
    value.kind == "rigid" || value.kind == "foreign"
}


function narrowPatternType(
  scrutinee: TypeValue,
  formed: TypeValue,
) -> TypeValue {
  if hasHole(scrutinee) { return formed }
  if assignable(formed, scrutinee) { return scrutinee }
  if assignable(scrutinee, formed) { return formed }
  if scrutinee.kind == "union" {
    let mut kept: Array<TypeValue> = []
    for member in scrutinee.members {
      if typesOverlap(member, formed) {
        kept.push(narrowPatternType(member, formed))
      }
    }
    if kept.length > 0 { return unionType(kept) }
  }
  formed
}

function patternNameSuggestion(
  target: string,
  candidates: Array<string>,
) -> string {
  didYouMean(target, candidates)
}

function recordPatternHeadSuggestion(
  state: CheckerState,
  moduleIndex: int,
  target: string,
) -> string {
  let mut candidates: Array<string> = []
  for definition in state.records {
    if definition.moduleIndex == moduleIndex {
      candidates.push(definition.name)
    }
  }
  patternNameSuggestion(target, candidates)
}

function recordFieldSuggestion(
  definition: RecordDefinition,
  target: string,
) -> string {
  let mut candidates: Array<string> = []
  for field in definition.fields { candidates.push(field.name) }
  patternNameSuggestion(target, candidates)
}

function structuralFieldSuggestion(
  value: TypeValue,
  target: string,
) -> string {
  patternNameSuggestion(target, value.fieldNames)
}

function enumVariantSuggestion(
  definition: EnumDefinition,
  target: string,
) -> string {
  let mut candidates: Array<string> = []
  for variant in definition.variants { candidates.push(variant.name) }
  patternNameSuggestion(target, candidates)
}

function nominalPatternIdentityFor(identity: string, origin: string) -> string {
  if origin == "" { identity }
  else { "{origin}::{identity}" }
}

function nominalPatternIdentity(value: TypeValue) -> string {
  nominalPatternIdentityFor(value.identity, value.origin)
}

function coverageCoversAt(
  state: CheckerState,
  moduleIndex: int,
  coverage: PatternCoverage,
  value: TypeValue,
  prefix: string,
) -> bool {
  if prefix == "" && coverage.irrefutable {
    return true
  }
  if prefix != "" && coverageHasKey(coverage, "{prefix}/*") {
    return true
  }
  if value.kind == "primitive" && value.name == "bool" {
    return coverageHasKey(
      coverage,
      coveragePath(prefix, "literal:true"),
    ) && coverageHasKey(
      coverage,
      coveragePath(prefix, "literal:false"),
    )
  }
  if value.kind == "literal" {
    return coverageHasKey(
      coverage,
      coveragePath(prefix, "literal:{typeText(value)}"),
    )
  }
  if value.kind == "union" {
    if value.members.length == 0 { return false }
    for member in value.members {
      if !coverageCoversAt(state, moduleIndex, coverage, member, prefix) {
        return false
      }
    }
    return true
  }
  if value.kind == "constructor" && value.name == "Option" {
    return coverageCoversAt(
      state,
      moduleIndex,
      coverage,
      typeArgument(value, 0),
      coveragePath(prefix, "constructor:Some"),
    ) && coverageHasKey(
      coverage,
      coveragePath(prefix, "constructor:None/*"),
    )
  }
  if value.kind == "constructor" && value.name == "Result" {
    return coverageCoversAt(
      state,
      moduleIndex,
      coverage,
      typeArgument(value, 0),
      coveragePath(prefix, "constructor:Ok"),
    ) && coverageCoversAt(
      state,
      moduleIndex,
      coverage,
      typeArgument(value, 1),
      coveragePath(prefix, "constructor:Err"),
    )
  }
  if value.kind == "enum" {
    return match enumDefinitionForType(state, moduleIndex, value) {
      case Some(definition) => {
        for variant in definition.variants {
          let variantPrefix = coveragePath(
            prefix,
            "constructor:{variant.name}",
          )
          if variant.payloads.length == 0 {
            if !coverageHasKey(coverage, "{variantPrefix}/*") {
              return false
            }
          } else if variant.payloads.length == 1 {
            let payload = match variant.payloads.get(0) {
              case Some(found) => substitute(
                found,
                definition.typeParameters,
                value.arguments,
              )
              case None => emptyType("unknown")
            }
            if !coverageCoversAt(
              state,
              definition.moduleIndex,
              coverage,
              payload,
              variantPrefix,
            ) {
              return false
            }
          } else if !coverageHasKey(coverage, "{variantPrefix}/*") {
            return false
          }
        }
        true
      }
      case None => false
    }
  }
  if value.kind == "nominal-record" {
    return coverageHasKey(
      coverage,
      coveragePath(prefix, "record:{nominalPatternIdentity(value)}"),
    )
  }
  false
}

export function coverageGap(
  state: CheckerState,
  moduleIndex: int,
  coverage: PatternCoverage,
  value: TypeValue,
) -> CoverageGap {
  if coverage.irrefutable {
    return CoverageGap { decidable: true, missing: [] }
  }
  let mut missing: Array<string> = []
  if value.kind == "primitive" && value.name == "bool" {
    for spelling in ["true", "false"] {
      if !coverageHasKey(coverage, "literal:{spelling}") {
        missing.push("`{spelling}`")
      }
    }
    return CoverageGap { decidable: true, missing: missing }
  }
  if value.kind == "newtype" {
    missing.push("`{typeText(value)}(_)`")
    return CoverageGap { decidable: true, missing: missing }
  }
  if value.kind == "union" {
    let mut decidable = true
    for member in value.members {
      if member.kind == "literal" {
        if !coverageHasKey(coverage, "literal:{typeText(member)}") {
          missing.push("`{typeText(member)}`")
        }
      } else if member.kind == "nominal-record" {
        if !coverageHasKey(
          coverage,
          "record:{nominalPatternIdentity(member)}",
        ) {
          missing.push("`{typeText(member)} \{ … \}`")
        }
      } else {
        decidable = false
      }
    }
    return CoverageGap {
      decidable: decidable,
      missing: if decidable { missing } else { [] },
    }
  }
  if value.kind == "constructor" && value.name == "Option" {
    if !coverageCoversAt(
      state,
      moduleIndex,
      coverage,
      typeArgument(value, 0),
      "constructor:Some",
    ) {
      missing.push("`Some`")
    }
    if !coverageHasKey(coverage, "constructor:None/*") {
      missing.push("`None`")
    }
    return CoverageGap { decidable: true, missing: missing }
  }
  if value.kind == "constructor" && value.name == "Result" {
    if !coverageCoversAt(
      state,
      moduleIndex,
      coverage,
      typeArgument(value, 0),
      "constructor:Ok",
    ) {
      missing.push("`Ok`")
    }
    if !coverageCoversAt(
      state,
      moduleIndex,
      coverage,
      typeArgument(value, 1),
      "constructor:Err",
    ) {
      missing.push("`Err`")
    }
    return CoverageGap { decidable: true, missing: missing }
  }
  if value.kind == "enum" {
    return match enumDefinitionForType(state, moduleIndex, value) {
      case Some(definition) => {
        for variant in definition.variants {
          let prefix = "constructor:{variant.name}"
          let mut covered = false
          if variant.payloads.length == 0 || variant.payloads.length > 1 {
            covered = coverageHasKey(coverage, "{prefix}/*")
          } else {
            let payload = match variant.payloads.get(0) {
              case Some(found) => substitute(
                found,
                definition.typeParameters,
                value.arguments,
              )
              case None => emptyType("unknown")
            }
            covered = coverageCoversAt(
              state,
              definition.moduleIndex,
              coverage,
              payload,
              prefix,
            )
          }
          if !covered {
            missing.push("`{typeText(value)}.{variant.name}`")
          }
        }
        CoverageGap { decidable: true, missing: missing }
      }
      case None => CoverageGap { decidable: false, missing: [] }
    }
  }
  if value.kind == "nominal-record" {
    if !coverageHasKey(
      coverage,
      "record:{nominalPatternIdentity(value)}",
    ) {
      missing.push("`{typeText(value)} \{ … \}`")
    }
    return CoverageGap { decidable: true, missing: missing }
  }
  CoverageGap { decidable: false, missing: [] }
}

function checkLiteralPattern(
  service: CheckerService,
  state: CheckerState,
  moduleIndex: int,
  source: Bytes,
  pattern: SyntaxNode,
  expected: TypeValue,
) -> PatternCoverage {
  let mut coverage = emptyPatternCoverage()
  for fieldName in ["value", "low", "high"] {
    match child(pattern, fieldName) {
      case Some(value) => {
        let inferred = serviceInferExpression(service, state, moduleIndex, source, value)
        if pattern.kind == "pattern/literal" && fieldName == "value" {
          coverage = coverageWithKey("literal:{typeText(inferred)}")
          if typeDecidable(expected) && !hasHole(inferred) &&
            !typesOverlap(inferred, expected) {
            addDiagnostic(
              state,
              moduleIndex,
              "TPZ5001",
              "this pattern can never match `{typeText(expected)}`",
              "",
              value,
            )
          }
        }
      }
      case None => ()
    }
  }
  addNode(state, moduleIndex, "pattern", pattern, expected)
  coverage
}

export function bindNamedPatternType(
  state: CheckerState,
  moduleIndex: int,
  source: Bytes,
  pattern: SyntaxNode,
  expected: TypeValue,
  typeValue: TypeValue,
  mutable: bool,
) -> () {
  let nameNode = match child(pattern, "name") {
    case Some(found) => found
    case None => pattern
  }
  let name = text(source, nameNode)
  if pattern.kind == "pattern/binding" {
    match enumDefinitionForType(state, moduleIndex, expected) {
      case Some(definition) => for variant in definition.variants {
        if variant.name == name && variant.payloads.length == 0 {
          addNode(state, moduleIndex, "pattern", pattern, expected)
          return ()
        }
      }
      case None => ()
    }
  }
  bindSymbol(
    state,
    moduleIndex,
    nameNode.lo,
    nameNode.hi,
    name,
    typeValue,
    mutable,
  )
  addNode(
    state,
    moduleIndex,
    "pattern",
    pattern,
    if pattern.kind == "pattern/typed" { expected } else { typeValue },
  )
  addNode(state, moduleIndex, "binding", nameNode, typeValue)
}

function bindNamedPattern(
  service: CheckerService,
  state: CheckerState,
  moduleIndex: int,
  source: Bytes,
  pattern: SyntaxNode,
  expected: TypeValue,
  mutable: bool,
) -> PatternCoverage {
  let typeValue = if pattern.kind == "pattern/typed" {
    match child(pattern, "type") {
      case Some(found) => formType(
        service,
        state,
        moduleIndex,
        source,
        found,
        [],
        "pattern",
      )
      case None => expected
    }
  } else {
    expected
  }
  let mut coverage = irrefutablePatternCoverage()
  let mut bound = typeValue
  if pattern.kind == "pattern/typed" {
    if !hasHole(expected) && !hasHole(typeValue) &&
      assignable(typeValue, expected) {
      coverage = irrefutablePatternCoverage()
    } else {
      coverage = emptyPatternCoverage()
      if typeDecidable(expected) && typeDecidable(typeValue) &&
        !typesOverlap(expected, typeValue) {
        addDiagnostic(
          state,
          moduleIndex,
          "TPZ5001",
          "this pattern can never match `{typeText(expected)}`",
          "",
          pattern,
        )
      }
    }
    bound = narrowPatternType(expected, typeValue)
  }
  bindNamedPatternType(
    state,
    moduleIndex,
    source,
    pattern,
    expected,
    bound,
    mutable,
  )
  coverage
}

function recordFieldType(value: TypeValue, name: string) -> Option<TypeValue> {
  if value.kind != "record" { return None }
  let mut index = 0
  for fieldName in value.fieldNames {
    if fieldName == name {
      return value.fields.get(index)
    }
    index += 1
  }
  None
}

function literalPatternType(
  service: CheckerService,
  state: CheckerState,
  moduleIndex: int,
  source: Bytes,
  pattern: SyntaxNode,
) -> Option<TypeValue> {
  if pattern.kind != "pattern/literal" { return None }
  match child(pattern, "value") {
    case Some(value) => Some(serviceInferExpression(service, state, moduleIndex, source, value))
    case None => None
  }
}

function structuralRecordCandidate(
  service: CheckerService,
  state: CheckerState,
  moduleIndex: int,
  source: Bytes,
  pattern: SyntaxNode,
  value: TypeValue,
) -> bool {
  if value.kind != "record" { return false }
  for field in children(pattern, "fields") {
    let nameNode = match child(field, "name") {
      case Some(found) => found
      case None => field
    }
    let fieldType = match recordFieldType(value, text(source, nameNode)) {
      case Some(found) => found
      case None => return false
    }
    match child(field, "pattern") {
      case Some(nested) => match literalPatternType(
        service,
        state,
        moduleIndex,
        source,
        nested,
      ) {
        case Some(literalType) => if typeDecidable(fieldType) &&
          !typesOverlap(literalType, fieldType) {
          return false
        }
        case None => ()
      }
      case None => ()
    }
  }
  true
}

function bindRecordPattern(
  service: CheckerService,
  state: CheckerState,
  moduleIndex: int,
  source: Bytes,
  pattern: SyntaxNode,
  expected: TypeValue,
  mutable: bool,
) -> PatternCoverage {
  if pattern.kind == "pattern/nominal-record" {
    let nameNode = match child(pattern, "name") {
      case Some(found) => found
      case None => pattern
    }
    let recordName = text(source, nameNode)
    let target = targetType(state, moduleIndex, nameNode)
    let targetModule = target.moduleIndex
    let targetName = target.name
    let targetOrigin = moduleIdentityAt(state, targetModule)
    let mut definition: Option<RecordDefinition> = None
    let index = recordDefinitionIndex(state, targetModule, targetName)
    if index >= 0 {
      definition = state.records.get(index)
    }
    let mut candidates: Array<TypeValue> = []
    let mut members: Array<TypeValue> = if expected.kind == "union" {
      expected.members
    } else {
      [expected]
    }
    let mut hasRigid = false
    let mut hasGradual = false
    let mut allMatch = members.length > 0
    for member in members {
      if member.kind == "nominal-record" &&
        member.identity == targetName && member.origin == targetOrigin {
        candidates.push(member)
      } else {
        allMatch = false
        if member.kind == "rigid" || member.kind == "foreign" {
          hasRigid = true
        }
        if hasHole(member) { hasGradual = true }
      }
    }
    match definition {
      case Some(recordDefinition) => {
        if hasRigid {
          addDiagnostic(
            state,
            moduleIndex,
            "TPZ5001",
            "a `{recordName}` pattern cannot establish nominal identity for rigid scrutinee type `{typeText(expected)}`",
            "",
            pattern,
          )
        } else if candidates.length == 0 && !hasGradual {
          addDiagnostic(
            state,
            moduleIndex,
            "TPZ5001",
            "this `{recordName}` pattern can never match `{typeText(expected)}`",
            "",
            pattern,
          )
        }
        let mut allIrrefutable = true
        let mut seenFields: Array<string> = []
        for field in children(pattern, "fields") {
          let fieldNameNode = match child(field, "name") {
            case Some(found) => found
            case None => field
          }
          let fieldName = text(source, fieldNameNode)
          let duplicate = containsString(seenFields, fieldName)
          seenFields.push(fieldName)
          if duplicate {
            addDiagnostic(
              state,
              moduleIndex,
              "TPZ5008",
              "nominal record pattern field `{fieldName}` is specified more than once",
              "",
              field,
            )
          }
          let mut knownField = false
          for declared in recordDefinition.fields {
            if declared.name == fieldName { knownField = true }
          }
          if !knownField {
            addDiagnostic(
              state,
              moduleIndex,
              "TPZ5006",
              "record `{recordName}` has no field `{fieldName}`" +
                recordFieldSuggestion(recordDefinition, fieldName),
              "",
              field,
            )
          }
          let mut fieldTypes: Array<TypeValue> = []
          for candidate in candidates {
            for declared in recordDefinition.fields {
              if declared.name == fieldName {
                fieldTypes.push(substitute(
                  declared.typeValue,
                  recordDefinition.typeParameters,
                  candidate.arguments,
                ))
              }
            }
          }
          if hasGradual { fieldTypes.push(emptyType("unknown")) }
          let fieldType = if fieldTypes.length == 0 {
            let mut fallback = emptyType("unknown")
            for declared in recordDefinition.fields {
              if declared.name == fieldName { fallback = declared.typeValue }
            }
            fallback
          } else {
            unionType(fieldTypes)
          }
          match child(field, "pattern") {
            case Some(nested) => {
              let nestedCoverage = patternBindingTypeAt(
                service,
                state,
                moduleIndex,
                source,
                nested,
                fieldType,
                mutable,
                false,
              )
              allIrrefutable = allIrrefutable && nestedCoverage.irrefutable
            }
            case None => bindSymbol(
              state,
              moduleIndex,
              fieldNameNode.lo,
              fieldNameNode.hi,
              fieldName,
              fieldType,
              mutable,
            )
          }
        }
        addNode(state, moduleIndex, "pattern", pattern, expected)
        if allIrrefutable {
          let targetIdentity = nominalPatternIdentityFor(
            targetName,
            targetOrigin,
          )
          let keyed = coverageWithKey("record:{targetIdentity}")
          return if allMatch {
            PatternCoverage { irrefutable: true, keys: keyed.keys }
          } else {
            keyed
          }
        }
        return emptyPatternCoverage()
      }
      case None => {
        addDiagnostic(
          state,
          moduleIndex,
          "TPZ5002",
          "unbound nominal record pattern head `{recordName}`" +
            recordPatternHeadSuggestion(state, moduleIndex, recordName),
          "",
          nameNode,
        )
        addNode(state, moduleIndex, "pattern", pattern, expected)
        return emptyPatternCoverage()
      }
    }
  }

  let mut members: Array<TypeValue> = if expected.kind == "union" {
    expected.members
  } else {
    [expected]
  }
  let mut candidates: Array<TypeValue> = []
  let mut rigids: Array<TypeValue> = []
  let mut hasGradual = false
  for member in members {
    if structuralRecordCandidate(
      service,
      state,
      moduleIndex,
      source,
      pattern,
      member,
    ) {
      candidates.push(member)
    } else if member.kind == "rigid" || member.kind == "foreign" {
      rigids.push(member)
    } else if hasHole(member) {
      hasGradual = true
    }
  }
  if expected.kind != "record" && candidates.length == 0 &&
    rigids.length == 0 && !hasGradual &&
    typeDecidable(expected) {
    addDiagnostic(
      state,
      moduleIndex,
      "TPZ5001",
      "this pattern can never match `{typeText(expected)}`",
      "",
      pattern,
    )
  }
  let mut allIrrefutable = expected.kind == "record"
  for field in children(pattern, "fields") {
    let nameNode = match child(field, "name") {
      case Some(found) => found
      case None => field
    }
    let fieldName = text(source, nameNode)
    let mut fieldTypes: Array<TypeValue> = []
    for candidate in candidates {
      match recordFieldType(candidate, fieldName) {
        case Some(found) => fieldTypes.push(found)
        case None => ()
      }
    }
    for rigidMember in rigids {
      fieldTypes.push(rigid(
        "FieldOf<{typeText(rigidMember)}, {fieldName}>",
        "builtin::record-pattern",
      ))
    }
    if hasGradual { fieldTypes.push(emptyType("unknown")) }
    if expected.kind == "record" &&
      recordFieldType(expected, fieldName) == None {
      addDiagnostic(
        state,
        moduleIndex,
        "TPZ5006",
        "`{typeText(expected)}` has no field `{fieldName}`" +
          structuralFieldSuggestion(expected, fieldName),
        "",
        field,
      )
    }
    let fieldType = if fieldTypes.length == 0 {
      emptyType("unknown")
    } else {
      unionType(fieldTypes)
    }
    match child(field, "pattern") {
      case Some(found) => {
        let nested = patternBindingTypeAt(
          service,
          state,
          moduleIndex,
          source,
          found,
          fieldType,
          mutable,
          false,
        )
        allIrrefutable = allIrrefutable && nested.irrefutable
      }
      case None => bindSymbol(
        state,
        moduleIndex,
        nameNode.lo,
        nameNode.hi,
        text(source, nameNode),
        fieldType,
        mutable,
      )
    }
  }
  addNode(state, moduleIndex, "pattern", pattern, expected)
  if allIrrefutable { irrefutablePatternCoverage() } else { emptyPatternCoverage() }
}

function bindConstructorPattern(
  service: CheckerService,
  state: CheckerState,
  moduleIndex: int,
  source: Bytes,
  pattern: SyntaxNode,
  expected: TypeValue,
  mutable: bool,
) -> PatternCoverage {
  let nameNode = match child(pattern, "name") {
    case Some(found) => found
    case None => pattern
  }
  let name = text(source, nameNode)
  let target = targetType(state, moduleIndex, nameNode)
  let targetModule = target.moduleIndex
  let targetName = target.name
  let targetOrigin = moduleIdentityAt(state, targetModule)
  let arguments = children(pattern, "arguments")

  if expected.kind == "newtype" {
    let mut coverage = emptyPatternCoverage()
    match newtypeDefinitionForType(state, moduleIndex, expected) {
      case Some(definition) => {
        let base = substitute(
          definition.base,
          definition.typeParameters,
          expected.arguments,
        )
        if targetName != expected.identity || targetOrigin != expected.origin ||
          newtypeDefinitionIndex(state, targetModule, targetName) < 0 {
          for argument in arguments {
            let _ = patternBindingTypeAt(
              service,
              state,
              moduleIndex,
              source,
              argument,
              emptyType("unknown"),
              mutable,
              false,
            )
          }
          addDiagnostic(
            state,
            moduleIndex,
            "TPZ5001",
            "this `{name}` pattern can never match `{typeText(expected)}`",
            "",
            pattern,
          )
        } else if arguments.length != 1 {
          addDiagnostic(
            state,
            moduleIndex,
            "TPZ5004",
            "newtype `{typeText(expected)}` pattern takes 1 subpattern (the wrapped `{typeText(base)}`), found {arguments.length}",
            "",
            pattern,
          )
        } else {
          let nested = match arguments.get(0) {
            case Some(argument) => patternBindingTypeAt(
              service,
              state,
              moduleIndex,
              source,
              argument,
              base,
              mutable,
              false,
            )
            case None => emptyPatternCoverage()
          }
          coverage = if nested.irrefutable {
            irrefutablePatternCoverage()
          } else {
            emptyPatternCoverage()
          }
        }
      }
      case None => ()
    }
    addNode(state, moduleIndex, "pattern", pattern, expected)
    return coverage
  }

  if expected.kind == "enum" {
    let mut coverage = emptyPatternCoverage()
    match enumDefinitionForType(state, moduleIndex, expected) {
      case Some(definition) => {
        let mut selected: Option<EnumVariant> = None
        for variant in definition.variants {
          if variant.name == name { selected = Some(variant) }
        }
        match selected {
          case Some(variant) => {
            if arguments.length != variant.payloads.length {
              for argument in arguments {
                let _ = patternBindingTypeAt(
                  service,
                  state,
                  moduleIndex,
                  source,
                  argument,
                  emptyType("unknown"),
                  mutable,
                  false,
                )
              }
              let wanted = if variant.payloads.length == 0 {
                "no subpattern"
              } else {
                "{variant.payloads.length} subpattern" +
                  if variant.payloads.length == 1 { "" } else { "s" }
              }
              addDiagnostic(
                state,
                moduleIndex,
                "TPZ5004",
                "enum variant `{typeText(expected)}.{name}` takes {wanted}, found {arguments.length}",
                "",
                pattern,
              )
            } else if arguments.length == 0 {
              coverage = coverageWithKey("constructor:{name}/*")
            } else if arguments.length == 1 {
              let payload = match variant.payloads.get(0) {
                case Some(found) => substitute(
                  found,
                  definition.typeParameters,
                  expected.arguments,
                )
                case None => emptyType("unknown")
              }
              let nested = match arguments.get(0) {
                case Some(argument) => patternBindingTypeAt(
                  service,
                  state,
                  moduleIndex,
                  source,
                  argument,
                  payload,
                  mutable,
                  false,
                )
                case None => emptyPatternCoverage()
              }
              coverage = prefixPatternCoverage("constructor:{name}", nested)
            } else {
              let mut allIrrefutable = true
              let mut index = 0
              for argument in arguments {
                let payload = match variant.payloads.get(index) {
                  case Some(found) => substitute(
                    found,
                    definition.typeParameters,
                    expected.arguments,
                  )
                  case None => emptyType("unknown")
                }
                let nested = patternBindingTypeAt(
                  service,
                  state,
                  moduleIndex,
                  source,
                  argument,
                  payload,
                  mutable,
                  false,
                )
                allIrrefutable = allIrrefutable && nested.irrefutable
                index += 1
              }
              if allIrrefutable {
                coverage = coverageWithKey("constructor:{name}/*")
              }
            }
          }
          case None => addDiagnostic(
            state,
            moduleIndex,
            "TPZ5001",
            "enum `{typeText(expected)}` has no variant `{name}`" +
              enumVariantSuggestion(definition, name),
            "",
            pattern,
          )
        }
      }
      case None => ()
    }
    addNode(state, moduleIndex, "pattern", pattern, expected)
    return coverage
  }

  let known = name == "Some" || name == "None" ||
    name == "Ok" || name == "Err"
  let correctArity = if name == "None" {
    arguments.length == 0
  } else if known {
    arguments.length == 1
  } else {
    true
  }
  let mut members: Array<TypeValue> = if expected.kind == "union" {
    expected.members
  } else {
    [expected]
  }
  let mut payloads: Array<TypeValue> = []
  let mut matchable = false
  for member in members {
    if name == "Some" && member.kind == "constructor" &&
      member.name == "Option" && correctArity {
      matchable = true
      payloads.push(typeArgument(member, 0))
    } else if name == "None" && member.kind == "constructor" &&
      member.name == "Option" && correctArity {
      matchable = true
    } else if name == "Ok" && member.kind == "constructor" &&
      member.name == "Result" && correctArity {
      matchable = true
      payloads.push(typeArgument(member, 0))
    } else if name == "Err" && member.kind == "constructor" &&
      member.name == "Result" && correctArity {
      matchable = true
      payloads.push(typeArgument(member, 1))
    } else if (member.kind == "rigid" || member.kind == "foreign") &&
      (!known || correctArity) {
      matchable = true
      if arguments.length > 0 {
        payloads.push(rigid(
          "PayloadOf<{typeText(member)}, {name}>",
          "builtin::constructor-pattern",
        ))
      }
    } else if hasHole(member) && (!known || correctArity) {
      matchable = true
      if arguments.length > 0 { payloads.push(emptyType("unknown")) }
    }
  }
  if known && !correctArity {
    addDiagnostic(
      state,
      moduleIndex,
      "TPZ5004",
      if name == "None" {
        "`None` pattern takes no subpattern"
      } else {
        "`{name}` pattern takes one subpattern"
      },
      "",
      pattern,
    )
  } else if known && !matchable {
    addDiagnostic(
      state,
      moduleIndex,
      "TPZ5001",
      "this pattern can never match `{typeText(expected)}`",
      "",
      pattern,
    )
  }
  let payload = if payloads.length == 0 {
    emptyType("unknown")
  } else {
    unionType(payloads)
  }
  let mut nested = irrefutablePatternCoverage()
  for argument in arguments {
    nested = patternBindingTypeAt(
      service,
      state,
      moduleIndex,
      source,
      argument,
      payload,
      mutable,
      false,
    )
  }
  addNode(state, moduleIndex, "pattern", pattern, expected)
  if matchable && known {
    prefixPatternCoverage("constructor:{name}", nested)
  } else {
    emptyPatternCoverage()
  }
}

function bindListPattern(
  service: CheckerService,
  state: CheckerState,
  moduleIndex: int,
  source: Bytes,
  pattern: SyntaxNode,
  expected: TypeValue,
  mutable: bool,
) -> PatternCoverage {
  let mut members: Array<TypeValue> = if expected.kind == "union" {
    expected.members
  } else {
    [expected]
  }
  let mut itemTypes: Array<TypeValue> = []
  let mut restTypes: Array<TypeValue> = []
  let mut opaque = false
  for member in members {
    if member.kind == "constructor" && member.name == "Array" {
      itemTypes.push(typeArgument(member, 0))
      restTypes.push(member)
    } else if member.kind == "rigid" || member.kind == "foreign" {
      let projected = rigid(
        "ElemOf<{typeText(member)}>",
        "builtin::list-pattern",
      )
      itemTypes.push(projected)
      restTypes.push(constructor("Array", [projected]))
      opaque = true
    } else if hasHole(member) {
      itemTypes.push(emptyType("unknown"))
      restTypes.push(emptyType("unknown"))
      opaque = true
    }
  }
  if itemTypes.length == 0 && !opaque && typeDecidable(expected) {
    addDiagnostic(
      state,
      moduleIndex,
      "TPZ5001",
      "this pattern can never match `{typeText(expected)}`",
      "",
      pattern,
    )
  }
  let item = if itemTypes.length == 0 {
    emptyType("unknown")
  } else {
    unionType(itemTypes)
  }
  let rest = if restTypes.length == 0 {
    emptyType("unknown")
  } else {
    unionType(restTypes)
  }
  let mut elementCount = 0
  let mut onlyRestIrrefutable = false
  for element in children(pattern, "elements") {
    if element.kind == "list-pattern/rest" {
      match child(element, "binding") {
        case Some(found) => {
          let nested = patternBindingTypeAt(
            service,
            state,
            moduleIndex,
            source,
            found,
            rest,
            mutable,
            false,
          )
          onlyRestIrrefutable = nested.irrefutable
        }
        case None => { onlyRestIrrefutable = true }
      }
    } else {
      elementCount += 1
      let _ = patternBindingTypeAt(
        service,
        state,
        moduleIndex,
        source,
        element,
        item,
        mutable,
        false,
      )
    }
  }
  addNode(state, moduleIndex, "pattern", pattern, expected)
  if expected.kind == "constructor" && expected.name == "Array" &&
    elementCount == 0 && children(pattern, "elements").length == 1 &&
    onlyRestIrrefutable {
    irrefutablePatternCoverage()
  } else {
    emptyPatternCoverage()
  }
}

function disconnectedPatternTypes(values: Array<TypeValue>) -> bool {
  if values.length < 2 { return false }
  let mut reached: Array<bool> = []
  let mut index = 0
  while index < values.length {
    reached.push(index == 0)
    index += 1
  }
  let mut stack: Array<int> = [0]
  while stack.length > 0 {
    let current = match stack.pop() {
      case Some(found) => found
      case None => 0
    }
    let currentType = match values.get(current) {
      case Some(found) => found
      case None => emptyType("unknown")
    }
    index = 0
    while index < values.length {
      let seen = match reached.get(index) {
        case Some(found) => found
        case None => false
      }
      let candidate = match values.get(index) {
        case Some(found) => found
        case None => emptyType("unknown")
      }
      if !seen && (hasHole(currentType) || hasHole(candidate) ||
        typesOverlap(currentType, candidate)) {
        reached[index] = true
        stack.push(index)
      }
      index += 1
    }
  }
  for seen in reached {
    if !seen { return true }
  }
  false
}

function bindOrPattern(
  service: CheckerService,
  state: CheckerState,
  moduleIndex: int,
  source: Bytes,
  pattern: SyntaxNode,
  expected: TypeValue,
  mutable: bool,
  topLevel: bool,
) -> PatternCoverage {
  let alternatives = children(pattern, "alternatives")
  let mut coverage = emptyPatternCoverage()
  for alternative in alternatives {
    for binding in patternAlternativeBindingNodes(
      state,
      moduleIndex,
      source,
      alternative,
      expected,
    ) {
      let name = text(source, binding)
      let mut presentEverywhere = true
      for other in alternatives {
        if !patternAlternativeHasBinding(
          state,
          moduleIndex,
          source,
          other,
          expected,
          name,
        ) {
          presentEverywhere = false
        }
      }
      if !presentEverywhere {
        addDiagnostic(
          state,
          moduleIndex,
          "TPZ5710",
          "or-pattern alternatives must bind the same names — `{name}` is bound in one alternative but not another",
          "",
          alternative,
        )
      }
    }
    let nested = patternBindingTypeAt(
      service,
      state,
      moduleIndex,
      source,
      alternative,
      expected,
      mutable,
      topLevel,
    )
    coverage = mergePatternCoverage(coverage, nested)
  }
  // The resolver traversal coalesces names across alternatives while retaining
  // repeated bindings inside each alternative. Variant patterns are not bindings.
  let mut bindingNodes: Array<SyntaxNode> = []
  collectPatternBindings(pattern, source, bindingNodes)
  let mut declaredNames: Array<string> = []
  for binding in bindingNodes {
    match symbolTypeAt(state, moduleIndex, binding.lo, binding.hi) {
      case Some(_) => {
        let name = text(source, binding)
        if containsString(declaredNames, name) {
          addDiagnostic(state, moduleIndex, "TPZ5008", "`{name}` is already declared in this scope", "", binding)
        } else { declaredNames.push(name) }
      }
      case None => ()
    }
  }
  let mut names: Array<string> = []
  for alternative in alternatives {
    for binding in patternAlternativeBindingNodes(
      state,
      moduleIndex,
      source,
      alternative,
      expected,
    ) {
      let name = text(source, binding)
      if !containsString(names, name) { names.push(name) }
    }
  }
  for name in names {
    let mut types: Array<TypeValue> = []
    let mut bindings: Array<SyntaxNode> = []
    for alternative in alternatives {
      for binding in patternAlternativeBindingNodes(
        state,
        moduleIndex,
        source,
        alternative,
        expected,
      ) {
        if text(source, binding) == name {
          bindings.push(binding)
          match symbolTypeAt(
            state,
            moduleIndex,
            binding.lo,
            binding.hi,
          ) {
            case Some(found) => types.push(found)
            case None => ()
          }
        }
      }
    }
    if types.length == alternatives.length && disconnectedPatternTypes(types) {
      let first = match types.get(0) {
        case Some(found) => found
        case None => emptyType("unknown")
      }
      let mut conflicting = first
      for candidate in types {
        if !typesOverlap(first, candidate) {
          conflicting = candidate
        }
      }
      let diagnosticNode = match alternatives.get(0) {
        case Some(found) => found
        case None => pattern
      }
      addDiagnostic(
        state,
        moduleIndex,
        "TPZ5711",
        "binding `{name}` has type `{typeText(first)}` in one or-pattern alternative and `{typeText(conflicting)}` in another",
        "",
        diagnosticNode,
      )
    }
    if types.length > 0 {
      let unified = unionType(types)
      for binding in bindings {
        bindSymbol(
          state,
          moduleIndex,
          binding.lo,
          binding.hi,
          name,
          unified,
          mutable,
        )
      }
    }
  }
  addNode(state, moduleIndex, "pattern", pattern, expected)
  coverage
}

export function patternBindingTypeAt(
  service: CheckerService,
  state: CheckerState,
  moduleIndex: int,
  source: Bytes,
  pattern: SyntaxNode,
  expected: TypeValue,
  mutable: bool,
  topLevel: bool,
) -> PatternCoverage {
  match pattern.kind {
    case "pattern/literal" | "pattern/range" =>
      checkLiteralPattern(service, state, moduleIndex, source, pattern, expected)
    case "pattern/binding" => {
      let nameNode = match child(pattern, "name") {
        case Some(found) => found
        case None => pattern
      }
      let name = text(source, nameNode)
      match enumDefinitionForType(state, moduleIndex, expected) {
        case Some(definition) => {
          let mut variant: Option<EnumVariant> = None
          for found in definition.variants {
            if found.name == name { variant = Some(found) }
          }
          match variant {
            case Some(found) => {
              if found.payloads.length > 0 {
                let underscores: Array<string> = []
                let mut parts = underscores
                let mut index = 0
                while index < found.payloads.length {
                  parts.push("_")
                  index += 1
                }
                addDiagnostic(
                  state,
                  moduleIndex,
                  "TPZ5004",
                  "enum variant `{typeText(expected)}.{name}` carries {found.payloads.length} payload" +
                    if found.payloads.length == 1 { "" } else { "s" } +
                    " — write `case {name}(" + stringJoin(parts, ", ") + ")` to match it",
                  "",
                  nameNode,
                )
              }
              addNode(state, moduleIndex, "pattern", pattern, expected)
              return coverageWithKey("constructor:{name}/*")
            }
            case None => if topLevel {
              addDiagnostic(
                state,
                moduleIndex,
                "TPZ5001",
                "`{name}` is not a variant of enum `{typeText(expected)}`" +
                  enumVariantSuggestion(definition, name) +
                  " (use `_` for a catch-all)",
                "",
                nameNode,
              )
              addNode(state, moduleIndex, "pattern", pattern, expected)
              return irrefutablePatternCoverage()
            }
          }
        }
        case None => ()
      }
      bindNamedPattern(service, state, moduleIndex, source, pattern, expected, mutable)
    }
    case "pattern/typed" => bindNamedPattern(
      service,
      state,
      moduleIndex,
      source,
      pattern,
      expected,
      mutable,
    )
    case "pattern/record" | "pattern/nominal-record" => bindRecordPattern(
      service,
      state,
      moduleIndex,
      source,
      pattern,
      expected,
      mutable,
    )
    case "pattern/constructor" => bindConstructorPattern(
      service,
      state,
      moduleIndex,
      source,
      pattern,
      expected,
      mutable,
    )
    case "pattern/list" => bindListPattern(
      service,
      state,
      moduleIndex,
      source,
      pattern,
      expected,
      mutable,
    )
    case "pattern/or" => bindOrPattern(
      service,
      state,
      moduleIndex,
      source,
      pattern,
      expected,
      mutable,
      topLevel,
    )
    case "pattern/wildcard" => {
      addNode(state, moduleIndex, "pattern", pattern, expected)
      irrefutablePatternCoverage()
    }
    case _ => {
      addNode(state, moduleIndex, "pattern", pattern, expected)
      emptyPatternCoverage()
    }
  }
}

export function patternBindingType(
  service: CheckerService,
  state: CheckerState,
  moduleIndex: int,
  source: Bytes,
  pattern: SyntaxNode,
  expected: TypeValue,
  mutable: bool,
) -> PatternCoverage {
  patternBindingTypeAt(
    service,
    state,
    moduleIndex,
    source,
    pattern,
    expected,
    mutable,
    false,
  )
}

