function diagnosticWithNotes(
  code: string,
  message: string,
  lo: int,
  hi: int,
  notes: Array<string>,
) -> PreviewDiagnostic {
  PreviewDiagnostic { code: code, message: message, lo: lo, hi: hi, notes: notes }
}

function nullAttribute(name: string) -> PreviewAstAttribute {
  PreviewAstAttribute { name: name, kind: "null", value: "" }
}

function binaryPrecedence(kind: string) -> int {
  match kind {
    case "pipe-gt" => 1
    case "gt-gt" => 2
    case "question-question" => 3
    case "or-or" => 4
    case "and-and" => 5
    case "eq-eq" | "not-eq" => 6
    case "lt" | "le" | "gt" | "ge" | "keyword/in" => 6
    case "dot-dot" | "dot-dot-lt" => 7
    case "plus" | "minus" => 8
    case "star" | "slash" | "percent" => 9
    case _ => 0
  }
}

function binaryName(kind: string) -> string {
  match kind {
    case "plus" => "add"
    case "minus" => "subtract"
    case "star" => "multiply"
    case "slash" => "divide"
    case "percent" => "remainder"
    case "lt" => "less-than"
    case "le" => "less-or-equal"
    case "gt" => "greater-than"
    case "ge" => "greater-or-equal"
    case "eq-eq" => "equal"
    case "not-eq" => "not-equal"
    case "keyword/in" => "in"
    case "and-and" => "and"
    case "or-or" => "or"
    case "question-question" => "coalesce"
    case _ => ""
  }
}

function parseCallArguments(
  service: ParserService,
  parser: Parser,
) -> Result<Array<SyntaxNode>, string> {
  expect(parser, "left-paren", "`(`")?
  let mut arguments: Array<SyntaxNode> = []
  let mut index = 0
  while !at(parser, "right-paren") && !at(parser, "eof") {
    if eat(parser, "ellipsis") {
      let value = parseNestedExpression(service, parser, "value", 0)?
      arguments.push(node(
        "call-argument/spread",
        value.lo,
        value.hi,
        "arguments",
        index,
        [],
        [value],
      ))
    } else if at(parser, "identifier") && tokenAt(parser, 1).kind == "colon" {
      let name = bump(parser)
      bump(parser)
      let value = parseNestedExpression(service, parser, "value", 0)?
      arguments.push(node(
        "call-argument/named",
        name.lo,
        value.hi,
        "arguments",
        index,
        [],
        [identNode(name, "name", 0), value],
      ))
    } else {
      arguments.push(parseNestedExpression(service, parser, "arguments", index)?)
    }
    index += 1
    if !eat(parser, "comma") {
      break
    }
  }
  expect(parser, "right-paren", "`)`")?
  Ok(arguments)
}

function looksLikeCallTypeArguments(parser: Parser) -> bool {
  if !at(parser, "lt") {
    return false
  }
  let mut angle = 0
  let mut paren = 0
  let mut brace = 0
  let mut offset = 0
  let mut sawTypeToken = false
  while true {
    let token = tokenAt(parser, offset)
    if token.kind == "lt" {
      angle += 1
    } else if token.kind == "gt" || token.kind == "gt-gt" {
      if paren != 0 || brace != 0 {
        return false
      }
      if token.kind == "gt-gt" {
        angle -= 2
      } else {
        angle -= 1
      }
      if angle <= 0 {
        let next = tokenAt(parser, offset + 1)
        return angle == 0 && sawTypeToken &&
          next.kind == "left-paren" && token.hi == next.lo
      }
      sawTypeToken = true
    } else if token.kind == "left-paren" {
      paren += 1
      sawTypeToken = true
    } else if token.kind == "right-paren" {
      paren -= 1
      if paren < 0 {
        return false
      }
    } else if token.kind == "left-brace" {
      brace += 1
      sawTypeToken = true
    } else if token.kind == "right-brace" {
      brace -= 1
      if brace < 0 {
        return false
      }
    } else if token.kind == "identifier" || token.kind == "dot" ||
      token.kind == "thin-arrow" || token.kind == "ellipsis" ||
      token.kind == "pipe" || token.kind == "colon" ||
      token.kind == "integer" || token.kind == "float" ||
      token.kind == "keyword/true" || token.kind == "keyword/false" ||
      token.kind == "keyword/null" || token.kind == "string-end" ||
      token.kind == "string-text" || token.kind.startsWith("string-start/") {
      sawTypeToken = true
    } else if token.kind != "comma" {
      return false
    }
    offset += 1
  }
  false
}

function parseLambdaParameters(
  service: ParserService,
  parser: Parser,
) -> Result<Array<SyntaxNode>, string> {
  let mut parameters: Array<SyntaxNode> = []
  let mut index = 0
  while !at(parser, "right-paren") && !at(parser, "eof") {
    let lo = current(parser).lo
    let name = identifier(parser, "a parameter name")?
    rejectReservedBinding(parser, name)
    let mut children: Array<SyntaxNode> = [identNode(name, "name", 0)]
    if eat(parser, "colon") {
      children.push(parseType(service, parser, "type", 0)?)
    }
    parameters.push(node(
      "lambda-parameter",
      lo,
      boxValue(parser.lastHi),
      "parameters",
      index,
      [],
      children,
    ))
    index += 1
    if !eat(parser, "comma") {
      break
    }
  }
  Ok(parameters)
}

function parseSingleLambda(
  service: ParserService,
  parser: Parser,
  field: string,
  index: int,
) -> Result<SyntaxNode, string> {
  let name = identifier(parser, "a parameter name")?
  rejectReservedBinding(parser, name)
  expect(parser, "fat-arrow", "`=>`")?
  let body = parseExpression(service, parser, "body", 0)?
  Ok(node(
    "expression/lambda",
    name.lo,
    body.hi,
    field,
    index,
    [],
    [
      node(
        "lambda-parameter",
        name.lo,
        name.hi,
        "parameters",
        0,
        [],
        [identNode(name, "name", 0)],
      ),
      body,
    ],
  ))
}

function parseParenLambda(
  service: ParserService,
  parser: Parser,
  field: string,
  index: int,
) -> Result<SyntaxNode, string> {
  let open = expect(parser, "left-paren", "`(`")?
  let mut children = parseLambdaParameters(service, parser)?
  expect(parser, "right-paren", "`)`")?
  expect(parser, "fat-arrow", "`=>`")?
  let body = parseExpression(service, parser, "body", 0)?
  let hi = body.hi
  children.push(body)
  Ok(node("expression/lambda", open.lo, hi, field, index, [], children))
}

function parseArray(
  service: ParserService,
  parser: Parser,
  field: string,
  index: int,
) -> Result<SyntaxNode, string> {
  let open = expect(parser, "left-bracket", "`[`")?
  let mut elements: Array<SyntaxNode> = []
  let mut elementIndex = 0
  while !at(parser, "right-bracket") && !at(parser, "eof") {
    if eat(parser, "ellipsis") {
      let value = parseNestedExpression(service, parser, "value", 0)?
      elements.push(node(
        "array-element/spread",
        value.lo,
        value.hi,
        "elements",
        elementIndex,
        [],
        [value],
      ))
    } else {
      elements.push(parseNestedExpression(service, parser, "elements", elementIndex)?)
    }
    elementIndex += 1
    if !eat(parser, "comma") {
      break
    }
  }
  let close = expect(parser, "right-bracket", "`]`")?
  Ok(node(
    "expression/array",
    open.lo,
    close.hi,
    field,
    index,
    [],
    elements,
  ))
}

function parseFieldInitializers(
  service: ParserService,
  parser: Parser,
  rejectRecordSpread: bool,
) -> Result<Array<SyntaxNode>, string> {
  let mut fields: Array<SyntaxNode> = []
  let mut fieldIndex = 0
  while !at(parser, "right-brace") && !at(parser, "eof") {
    if rejectRecordSpread && at(parser, "ellipsis") {
      let spread = current(parser)
      addDiagnostic(
        parser,
        "TPZ2001",
        "a record spread `...` must be the FIRST element and appear at most once",
        spread.lo,
        spread.hi,
      )
      recoverToMatchingRightBrace(parser)
      break
    }
    let name = fieldName(parser, "a field name")?
    expect(parser, "colon", "`:`")?
    let value = parseNestedExpression(service, parser, "value", 0)?
    fields.push(node(
      "field-initializer",
      name.lo,
      value.hi,
      "fields",
      fieldIndex,
      [],
      [identNode(name, "name", 0), value],
    ))
    fieldIndex += 1
    if !eat(parser, "comma") {
      break
    }
  }
  Ok(fields)
}

function parseRecordLiteral(
  service: ParserService,
  parser: Parser,
  field: string,
  index: int,
) -> Result<SyntaxNode, string> {
  let open = expectLeftBrace(parser)?
  let children = parseFieldInitializers(service, parser, false)?
  let close = expectRightBrace(parser)?
  Ok(node(
    "expression/record-literal",
    open.lo,
    close.hi,
    field,
    index,
    [],
    children,
  ))
}

function parseRecordUpdate(
  service: ParserService,
  parser: Parser,
  base: SyntaxNode,
  field: string,
  index: int,
) -> Result<SyntaxNode, string> {
  expectLeftBrace(parser)?
  let mut children: Array<SyntaxNode> = [attach(base, "base", 0)]
  if eat(parser, "ellipsis") {
    children.push(parseNestedExpression(service, parser, "spread", 0)?)
    if !at(parser, "right-brace") && !eat(parser, "comma") {
      let token = current(parser)
      addDiagnostic(parser, "TPZ2001", "expected `,` or `\}`", token.lo, token.hi)
      recoverToMatchingRightBrace(parser)
    }
  }
  for found in parseFieldInitializers(service, parser, true)? {
    children.push(found)
  }
  let close = expectRightBrace(parser)?
  Ok(node(
    "expression/record-update",
    base.lo,
    close.hi,
    field,
    index,
    [],
    children,
  ))
}

function parseComprehensionClauses(
  service: ParserService,
  parser: Parser,
) -> Result<Array<SyntaxNode>, string> {
  let mut clauses: Array<SyntaxNode> = []
  let mut clauseIndex = 0
  while true {
    if eat(parser, "keyword/for") {
      let pattern = parsePattern(service, parser, "pattern", 0)?
      expect(parser, "keyword/in", "`in`")?
      let iterator = parseExpressionWithoutNakedLambda(service, parser, "iterator", 0)?
      clauses.push(node(
        "comprehension-clause/for",
        pattern.lo,
        iterator.hi,
        "clauses",
        clauseIndex,
        [],
        [pattern, iterator],
      ))
      clauseIndex += 1
      continue
    }
    if eat(parser, "keyword/if") {
      let condition = parseExpressionWithoutNakedLambda(service, parser, "condition", 0)?
      clauses.push(node(
        "comprehension-clause/if",
        condition.lo,
        condition.hi,
        "clauses",
        clauseIndex,
        [],
        [condition],
      ))
      clauseIndex += 1
      continue
    }
    break
  }
  expect(parser, "fat-arrow", "`=>` to introduce the comprehension body")?
  Ok(clauses)
}

function parseArrayComprehension(
  service: ParserService,
  parser: Parser,
  field: string,
  index: int,
) -> Result<SyntaxNode, string> {
  let open = expect(parser, "left-bracket", "`[`")?
  let mut children = parseComprehensionClauses(service, parser)?
  children.push(parseNestedExpression(service, parser, "body", 0)?)
  let close = expect(parser, "right-bracket", "`]`")?
  Ok(node(
    "expression/comprehension",
    open.lo,
    close.hi,
    field,
    index,
    [stringAttribute("collection", "array")],
    children,
  ))
}

function parseSetComprehension(
  service: ParserService,
  parser: Parser,
  field: string,
  index: int,
) -> Result<SyntaxNode, string> {
  let head = identifier(parser, "`set`")?
  expectLeftBrace(parser)?
  let mut children = parseComprehensionClauses(service, parser)?
  children.push(parseNestedExpression(service, parser, "body", 0)?)
  let close = expectRightBrace(parser)?
  Ok(node(
    "expression/comprehension",
    head.lo,
    close.hi,
    field,
    index,
    [stringAttribute("collection", "set")],
    children,
  ))
}

function parseMapComprehension(
  service: ParserService,
  parser: Parser,
  field: string,
  index: int,
) -> Result<SyntaxNode, string> {
  let head = identifier(parser, "`map`")?
  expectLeftBrace(parser)?
  let mut children = parseComprehensionClauses(service, parser)?
  children.push(parseNestedExpression(service, parser, "bodyKey", 0)?)
  expect(parser, "colon", "`:` (a map comprehension body is `key: value`)")?
  children.push(parseNestedExpression(service, parser, "bodyValue", 0)?)
  let close = expectRightBrace(parser)?
  Ok(node(
    "expression/comprehension",
    head.lo,
    close.hi,
    field,
    index,
    [stringAttribute("collection", "map")],
    children,
  ))
}

function parseSet(
  service: ParserService,
  parser: Parser,
  field: string,
  index: int,
) -> Result<SyntaxNode, string> {
  let head = identifier(parser, "`set`")?
  expectLeftBrace(parser)?
  let mut elements: Array<SyntaxNode> = []
  let mut elementIndex = 0
  while !at(parser, "right-brace") && !at(parser, "eof") {
    elements.push(parseNestedExpression(service, parser, "elements", elementIndex)?)
    elementIndex += 1
    if !eat(parser, "comma") {
      break
    }
  }
  let close = expectRightBrace(parser)?
  Ok(node("expression/set", head.lo, close.hi, field, index, [], elements))
}

function parseMap(
  service: ParserService,
  parser: Parser,
  field: string,
  index: int,
) -> Result<SyntaxNode, string> {
  let head = identifier(parser, "`map`")?
  expectLeftBrace(parser)?
  let mut entries: Array<SyntaxNode> = []
  let mut entryIndex = 0
  while !at(parser, "right-brace") && !at(parser, "eof") {
    let key = parseNestedExpression(service, parser, "key", 0)?
    expect(parser, "colon", "`:`")?
    let value = parseNestedExpression(service, parser, "value", 0)?
    entries.push(node(
      "map-entry",
      key.lo,
      value.hi,
      "entries",
      entryIndex,
      [],
      [key, value],
    ))
    entryIndex += 1
    if !eat(parser, "comma") {
      break
    }
  }
  let close = expectRightBrace(parser)?
  Ok(node("expression/map", head.lo, close.hi, field, index, [], entries))
}

export function blockExpression(block: SyntaxNode, field: string, index: int) -> SyntaxNode {
  node(
    "expression/block",
    block.lo,
    block.hi,
    field,
    index,
    [],
    [attach(block, "block", 0)],
  )
}

function parseIfLet(
  service: ParserService,
  parser: Parser,
  keyword: PreviewToken,
  field: string,
  index: int,
) -> Result<SyntaxNode, string> {
  expect(parser, "keyword/let", "`let`")?
  let pattern = parsePattern(service, parser, "pattern", 0)?
  expect(parser, "eq", "`=`")?
  let scrutinee = parseExpressionBeforeBlock(service, parser, "scrutinee", 0)?
  let thenBlock = invokeParseBlock(service, parser, "block", 0)?
  let thenExpression = blockExpression(thenBlock, "body", 0)
  let mut elseExpression = node(
    "expression/unit",
    thenBlock.hi,
    thenBlock.hi,
    "body",
    0,
    [],
    [],
  )
  if eat(parser, "keyword/else") {
    elseExpression = if at(parser, "keyword/if") {
      parseIf(service, parser, "body", 0)?
    } else {
      let block = invokeParseBlock(service, parser, "block", 0)?
      blockExpression(block, "body", 0)
    }
  }
  let hi = elseExpression.hi
  let wholeLo = keyword.lo
  let firstCase = node(
    "match-case",
    wholeLo,
    hi,
    "cases",
    0,
    [],
    [pattern, thenExpression],
  )
  let wildcard = node("pattern/wildcard", wholeLo, hi, "pattern", 0, [], [])
  let secondCase = node(
    "match-case",
    wholeLo,
    hi,
    "cases",
    1,
    [],
    [wildcard, elseExpression],
  )
  Ok(node(
    "expression/match",
    wholeLo,
    hi,
    field,
    index,
    [],
    [scrutinee, firstCase, secondCase],
  ))
}

function parseIf(
  service: ParserService,
  parser: Parser,
  field: string,
  index: int,
) -> Result<SyntaxNode, string> {
  let keyword = expect(parser, "keyword/if", "`if`")?
  if at(parser, "keyword/let") {
    return parseIfLet(service, parser, keyword, field, index)
  }
  let condition = parseExpressionBeforeBlock(service, parser, "condition", 0)?
  let thenBlock = invokeParseBlock(service, parser, "then", 0)?
  let mut children: Array<SyntaxNode> = [condition, thenBlock]
  let mut hi = thenBlock.hi
  if eat(parser, "keyword/else") {
    let elseValue = if at(parser, "keyword/if") {
      parseIf(service, parser, "else", 0)?
    } else {
      let block = invokeParseBlock(service, parser, "block", 0)?
      blockExpression(block, "else", 0)
    }
    hi = elseValue.hi
    children.push(elseValue)
  }
  Ok(node("expression/if", keyword.lo, hi, field, index, [], children))
}

function parseFor(
  service: ParserService,
  parser: Parser,
  field: string,
  index: int,
) -> Result<SyntaxNode, string> {
  let keyword = expect(parser, "keyword/for", "`for`")?
  let pattern = parsePattern(service, parser, "pattern", 0)?
  expect(parser, "keyword/in", "`in`")?
  let iterator = parseExpressionBeforeBlock(service, parser, "iterator", 0)?
  let body = invokeParseBlock(service, parser, "body", 0)?
  Ok(node(
    "expression/for",
    keyword.lo,
    body.hi,
    field,
    index,
    [],
    [pattern, iterator, body],
  ))
}

export function labelNode(value: PreviewToken, field: string, index: int) -> SyntaxNode {
  node("identifier", value.lo + 1, value.hi, field, index, [], [])
}

function parseLoop(
  service: ParserService,
  parser: Parser,
  field: string,
  index: int,
) -> Result<SyntaxNode, string> {
  let head = identifier(parser, "`loop`")?
  let mut children: Array<SyntaxNode> = []
  if at(parser, "label") {
    children.push(labelNode(bump(parser), "label", 0))
  }
  let body = invokeParseBlock(service, parser, "body", 0)?
  let hi = body.hi
  children.push(body)
  Ok(node("expression/loop", head.lo, hi, field, index, [], children))
}

function parseConcurrentTimeout(parser: Parser) -> Result<Option<SyntaxNode>, string> {
  if !at(parser, "left-paren") {
    return Ok(None)
  }
  bump(parser)
  let key = identifier(parser, "`timeout`")?
  if text(parser, key.lo, key.hi) != "timeout" {
    addDiagnostic(
      parser,
      "TPZ2005",
      "`concurrent` takes only a `timeout:` argument",
      key.lo,
      key.hi,
    )
  }
  if !eat(parser, "colon") {
    let token = current(parser)
    addDiagnostic(parser, "TPZ2001", "expected `:` after `timeout`", token.lo, token.hi)
  }
  let duration = current(parser)
  let mut durationHi = duration.hi
  let mut unit = "s"
  let mut valueAttribute = nullAttribute("valueDecimal")
  if duration.kind.startsWith("duration/") {
    unit = duration.kind.replace("duration/", "")
    let spelling = text(parser, duration.lo, duration.hi)
    let magnitude = spelling.replace(unit, "")
    if !validIntegerLiteral(magnitude) || (parser.languageMode != "topaz-5.21" && magnitude.contains("_")) { fail(parser,"malformed numeric literal")? }
    bump(parser)
    valueAttribute = stringAttribute("valueDecimal", magnitude.replace("_", ""))
  } else {
    addDiagnostic(
      parser,
      "TPZ2001",
      "expected a duration literal, e.g. `3s`",
      duration.lo,
      duration.hi,
    )
    recoverToMatchingRightParen(parser, false)
    let recoveredHi = boxValue(parser.lastHi)
    if recoveredHi > durationHi {
      durationHi = recoveredHi
    }
  }
  let value = node(
    "expression/duration",
    duration.lo,
    durationHi,
    "timeout",
    0,
    [
      stringAttribute("unit", unit),
      valueAttribute,
    ],
    [],
  )
  expect(parser, "right-paren", "`)`")?
  Ok(Some(value))
}

function parseConcurrentArm(
  service: ParserService,
  parser: Parser,
  index: int,
) -> Result<SyntaxNode, string> {
  let name = identifier(parser, "an arm name")?
  expect(parser, "colon", "`:`")?
  let value = parseNestedExpression(service, parser, "value", 0)?
  Ok(node(
    "concurrent-arm",
    name.lo,
    value.hi,
    "arms",
    index,
    [],
    [identNode(name, "name", 0), value],
  ))
}

function parseConcurrentArms(
  service: ParserService,
  parser: Parser,
  keyword: PreviewToken,
) -> Result<Array<SyntaxNode>, string> {
  expectLeftBrace(parser)?
  let mut arms: Array<SyntaxNode> = []
  skipSeparators(parser)
  while !at(parser, "right-brace") && !at(parser, "eof") {
    let before = boxValue(parser.position)
    match parseConcurrentArm(service, parser, arms.length) {
      case Ok(arm) => {
        arms.push(arm)
        itemBoundary(parser)
      }
      case Err(_) => synchronize(parser)
    }
    if boxValue(parser.position) == before &&
      !at(parser, "right-brace") && !at(parser, "eof") {
      addDiagnostic(
        parser,
        "TPZ2001",
        "expected a concurrent arm",
        current(parser).lo,
        current(parser).hi,
      )
      bump(parser)
    }
    skipSeparators(parser)
  }
  expectRightBrace(parser)?
  if arms.length == 0 {
    addDiagnostic(
      parser,
      "TPZ2001",
      "`concurrent` requires at least one arm",
      keyword.lo,
      boxValue(parser.lastHi),
    )
  }
  Ok(arms)
}

function parseConcurrentElse(
  service: ParserService,
  parser: Parser,
  keyword: PreviewToken,
  hasTimeout: bool,
) -> Result<Option<SyntaxNode>, string> {
  let elseToken = current(parser)
  if eat(parser, "keyword/else") {
    if !hasTimeout {
      addDiagnostic(
        parser,
        "TPZ2005",
        "`else` requires the `concurrent(timeout: ...)` form",
        elseToken.lo,
        elseToken.hi,
      )
    }
    return Ok(Some(invokeParseBlock(service, parser, "else", 0)?))
  }
  if hasTimeout {
    addDiagnostic(
      parser,
      "TPZ2005",
      "the `concurrent(timeout: ...)` form requires an `else` block",
      keyword.lo,
      boxValue(parser.lastHi),
    )
  }
  Ok(None)
}

function parseConcurrent(
  service: ParserService,
  parser: Parser,
  field: string,
  index: int,
) -> Result<SyntaxNode, string> {
  let keyword = expect(parser, "keyword/concurrent", "`concurrent`")?
  let mut children: Array<SyntaxNode> = []
  let timeout = parseConcurrentTimeout(parser)?
  let mut hasTimeout = false
  match timeout {
    case Some(value) => {
      hasTimeout = true
      children.push(value)
    }
    case None => ()
  }
  for arm in parseConcurrentArms(service, parser, keyword)? {
    children.push(arm)
  }
  match parseConcurrentElse(service, parser, keyword, hasTimeout)? {
    case Some(value) => children.push(value)
    case None => ()
  }
  Ok(node(
    "expression/concurrent",
    keyword.lo,
    boxValue(parser.lastHi),
    field,
    index,
    [],
    children,
  ))
}

function parseMatchCase(
  service: ParserService,
  parser: Parser,
  index: int,
) -> Result<SyntaxNode, string> {
  let keyword = expect(parser, "keyword/case", "`case`")?
  let pattern = parsePattern(service, parser, "pattern", 0)?
  let mut children: Array<SyntaxNode> = [pattern]
  if eat(parser, "keyword/if") {
    children.push(parseExpressionWithoutNakedLambda(service, parser, "guard", 0)?)
  }
  expect(parser, "fat-arrow", "`=>`")?
  let hi = if at(parser, "keyword/return") {
    let returnToken = bump(parser)
    let mut returnChildren: Array<SyntaxNode> = []
    if !at(parser, "separator") && !at(parser, "right-brace") && !at(parser, "eof") {
      returnChildren.push(parseNestedExpression(service, parser, "value", 0)?)
    }
    let returnHi = boxValue(parser.lastHi)
    children.push(node(
      "match-case-return",
      returnToken.lo,
      returnHi,
      "body",
      0,
      [],
      returnChildren,
    ))
    returnHi
  } else {
    let body = parseNestedExpression(service, parser, "body", 0)?
    let bodyHi = body.hi
    children.push(body)
    bodyHi
  }
  Ok(node("match-case", keyword.lo, hi, "cases", index, [], children))
}

function parseMatch(
  service: ParserService,
  parser: Parser,
  field: string,
  index: int,
) -> Result<SyntaxNode, string> {
  let keyword = expect(parser, "keyword/match", "`match`")?
  let scrutinee = parseExpressionBeforeBlock(service, parser, "scrutinee", 0)?
  let open = expectLeftBrace(parser)?
  let mut children: Array<SyntaxNode> = [scrutinee]
  let mut caseIndex = 0
  skipSeparators(parser)
  while !at(parser, "right-brace") && !at(parser, "eof") {
    let before = boxValue(parser.position)
    match parseMatchCase(service, parser, caseIndex) {
      case Ok(found) => {
        children.push(found)
        caseIndex += 1
        itemBoundary(parser)
      }
      case Err(_) => synchronize(parser)
    }
    if boxValue(parser.position) == before &&
      !at(parser, "right-brace") && !at(parser, "eof") {
      addDiagnostic(
        parser,
        "TPZ2001",
        "expected `case`",
        current(parser).lo,
        current(parser).hi,
      )
      bump(parser)
    }
    skipSeparators(parser)
  }
  let close = expectRightBrace(parser)?
  if caseIndex == 0 {
    addDiagnostic(
      parser,
      "TPZ2001",
      "`match` requires at least one `case`",
      open.lo,
      close.hi,
    )
  }
  Ok(node(
    "expression/match",
    keyword.lo,
    close.hi,
    field,
    index,
    [],
    children,
  ))
}

function parseIdentifierAtom(
  service: ParserService,
  parser: Parser,
  field: string,
  index: int,
) -> Result<SyntaxNode, string> {
  let value = current(parser)
  if tokenAt(parser, 1).kind == "fat-arrow" && lambdaAllowed(parser) {
    return parseSingleLambda(service, parser, field, index)
  }
  let name = text(parser, value.lo, value.hi)
  if name == "set" && tokenAt(parser, 1).kind == "left-brace" {
    if tokenAt(parser, 2).kind == "keyword/for" {
      return parseSetComprehension(service, parser, field, index)
    }
    return parseSet(service, parser, field, index)
  }
  if name == "map" && tokenAt(parser, 1).kind == "left-brace" {
    if tokenAt(parser, 2).kind == "keyword/for" {
      return parseMapComprehension(service, parser, field, index)
    }
    return parseMap(service, parser, field, index)
  }
  if name == "loop" &&
    (tokenAt(parser, 1).kind == "left-brace" ||
      (tokenAt(parser, 1).kind == "label" && tokenAt(parser, 2).kind == "left-brace")) {
    return parseLoop(service, parser, field, index)
  }
  bump(parser)
  Ok(node("expression/identifier", value.lo, value.hi, field, index, [], []))
}

function parseParenthesizedExpression(
  service: ParserService,
  parser: Parser,
  field: string,
  index: int,
) -> Result<SyntaxNode, string> {
  let openPosition = boxValue(parser.position)
  let open = bump(parser)
  if eat(parser, "right-paren") {
    return Ok(node(
      "expression/unit",
      open.lo,
      boxValue(parser.lastHi),
      field,
      index,
      [],
      [],
    ))
  }
  let inner = parseNestedExpression(service, parser, "operand", 0)?
  if at(parser, "comma") {
    let comma = current(parser)
    let mut diagnostics = parser.diagnostics
    diagnostics.push(diagnosticWithNotes(
      "TPZ2001",
      "parentheses group a single expression; `(a, b)` comma lists are not Topaz syntax",
      comma.lo,
      comma.hi,
      if looksLikeExplicitTypeArgumentsBefore(parser, openPosition) {
        ["Topaz infers type arguments — drop the explicit `<…>`, e.g. `Array.of(…)`"]
      } else {
        []
      },
    ))
    recoverToMatchingRightParen(parser, true)
    return Ok(node(
      "expression/parenthesized",
      open.lo,
      boxValue(parser.lastHi),
      field,
      index,
      [],
      [inner],
    ))
  }
  let close = expect(parser, "right-paren", "`)`")?
  Ok(node(
    "expression/parenthesized",
    open.lo,
    close.hi,
    field,
    index,
    [],
    [inner],
  ))
}

function looksLikeExplicitTypeArgumentsBefore(parser: Parser, leftParenPosition: int) -> bool {
  if leftParenPosition == 0 || layoutTokenAt(parser, leftParenPosition - 1).kind != "gt" {
    return false
  }
  let mut position = leftParenPosition - 1
  let mut depth = 0
  while true {
    let kind = layoutTokenAt(parser, position).kind
    if kind == "gt" {
      depth += 1
    } else if kind == "lt" {
      depth -= 1
      if depth == 0 {
        break
      }
    } else if kind != "identifier" && kind != "comma" {
      return false
    }
    if position == 0 {
      return false
    }
    position -= 1
  }
  position > 0 && layoutTokenAt(parser, position - 1).kind == "identifier"
}

function recoverToMatchingRightParen(parser: Parser, consumeClose: bool) -> () {
  let mut depth = 0
  while !at(parser, "eof") {
    let kind = current(parser).kind
    if kind == "left-paren" || kind == "left-bracket" || kind == "left-brace" {
      depth += 1
    } else if kind == "right-paren" || kind == "right-bracket" || kind == "right-brace" {
      if depth == 0 {
        if consumeClose && kind == "right-paren" {
          bump(parser)
        }
        return ()
      }
      depth -= 1
    }
    bump(parser)
  }
  ()
}

function recoverToMatchingRightBrace(parser: Parser) -> () {
  let mut depth = 0
  while !at(parser, "eof") {
    let kind = current(parser).kind
    if kind == "left-paren" || kind == "left-bracket" || kind == "left-brace" {
      depth += 1
    } else if kind == "right-paren" || kind == "right-bracket" || kind == "right-brace" {
      if depth == 0 {
        return ()
      }
      depth -= 1
    }
    bump(parser)
  }
  ()
}

function parseCollectionAtom(
  service: ParserService,
  parser: Parser,
  field: string,
  index: int,
) -> Result<SyntaxNode, string> {
  let value = current(parser)
  if value.kind == "left-bracket" {
    if tokenAt(parser, 1).kind == "keyword/for" {
      return parseArrayComprehension(service, parser, field, index)
    }
    return parseArray(service, parser, field, index)
  }
  if value.kind == "left-brace" &&
    isFieldNameKind(tokenAt(parser, 1).kind) &&
    tokenAt(parser, 2).kind == "colon" {
    return parseRecordLiteral(service, parser, field, index)
  }
  if value.kind == "left-brace" {
    let block = invokeParseBlock(service, parser, "block", 0)?
    return Ok(node(
      "expression/block",
      block.lo,
      block.hi,
      field,
      index,
      [],
      [block],
    ))
  }
  fail(parser, "expected a collection or block expression")?
  Err("expected a collection or block expression")
}

function parseLiteralAtom(
  parser: Parser,
  field: string,
  index: int,
) -> Result<SyntaxNode, string> {
  let value = current(parser)
  if value.kind == "integer" || value.kind == "float" { validateNumericLiteral(parser, value)? }
  bump(parser)
  if value.kind == "integer" {
    return Ok(node(
      "expression/integer",
      value.lo,
      value.hi,
      field,
      index,
      [stringAttribute("valueDecimal", match integerMagnitude(text(parser, value.lo, value.hi)) { case Some(n) => n.toString(10); case None => "" })],
      [],
    ))
  }
  if value.kind == "float" {
    let bits = floatLiteralBits(text(parser, value.lo, value.hi))
    return Ok(node(
      "expression/float",
      value.lo,
      value.hi,
      field,
      index,
      [if bits != "" && bits != "7ff0000000000000" { stringAttribute("floatBits", bits) } else { nullAttribute("floatBits") }],
      [],
    ))
  }
  if value.kind == "keyword/true" || value.kind == "keyword/false" {
    return Ok(node(
      "expression/boolean",
      value.lo,
      value.hi,
      field,
      index,
      [boolAttribute("value", value.kind == "keyword/true")],
      [],
    ))
  }
  Ok(node("expression/null", value.lo, value.hi, field, index, [], []))
}

function parseAtom(
  service: ParserService,
  parser: Parser,
  field: string,
  index: int,
) -> Result<SyntaxNode, string> {
  let value = current(parser)
  if value.kind.startsWith("length/") {
    if parser.languageMode != "topaz-5.21" { fail(parser,"Length literals require language mode 5.21")? }
    let spelling = text(parser,value.lo,value.hi)
    if !validLiteral(spelling) { fail(parser,"malformed Length literal")? }
    bump(parser)
    return Ok(node("expression/length",value.lo,value.hi,field,index,[stringAttribute("unit",value.kind.replace("length/","")),stringAttribute("spelling",spelling)],[]))
  }
  if value.kind == "integer" || value.kind == "float" ||
    value.kind == "keyword/true" || value.kind == "keyword/false" ||
    value.kind == "keyword/null" {
    return parseLiteralAtom(parser, field, index)
  }
  if value.kind.startsWith("duration/") {
    fail(parser, "a duration literal is valid only in `concurrent(timeout: ...)`")?
  }
  if value.kind == "identifier" {
    return parseIdentifierAtom(service, parser, field, index)
  }
  if value.kind == "underscore" {
    bump(parser)
    return Ok(node(
      "expression/placeholder",
      value.lo,
      value.hi,
      field,
      index,
      [],
      [],
    ))
  }
  if value.kind.startsWith("string-start/") {
    return parseString(service, parser, field, index)
  }
  if value.kind == "left-paren" && lambdaAllowed(parser) &&
    matchingParenFollowedBy(parser, "fat-arrow") {
    return parseParenLambda(service, parser, field, index)
  }
  if value.kind == "left-paren" {
    return parseParenthesizedExpression(service, parser, field, index)
  }
  if value.kind == "left-bracket" || value.kind == "left-brace" {
    return parseCollectionAtom(service, parser, field, index)
  }
  if value.kind == "keyword/if" {
    return parseIf(service, parser, field, index)
  }
  if value.kind == "keyword/match" {
    return parseMatch(service, parser, field, index)
  }
  if value.kind == "keyword/for" {
    return parseFor(service, parser, field, index)
  }
  if value.kind == "keyword/concurrent" {
    return parseConcurrent(service, parser, field, index)
  }
  fail(parser, "expected an expression")?
  Err("expected an expression")
}

function parseCallPostfix(
  service: ParserService,
  parser: Parser,
  callee: SyntaxNode,
  field: string,
  index: int,
  withTypeArguments: bool,
) -> Result<SyntaxNode, string> {
  let typeArguments = if withTypeArguments {
    parseTypeArguments(service, parser)?
  } else {
    []
  }
  let arguments = parseCallArguments(service, parser)?
  let mut children: Array<SyntaxNode> = [attach(callee, "callee", 0)]
  for argument in arguments {
    children.push(argument)
  }
  let mut typeIndex = 0
  for typeArgument in typeArguments {
    children.push(attach(typeArgument, "typeArguments", typeIndex))
    typeIndex += 1
  }
  Ok(node(
    "expression/call",
    callee.lo,
    boxValue(parser.lastHi),
    field,
    index,
    [],
    children,
  ))
}

function parseIndexPostfix(
  service: ParserService,
  parser: Parser,
  object: SyntaxNode,
  field: string,
  index: int,
) -> Result<SyntaxNode, string> {
  bump(parser)
  let found = parseNestedExpression(service, parser, "index", 0)?
  let close = expect(parser, "right-bracket", "`]`")?
  Ok(node(
    "expression/index",
    object.lo,
    close.hi,
    field,
    index,
    [],
    [attach(object, "object", 0), found],
  ))
}

function parseMemberPostfix(
  parser: Parser,
  object: SyntaxNode,
  field: string,
  index: int,
) -> Result<SyntaxNode, string> {
  let optional = at(parser, "question-dot")
  bump(parser)
  let name = fieldName(parser, "a member name")?
  Ok(node(
    if optional { "expression/optional-access" } else { "expression/member" },
    object.lo,
    name.hi,
    field,
    index,
    [],
    [attach(object, "object", 0), identNode(name, "field", 0)],
  ))
}

function tryPostfix(
  parser: Parser,
  operand: SyntaxNode,
  field: string,
  index: int,
) -> SyntaxNode {
  bump(parser)
  node(
    "expression/try",
    operand.lo,
    boxValue(parser.lastHi),
    field,
    index,
    [],
    [attach(operand, "operand", 0)],
  )
}

function startsRecordUpdate(parser: Parser, base: SyntaxNode) -> bool {
  if !recordUpdateAllowed(parser) || !at(parser, "left-brace") {
    return false
  }
  if isFieldNameKind(tokenAt(parser, 1).kind) && tokenAt(parser, 2).kind == "colon" {
    return true
  }
  base.kind == "expression/identifier" &&
    (tokenAt(parser, 1).kind == "ellipsis" || tokenAt(parser, 1).kind == "right-brace")
}

function parsePostfix(
  service: ParserService,
  parser: Parser,
  field: string,
  index: int,
) -> Result<SyntaxNode, string> {
  let mut value = parseAtom(service, parser, field, index)?
  while true {
    if at(parser, "left-paren") {
      value = parseCallPostfix(service, parser, value, field, index, false)?
    } else if at(parser, "lt") &&
      (value.kind == "expression/identifier" ||
        value.kind == "expression/member" ||
        value.kind == "expression/optional-access") &&
      looksLikeCallTypeArguments(parser) {
      value = parseCallPostfix(service, parser, value, field, index, true)?
    } else if at(parser, "left-bracket") {
      value = parseIndexPostfix(service, parser, value, field, index)?
    } else if at(parser, "dot") || at(parser, "question-dot") {
      value = parseMemberPostfix(parser, value, field, index)?
    } else if at(parser, "question") {
      value = tryPostfix(parser, value, field, index)
    } else if startsRecordUpdate(parser, value) {
      value = parseRecordUpdate(service, parser, value, field, index)?
    } else {
      break
    }
  }
  Ok(value)
}

function parseUnary(
  service: ParserService,
  parser: Parser,
  field: string,
  index: int,
) -> Result<SyntaxNode, string> {
  let value = current(parser)
  if value.kind == "plus" || value.kind == "minus" || value.kind == "bang" {
    bump(parser)
    let operand = parseUnary(service, parser, "operand", 0)?
    let operator = match value.kind {
      case "plus" => "plus"
      case "minus" => "minus"
      case _ => "not"
    }
    return Ok(node(
      "expression/unary",
      value.lo,
      operand.hi,
      field,
      index,
      [stringAttribute("operator", operator)],
      [operand],
    ))
  }
  if value.kind == "tilde" {
    let mut diagnostics = parser.diagnostics
    diagnostics.push(diagnostic(
      "TPZ2013",
      "reserved operator `~`: Topaz has no bitwise operations",
      value.lo,
      value.hi,
    ))
    bump(parser)
    return parseUnary(service, parser, field, index)
  }
  let mut lhs = parsePostfix(service, parser, field, index)?
  if eat(parser, "star-star") {
    let rhs = parseUnary(service, parser, "right", 0)?
    lhs = node(
      "expression/binary",
      lhs.lo,
      rhs.hi,
      field,
      index,
      [stringAttribute("operator", "power")],
      [attach(lhs, "left", 0), rhs],
    )
  }
  Ok(lhs)
}

function parsePipeInfix(
  service: ParserService,
  parser: Parser,
  lhs: SyntaxNode,
  precedence: int,
  field: string,
  index: int,
) -> Result<SyntaxNode, string> {
  if eat(parser, "dot") {
    let name = identifier(parser, "a field name")?
    return Ok(node(
      "expression/pipe",
      lhs.lo,
      name.hi,
      field,
      index,
      [],
      [attach(lhs, "left", 0), identNode(name, "field", 0)],
    ))
  }
  let rhs = parseExpressionBp(service, parser, precedence + 1, "right", 0)?
  Ok(node(
    "expression/pipe",
    lhs.lo,
    rhs.hi,
    field,
    index,
    [],
    [attach(lhs, "left", 0), rhs],
  ))
}

function parseComposeInfix(
  service: ParserService,
  parser: Parser,
  lhs: SyntaxNode,
  precedence: int,
  field: string,
  index: int,
) -> Result<SyntaxNode, string> {
  let rhs = parseExpressionBp(service, parser, precedence, "right", 0)?
  Ok(node(
    "expression/compose",
    lhs.lo,
    rhs.hi,
    field,
    index,
    [],
    [attach(lhs, "left", 0), rhs],
  ))
}

function parseRangeInfix(
  service: ParserService,
  parser: Parser,
  lhs: SyntaxNode,
  precedence: int,
  field: string,
  index: int,
) -> Result<SyntaxNode, string> {
  let operator = layoutTokenAt(parser, boxValue(parser.position) - 1)
  let kind = current(parser).kind
  let missingEndpoint = kind == "separator" || kind == "eof" ||
    kind == "right-paren" || kind == "right-brace" || kind == "right-bracket" ||
    kind == "comma" || kind == "fat-arrow" ||
    (kind.startsWith("keyword/") && kind != "keyword/if" && kind != "keyword/match" &&
      kind != "keyword/for" && kind != "keyword/concurrent" &&
      kind != "keyword/true" && kind != "keyword/false" && kind != "keyword/null")
  let rhs = if missingEndpoint {
    addDiagnostic(
      parser,
      "TPZ2001",
      "expected a range endpoint after `..`, e.g. `1..5`",
      operator.lo,
      operator.hi,
    )
    attach(lhs, "high", 0)
  } else {
    parseExpressionBp(service, parser, precedence + 1, "high", 0)?
  }
  let mut children: Array<SyntaxNode> = [attach(lhs, "low", 0), rhs]
  if eat(parser, "keyword/by") {
    children.push(parseExpressionBp(service, parser, precedence + 1, "step", 0)?)
  }
  let hi = if missingEndpoint && children.length == 2 {
    operator.hi
  } else {
    match children.get(children.length - 1) {
      case Some(last) => last.hi
      case None => rhs.hi
    }
  }
  Ok(node(
    "expression/range",
    lhs.lo,
    hi,
    field,
    index,
    [boolAttribute("inclusive", operator.kind == "dot-dot")],
    children,
  ))
}

function parseBinaryInfix(
  service: ParserService,
  parser: Parser,
  lhs: SyntaxNode,
  operator: string,
  precedence: int,
  field: string,
  index: int,
) -> Result<SyntaxNode, string> {
  let rhs = parseExpressionBp(service, parser, precedence + 1, "right", 0)?
  Ok(node(
    "expression/binary",
    lhs.lo,
    rhs.hi,
    field,
    index,
    [stringAttribute("operator", binaryName(operator))],
    [attach(lhs, "left", 0), rhs],
  ))
}

export function parseExpressionBp(
  service: ParserService,
  parser: Parser,
  minimum: int,
  field: string,
  index: int,
) -> Result<SyntaxNode, string> {
  let mut lhs = parseUnary(service, parser, field, index)?
  while true {
    let operator = current(parser).kind
    let precedence = binaryPrecedence(operator)
    if precedence < minimum || precedence == 0 {
      break
    }
    bump(parser)
    if operator == "pipe-gt" {
      lhs = parsePipeInfix(service, parser, lhs, precedence, field, index)?
    } else if operator == "gt-gt" {
      lhs = parseComposeInfix(service, parser, lhs, precedence, field, index)?
    } else if operator == "dot-dot" || operator == "dot-dot-lt" {
      lhs = parseRangeInfix(service, parser, lhs, precedence, field, index)?
    } else {
      lhs = parseBinaryInfix(service, parser, lhs, operator, precedence, field, index)?
    }
  }
  Ok(lhs)
}

export function parseExpression(
  service: ParserService,
  parser: Parser,
  field: string,
  index: int,
) -> Result<SyntaxNode, string> {
  parseExpressionBp(service, parser, 1, field, index)
}

function parseNestedExpression(
  service: ParserService,
  parser: Parser,
  field: string,
  index: int,
) -> Result<SyntaxNode, string> {
  let previousLambda = lambdaAllowed(parser)
  setLambdaAllowed(parser, true)
  let result = parseRecordNestedExpression(service, parser, field, index)
  setLambdaAllowed(parser, previousLambda)
  result
}

function parseRecordNestedExpression(
  service: ParserService,
  parser: Parser,
  field: string,
  index: int,
) -> Result<SyntaxNode, string> {
  let previous = recordUpdateAllowed(parser)
  setRecordUpdateAllowed(parser, true)
  let result = parseExpression(service, parser, field, index)
  setRecordUpdateAllowed(parser, previous)
  result
}

function parseExpressionWithoutNakedLambda(
  service: ParserService,
  parser: Parser,
  field: string,
  index: int,
) -> Result<SyntaxNode, string> {
  let previous = lambdaAllowed(parser)
  setLambdaAllowed(parser, false)
  let result = parseRecordNestedExpression(service, parser, field, index)
  setLambdaAllowed(parser, previous)
  result
}

export function parseExpressionBeforeBlock(
  service: ParserService,
  parser: Parser,
  field: string,
  index: int,
) -> Result<SyntaxNode, string> {
  let previous = recordUpdateAllowed(parser)
  setRecordUpdateAllowed(parser, false)
  let result = parseExpression(service, parser, field, index)
  setRecordUpdateAllowed(parser, previous)
  result
}

import literal { literalAttribute }
// Type-expression and binding-pattern grammar for the self-host parser.
// It shares cursor and node helpers with parser.core and returns syntax trees to
// declaration and expression leaves without owning parse-result flattening.

import types { PreviewToken, SyntaxNode }
import parser.core {
  Parser,
  ParserService,
  addDiagnostic,
  at,
  attach,
  boolAttribute,
  boxValue,
  bump,
  current,
  diagnostic,
  eat,
  expect,
  expectLeftBrace,
  expectRightBrace,
  fail,
  fieldName,
  identNode,
  identifier,
  invokeParseExpressionBp,
  matchingParenFollowedBy,
  node,
  parseString,
  validateNumericLiteral,
  rejectReservedBinding,
  setBox,
  stringAttribute,
  text,
  tokenAt,
}

export function bindingPattern(value: PreviewToken, field: string, index: int) -> SyntaxNode {
  node(
    "pattern/binding",
    value.lo,
    value.hi,
    field,
    index,
    [],
    [identNode(value, "name", 0)],
  )
}

export function namedType(value: PreviewToken, field: string, index: int) -> SyntaxNode {
  node(
    "type/named",
    value.lo,
    value.hi,
    field,
    index,
    [],
    [identNode(value, "name", 0)],
  )
}

export function expectCloseAngle(parser: Parser) -> Result<int, string> {
  if at(parser, "gt") {
    return Ok(bump(parser).hi)
  }
  if at(parser, "gt-gt") {
    let token = bump(parser)
    let mut pending = parser.pendingGt
    pending.push(token.hi)
    setBox(parser.lastHi, token.lo + 1)
    return Ok(token.lo + 1)
  }
  fail(parser, "expected `>`")?
  Err("expected `>`")
}

export function parseTypeArguments(
  service: ParserService,
  parser: Parser,
) -> Result<Array<SyntaxNode>, string> {
  expect(parser, "lt", "`<`")?
  let mut arguments: Array<SyntaxNode> = [
    parseType(service, parser, "arguments", 0)?,
  ]
  let mut index = 1
  while eat(parser, "comma") {
    arguments.push(parseType(
      service,

      parser,
      "arguments",
      index,
    )?)
    index += 1
  }
  expectCloseAngle(parser)?
  Ok(arguments)
}

function parseNamedType(
  service: ParserService,
  parser: Parser,
  field: string,
  index: int,
) -> Result<SyntaxNode, string> {
  let namespace = bump(parser)
  if eat(parser, "dot") {
    let name = identifier(parser, "an exported type name")?
    let mut children: Array<SyntaxNode> = [
      identNode(namespace, "namespace", 0),
      identNode(name, "name", 0),
    ]
    if at(parser, "lt") {
      for argument in parseTypeArguments(service, parser)? {
        children.push(argument)
      }
    }
    return Ok(node(
      "type/qualified",
      namespace.lo,
      boxValue(parser.lastHi),
      field,
      index,
      [],
      children,
    ))
  }
  let mut children: Array<SyntaxNode> = [identNode(namespace, "name", 0)]
  if at(parser, "lt") {
    for argument in parseTypeArguments(service, parser)? {
      children.push(argument)
    }
  }
  Ok(node(
    "type/named",
    namespace.lo,
    boxValue(parser.lastHi),
    field,
    index,
    [],
    children,
  ))
}

function parseRecordType(
  service: ParserService,
  parser: Parser,
  field: string,
  index: int,
) -> Result<SyntaxNode, string> {
  let open = bump(parser)
  let mut fields: Array<SyntaxNode> = []
  let mut fieldIndex = 0
  while !at(parser, "right-brace") && !at(parser, "eof") {
    let name = fieldName(parser, "a field name")?
    expect(parser, "colon", "`:`")?
    let typeNode = parseType(service, parser, "type", 0)?
    fields.push(node(
      "record-type-field",
      name.lo,
      typeNode.hi,
      "fields",
      fieldIndex,
      [],
      [identNode(name, "name", 0), typeNode],
    ))
    fieldIndex += 1
    if !eat(parser, "comma") {
      break
    }
  }
  let close = expectRightBrace(parser)?
  if fields.length == 0 {
    addDiagnostic(
      parser,
      "TPZ2001",
      "a record type requires at least one field",
      open.lo,
      close.hi,
    )
  }
  Ok(node("type/record", open.lo, close.hi, field, index, [], fields))
}

function parseFunctionType(
  service: ParserService,
  parser: Parser,
  open: PreviewToken,
  field: string,
  index: int,
) -> Result<SyntaxNode, string> {
  let mut parameters: Array<SyntaxNode> = []
  let mut parameterIndex = 0
  while !at(parser, "right-paren") && !at(parser, "eof") {
    let variadic = eat(parser, "ellipsis")
    let typeNode = parseType(service, parser, "type", 0)?
    parameters.push(node(
      "function-type-parameter",
      typeNode.lo,
      typeNode.hi,
      "parameters",
      parameterIndex,
      [boolAttribute("variadic", variadic)],
      [typeNode],
    ))
    parameterIndex += 1
    if !eat(parser, "comma") {
      break
    }
  }
  expect(parser, "right-paren", "`)`")?
  expect(parser, "thin-arrow", "`->`")?
  let returnType = parseType(service, parser, "returnType", 0)?
  let hi = returnType.hi
  parameters.push(returnType)
  Ok(node("type/function", open.lo, hi, field, index, [], parameters))
}

function parseParenthesizedType(
  service: ParserService,
  parser: Parser,
  field: string,
  index: int,
) -> Result<SyntaxNode, string> {
  let functionType = matchingParenFollowedBy(parser, "thin-arrow")
  let open = bump(parser)
  if functionType {
    return parseFunctionType(service, parser, open, field, index)
  }
  if eat(parser, "right-paren") {
    return Ok(node(
      "type/unit",
      open.lo,
      boxValue(parser.lastHi),
      field,
      index,
      [],
      [],
    ))
  }
  let inner = parseType(service, parser, field, index)?
  let close = expect(parser, "right-paren", "`)`")?
  Ok(node(
    inner.kind,
    open.lo,
    close.hi,
    field,
    index,
    inner.attributes,
    inner.children,
  ))
}

function parsePrimaryType(
  service: ParserService,
  parser: Parser,
  field: string,
  index: int,
) -> Result<SyntaxNode, string> {
  let start = current(parser)
  if start.kind == "identifier" {
    return parseNamedType(service, parser, field, index)
  }
  if start.kind == "left-brace" {
    return parseRecordType(service, parser, field, index)
  }
  if start.kind == "left-paren" {
    return parseParenthesizedType(service, parser, field, index)
  }
  if start.kind == "integer" || start.kind == "float" ||
    start.kind == "keyword/true" || start.kind == "keyword/false" ||
    start.kind == "keyword/null" {
    if start.kind == "integer" || start.kind == "float" { validateNumericLiteral(parser, start)? }
    bump(parser)
    let kind = if start.kind == "integer" || start.kind == "float" { start.kind } else if start.kind == "keyword/null" { "null" } else { "bool" }
    return Ok(node("type/literal", start.lo, start.hi, field, index, [stringAttribute("literalKind",kind),stringAttribute("literalSpelling",text(parser,start.lo,start.hi))], []))
  }
  if start.kind.startsWith("string-start/") {
    let literal = parseString(service, parser, field, index)?
    for part in literal.children {
      if part.kind == "string-part/interpolation" {
        addDiagnostic(
          parser,
          "TPZ2001",
          "a literal type cannot contain interpolation",
          literal.lo,
          literal.hi,
        )
        break
      }
    }
    let mut cooked = ""
    let mut maps: Array<string> = []
    for part in literal.children {
      if part.kind == "string-part/text" { cooked = cooked + literalAttribute(part, "cooked"); maps.push(literalAttribute(part, "sourceMap")) }
    }
    let attributes = if literal.kind == "expression/template" { [] }
      else { [stringAttribute("cooked", cooked), stringAttribute("sourceMap", maps.join(";"))] }
    return Ok(node("type/literal", literal.lo, literal.hi, field, index, attributes, []))
  }
  fail(parser, "expected a type")?
  Err("expected a type")
}

export function parseType(
  service: ParserService,
  parser: Parser,
  field: string,
  index: int,
) -> Result<SyntaxNode, string> {
  let first = parsePrimaryType(service, parser, field, index)?
  if !at(parser, "pipe") {
    return Ok(first)
  }
  let mut members: Array<SyntaxNode> = [attach(first, "members", 0)]
  let mut memberIndex = 1
  while eat(parser, "pipe") {
    members.push(parsePrimaryType(
      service,

      parser,
      "members",
      memberIndex,
    )?)
    memberIndex += 1
  }
  Ok(node("type/union", first.lo, boxValue(parser.lastHi), field, index, [], members))
}

function isLiteralExpressionKind(kind: string) -> bool {
  kind == "expression/integer" ||
    kind == "expression/float" ||
    kind == "expression/string" ||
    kind == "expression/boolean" ||
    kind == "expression/null" ||
    kind == "expression/unit"
}

function parseRecordPatternFields(
  service: ParserService,
  parser: Parser,
) -> Result<Array<SyntaxNode>, string> {
  let open = expectLeftBrace(parser)?
  let mut fields: Array<SyntaxNode> = []
  let mut fieldIndex = 0
  while !at(parser, "right-brace") && !at(parser, "eof") {
    let lo = current(parser).lo
    let name = if current(parser).kind.startsWith("keyword/") &&
      tokenAt(parser, 1).kind == "colon" {
      bump(parser)
    } else {
      identifier(parser, "a field name")?
    }
    let mut children: Array<SyntaxNode> = [identNode(name, "name", 0)]
    if eat(parser, "colon") {
      children.push(parsePattern(service, parser, "pattern", 0)?)
    } else {
      rejectReservedBinding(parser, name)
    }
    fields.push(node(
      "record-pattern-field",
      lo,
      boxValue(parser.lastHi),
      "fields",
      fieldIndex,
      [],
      children,
    ))
    fieldIndex += 1
    if !eat(parser, "comma") {
      break
    }
  }
  let close = expectRightBrace(parser)?
  if fields.length == 0 {
    let mut diagnostics = parser.diagnostics
    diagnostics.push(diagnostic(
      "TPZ2001",
      "a record pattern requires at least one field",
      open.lo,
      close.hi,
    ))
  }
  Ok(fields)
}

function parseListPattern(
  service: ParserService,
  parser: Parser,
  field: string,
  index: int,
) -> Result<SyntaxNode, string> {
  let open = bump(parser)
  let mut elements: Array<SyntaxNode> = []
  let mut elementIndex = 0
  while !at(parser, "right-bracket") && !at(parser, "eof") {
    if eat(parser, "dot-dot") {
      let markerLo = boxValue(parser.lastHi) - 2
      let mut children: Array<SyntaxNode> = []
      if !at(parser, "comma") && !at(parser, "right-bracket") {
        children.push(parsePattern(service, parser, "binding", 0)?)
      }
      let restLo = match children.get(0) {
        case Some(binding) => binding.lo
        case None => markerLo
      }
      let restHi = boxValue(parser.lastHi)
      elements.push(node(
        "list-pattern/rest",
        restLo,
        restHi,
        "elements",
        elementIndex,
        [],
        children,
      ))
    } else {
      elements.push(parsePattern(
        service,

        parser,
        "elements",
        elementIndex,
      )?)
    }
    elementIndex += 1
    if !eat(parser, "comma") {
      break
    }
  }
  let close = expect(parser, "right-bracket", "`]`")?
  let mut normalized: Array<SyntaxNode> = []
  for element in elements {
    if element.kind == "list-pattern/rest" && element.children.length == 0 {
      normalized.push(node(
        element.kind,
        open.lo,
        close.hi,
        element.field,
        element.index,
        element.attributes,
        element.children,
      ))
    } else {
      normalized.push(element)
    }
  }
  Ok(node("pattern/list", open.lo, close.hi, field, index, [], normalized))
}

function parseConstructorPattern(
  service: ParserService,
  parser: Parser,
  field: string,
  index: int,
) -> Result<SyntaxNode, string> {
  let name = bump(parser)
  bump(parser)
  let mut children: Array<SyntaxNode> = [identNode(name, "name", 0)]
  let mut argumentIndex = 0
  while !at(parser, "right-paren") && !at(parser, "eof") {
    children.push(parsePattern(
      service,

      parser,
      "arguments",
      argumentIndex,
    )?)
    argumentIndex += 1
    if !eat(parser, "comma") {
      break
    }
  }
  let close = expect(parser, "right-paren", "`)`")?
  Ok(node(
    "pattern/constructor",
    name.lo,
    close.hi,
    field,
    index,
    [],
    children,
  ))
}

function parseNominalRecordPattern(
  service: ParserService,
  parser: Parser,
  field: string,
  index: int,
) -> Result<SyntaxNode, string> {
  let name = bump(parser)
  let fields = parseRecordPatternFields(service, parser)?
  let mut children: Array<SyntaxNode> = [identNode(name, "name", 0)]
  for found in fields {
    children.push(found)
  }
  Ok(node(
    "pattern/nominal-record",
    name.lo,
    boxValue(parser.lastHi),
    field,
    index,
    [],
    children,
  ))
}

function parseTypedPattern(
  service: ParserService,
  parser: Parser,
  field: string,
  index: int,
) -> Result<SyntaxNode, string> {
  let name = bump(parser)
  rejectReservedBinding(parser, name)
  bump(parser)
  let typeNode = parseType(service, parser, "type", 0)?
  Ok(node(
    "pattern/typed",
    name.lo,
    typeNode.hi,
    field,
    index,
    [],
    [identNode(name, "name", 0), typeNode],
  ))
}

function identifierStartsBindingPattern(parser: Parser) -> bool {
  let next = tokenAt(parser, 1).kind
  next != "dot-dot" && next != "dot-dot-lt" && next != "plus" &&
    next != "minus" && next != "star" && next != "slash" &&
    next != "percent" && next != "star-star"
}

function parseIdentifierPattern(
  service: ParserService,
  parser: Parser,
  field: string,
  index: int,
) -> Result<Option<SyntaxNode>, string> {
  let next = tokenAt(parser, 1).kind
  if next == "left-paren" {
    return Ok(Some(parseConstructorPattern(
      service,

      parser,
      field,
      index,
    )?))
  }
  if next == "left-brace" {
    return Ok(Some(parseNominalRecordPattern(
      service,

      parser,
      field,
      index,
    )?))
  }
  if next == "colon" {
    return Ok(Some(parseTypedPattern(
      service,

      parser,
      field,
      index,
    )?))
  }
  if !identifierStartsBindingPattern(parser) {
    return Ok(None)
  }
  let name = bump(parser)
  if text(parser, name.lo, name.hi) == "None" {
    return Ok(Some(node(
      "pattern/constructor",
      name.lo,
      name.hi,
      field,
      index,
      [],
      [identNode(name, "name", 0)],
    )))
  }
  Ok(Some(bindingPattern(name, field, index)))
}

function parseExpressionPattern(
  service: ParserService,
  parser: Parser,
  field: string,
  index: int,
) -> Result<SyntaxNode, string> {
  let first = invokeParseExpressionBp(service, parser, 8, "value", 0)?
  if at(parser, "dot-dot") || at(parser, "dot-dot-lt") {
    let inclusive = at(parser, "dot-dot")
    bump(parser)
    let high = invokeParseExpressionBp(service, parser, 8, "high", 0)?
    return Ok(node(
      "pattern/range",
      first.lo,
      high.hi,
      field,
      index,
      [boolAttribute("inclusive", inclusive)],
      [attach(first, "low", 0), high],
    ))
  }
  if isLiteralExpressionKind(first.kind) {
    return Ok(node(
      "pattern/literal",
      first.lo,
      first.hi,
      field,
      index,
      [],
      [attach(first, "value", 0)],
    ))
  }
  fail(parser, "expected a pattern")?
  Err("expected a pattern")
}

function parsePrimaryPattern(
  service: ParserService,
  parser: Parser,
  field: string,
  index: int,
) -> Result<SyntaxNode, string> {
  let start = current(parser)
  if start.kind == "underscore" {
    let value = bump(parser)
    return Ok(node("pattern/wildcard", value.lo, value.hi, field, index, [], []))
  }
  if start.kind == "left-bracket" {
    return parseListPattern(service, parser, field, index)
  }
  if start.kind == "left-brace" {
    let fields = parseRecordPatternFields(service, parser)?
    return Ok(node(
      "pattern/record",
      start.lo,
      boxValue(parser.lastHi),
      field,
      index,
      [],
      fields,
    ))
  }
  if start.kind == "identifier" {
    match parseIdentifierPattern(service, parser, field, index)? {
      case Some(pattern) => return Ok(pattern)
      case None => ()
    }
  }
  parseExpressionPattern(service, parser, field, index)
}

export function parsePattern(
  service: ParserService,
  parser: Parser,
  field: string,
  index: int,
) -> Result<SyntaxNode, string> {
  let first = parsePrimaryPattern(service, parser, field, index)?
  if !at(parser, "pipe") {
    return Ok(first)
  }
  let mut alternatives: Array<SyntaxNode> = [attach(first, "alternatives", 0)]
  let mut alternativeIndex = 1
  while eat(parser, "pipe") {
    alternatives.push(parsePrimaryPattern(
      service,

      parser,
      "alternatives",
      alternativeIndex,
    )?)
    alternativeIndex += 1
  }
  Ok(node(
    "pattern/or",
    first.lo,
    boxValue(parser.lastHi),
    field,
    index,
    [],
    alternatives,
  ))
}

import types {
  PreviewAstNode,
  PreviewCheckDiagnostic,
  PreviewModuleResult,
  PreviewResolvedReference,
  PreviewToken,
  PreviewTypeAtom,
  PreviewTypedCall,
  PreviewTypedCapture,
  PreviewTypedNode,
}

record ProfileSpan {
  lo: int,
  hi: int,
}

record ProfileDenial {
  rule: string,
  message: string,
}

function moduleText(source: Bytes, lo: int, hi: int) -> string {
  match source.slice(lo, hi).decodeUtf8() {
    case Ok(value) => value
    case Err(_) => ""
  }
}

function sameFinding(
  left: PreviewCheckDiagnostic,
  right: PreviewCheckDiagnostic,
) -> bool {
  left.moduleIndex == right.moduleIndex &&
    left.lo == right.lo &&
    left.hi == right.hi &&
    left.code == right.code &&
    left.message == right.message &&
    left.profileRule == right.profileRule
}

function before(
  left: PreviewCheckDiagnostic,
  right: PreviewCheckDiagnostic,
) -> bool {
  left.moduleIndex < right.moduleIndex ||
    (left.moduleIndex == right.moduleIndex && left.lo < right.lo) ||
    (left.moduleIndex == right.moduleIndex && left.lo == right.lo &&
      left.hi < right.hi) ||
    (left.moduleIndex == right.moduleIndex && left.lo == right.lo &&
      left.hi == right.hi && left.profileRule < right.profileRule) ||
    (left.moduleIndex == right.moduleIndex && left.lo == right.lo &&
      left.hi == right.hi && left.profileRule == right.profileRule &&
      left.message < right.message)
}

function insertFinding(
  output: Array<PreviewCheckDiagnostic>,
  finding: PreviewCheckDiagnostic,
) -> () {
  let mut target = output
  let mut index = 0
  while index < target.length {
    let existing = target[index]
    if sameFinding(existing, finding) {
      return ()
    }
    if before(finding, existing) {
      target.insert(index, finding)
      return ()
    }
    index += 1
  }
  target.push(finding)
  ()
}

function insertTypedFinding(
  output: Array<PreviewCheckDiagnostic>,
  finding: PreviewCheckDiagnostic,
) -> () {
  let mut target = output
  let mut index = 0
  while index < target.length {
    let existing = target[index]
    if existing.moduleIndex == finding.moduleIndex &&
      existing.lo == finding.lo &&
      existing.hi == finding.hi {
      return ()
    }
    if before(finding, existing) {
      target.insert(index, finding)
      return ()
    }
    index += 1
  }
  target.push(finding)
  ()
}

function finding(
  moduleIndex: int,
  lo: int,
  hi: int,
  rule: string,
  message: string,
  primaryMessage: string,
  notes: Array<string>,
) -> PreviewCheckDiagnostic {
  PreviewCheckDiagnostic {
    moduleIndex: moduleIndex,
    code: "TPZ5801",
    message: message,
    primaryMessage: primaryMessage,
    lo: lo,
    hi: hi,
    secondary: [],
    notes: notes,
    profileRule: rule,
  }
}

function sourceFinding(
  moduleIndex: int,
  lo: int,
  hi: int,
  rule: string,
  message: string,
) -> PreviewCheckDiagnostic {
  finding(
    moduleIndex,
    lo,
    hi,
    rule,
    message,
    "not in the deterministic compiler-kernel inventory",
    [
      "profile rule: {rule}",
      "move this effect to the Rust host shell or use a deterministic admitted value/library leaf",
    ],
  )
}

function typedFinding(
  moduleIndex: int,
  lo: int,
  hi: int,
  rule: string,
  message: string,
) -> PreviewCheckDiagnostic {
  finding(
    moduleIndex,
    lo,
    hi,
    rule,
    message,
    "Bootstrap Profile package boundary",
    ["profile rule: {rule}"],
  )
}

record DirectChildIndexes {
  byParent: Map<int, Map<string, int>>,
}

record ProfileSpanIndexes {
  byModule: Map<int, Map<int, Map<int, int>>>,
}

function directChildIndexes(
  nodes: Array<PreviewAstNode>,
) -> DirectChildIndexes {
  let mut byParent: Map<int, Map<string, int>> = map {}
  let mut index = 0
  for node in nodes {
    match byParent.get(node.parent) {
      case Some(found) => {
        let mut byField = found
        match byField.get(node.field) {
          case Some(_) => ()
          case None => byField.insert(node.field, index)
        }
      }
      case None => {
        let mut byField: Map<string, int> = map {}
        byField.insert(node.field, index)
        byParent.insert(node.parent, byField)
      }
    }
    index += 1
  }
  DirectChildIndexes { byParent: byParent }
}

function directChildIndex(
  indexes: DirectChildIndexes,
  parent: int,
  field: string,
) -> Option<int> {
  match indexes.byParent.get(parent) {
    case Some(byField) => byField.get(field)
    case None => None
  }
}

function directChild(
  nodes: Array<PreviewAstNode>,
  indexes: DirectChildIndexes,
  parent: int,
  field: string,
) -> Option<PreviewAstNode> {
  match directChildIndex(indexes, parent, field) {
    case Some(index) => Some(nodes[index])
    case None => None
  }
}

function insertProfileSpanIndex(
  indexes: ProfileSpanIndexes,
  moduleIndex: int,
  lo: int,
  hi: int,
  index: int,
) -> () {
  let mut byModule = indexes.byModule
  let mut byLo = match byModule.get(moduleIndex) {
    case Some(found) => found
    case None => {
      let value: Map<int, Map<int, int>> = map {}
      byModule.insert(moduleIndex, value)
      value
    }
  }
  let mut byHi = match byLo.get(lo) {
    case Some(found) => found
    case None => {
      let value: Map<int, int> = map {}
      byLo.insert(lo, value)
      value
    }
  }
  match byHi.get(hi) {
    case Some(_) => ()
    case None => byHi.insert(hi, index)
  }
}

function profileSpanIndex(
  indexes: ProfileSpanIndexes,
  moduleIndex: int,
  lo: int,
  hi: int,
) -> Option<int> {
  match indexes.byModule.get(moduleIndex) {
    case Some(byLo) => match byLo.get(lo) {
      case Some(byHi) => byHi.get(hi)
      case None => None
    }
    case None => None
  }
}

function memberReference(
  catalog: ProfileReferenceCatalog,
  moduleIndex: int,
  lo: int,
  hi: int,
) -> Option<PreviewResolvedReference> {
  match profileSpanIndex(catalog.memberReferences, moduleIndex, lo, hi) {
    case Some(index) => Some(catalog.references[index])
    case None => None
  }
}

function memberIdentity(
  reference: Option<PreviewResolvedReference>,
  objectName: string,
  fieldName: string,
) -> string {
  match reference {
    case Some(found) => {
      let reference = found
      let targetName = if reference.targetName == "" {
        fieldName
      } else {
        reference.targetName
      }
      "{reference.targetModule}::{targetName}"
    }
    case None => "{objectName}::{fieldName}"
  }
}

function composeSpan(
  module: PreviewModuleResult,
  childIndexes: DirectChildIndexes,
  node: PreviewAstNode,
  ordinal: int,
) -> ProfileSpan {
  match [
    directChild(module.ast, childIndexes, ordinal, "left"),
    directChild(module.ast, childIndexes, ordinal, "right"),
  ] {
    case [Some(left), Some(right)] => for token in module.raw {
      if token.kind == "gt-gt" &&
        token.lo >= left.hi &&
        token.hi <= right.lo {
        return ProfileSpan { lo: token.lo, hi: token.hi }
      }
    }
    case _ => ()
  }
  ProfileSpan { lo: node.lo, hi: node.hi }
}

function identityHasHead(identity: string, head: string) -> bool {
  identity == head ||
    identity.startsWith("{head}.") ||
    identity.startsWith("{head}::")
}

function deniedModule(identity: string) -> bool {
  identityHasHead(identity, "std.fs") ||
    identityHasHead(identity, "std.io") ||
    identityHasHead(identity, "std.path") ||
    identityHasHead(identity, "std.cli") ||
    identityHasHead(identity, "std.test") ||
    identityHasHead(identity, "std.regex") ||
    identityHasHead(identity, "std.codec") ||
    identityHasHead(identity, "std.crypto") ||
    identityHasHead(identity, "std.time") ||
    identityHasHead(identity, "std.random") ||
    identityHasHead(identity, "std.process") ||
    identityHasHead(identity, "std.database")
}

function deniedLeaf(identity: string) -> bool {
  deniedModule(identity) ||
    identityHasHead(identity, "FS") ||
    identityHasHead(identity, "Cli") ||
    identityHasHead(identity, "Path") ||
    identityHasHead(identity, "HTTP") ||
    identityHasHead(identity, "DOM") ||
    identityHasHead(identity, "Test") ||
    identityHasHead(identity, "Regex") ||
    identityHasHead(identity, "Date") ||
    identityHasHead(identity, "Math") ||
    identityHasHead(identity, "HMAC") ||
    identityHasHead(identity, "Base64") ||
    identityHasHead(identity, "Deflate") ||
    identityHasHead(identity, "Zlib") ||
    identityHasHead(identity, "ReedSolomon")
}

function testFrameworkIdentity(identity: string) -> bool {
  identityHasHead(identity, "std.test") || identityHasHead(identity, "Test")
}

function testMember(name: string) -> bool {
  name == "assert" ||
    name == "assertEq" ||
    name == "assertNe" ||
    name == "assertContains" ||
    name == "assertOk" ||
    name == "assertErr" ||
    name == "assertSome" ||
    name == "assertNone" ||
    name == "assertGolden"
}

function typeDenial(atoms: Array<PreviewTypeAtom>) -> Option<ProfileDenial> {
  for atom in atoms {
    if (atom.kind == "primitive" || atom.kind == "literal") &&
      atom.name == "float" {
      return Some(ProfileDenial {
        rule: "bootstrap/no-float",
        message: "`float` is not available to the deterministic Bootstrap Profile",
      })
    }
    if atom.kind == "file" || atom.kind == "path" {
      return Some(ProfileDenial {
        rule: "bootstrap/no-resource",
        message: "host file and path values are not available to the Bootstrap Profile",
      })
    }
    if atom.kind == "regex" ||
      atom.kind == "match" ||
      atom.kind == "toml-value" ||
      atom.kind == "url" ||
      atom.kind == "date" ||
      atom.kind == "big-int" ||
      atom.kind == "decimal" ||
      atom.kind == "rounding-mode" {
      return Some(ProfileDenial {
        rule: "bootstrap/no-host-leaf",
        message: "this runtime value family is outside the Bootstrap Profile inventory",
      })
    }
  }
  None
}

function appendTypeFinding(
  output: Array<PreviewCheckDiagnostic>,
  moduleIndex: int,
  lo: int,
  hi: int,
  atoms: Array<PreviewTypeAtom>,
) -> () {
  match typeDenial(atoms) {
    case Some(value) => insertTypedFinding(
      output,
      typedFinding(moduleIndex, lo, hi, value.rule, value.message),
    )
    case None => ()
  }
}

function appendCallTypeFinding(
  output: Array<PreviewCheckDiagnostic>,
  call: PreviewTypedCall,
) -> () {
  match typeDenial(call.calleeType) {
    case Some(value) => insertTypedFinding(
      output,
      typedFinding(
        call.moduleIndex,
        call.lo,
        call.hi,
        value.rule,
        value.message,
      ),
    )
    case None => match typeDenial(call.resultType) {
      case Some(value) => insertTypedFinding(
        output,
        typedFinding(
          call.moduleIndex,
          call.lo,
          call.hi,
          value.rule,
          value.message,
        ),
      )
      case None => ()
    }
  }
}

function appendTestFramework(
  output: Array<PreviewCheckDiagnostic>,
  profile: string,
  moduleIndex: int,
  lo: int,
  hi: int,
  label: string,
) -> () {
  let rule = if profile == "agent-pack" {
    "agent-pack/no-test-framework"
  } else if profile == "test-profile" {
    "test-profile/no-test-framework"
  } else {
    "bootstrap/no-test-framework"
  }
  insertFinding(
    output,
    finding(
      moduleIndex,
      lo,
      hi,
      rule,
      "test-framework APIs are not allowed by profile `{profile}`",
      label,
      [
        "profile rule: {rule}",
        "the executable test-profile grants the canonical assert function (std.test.assert in language mode 5.21)",
      ],
    ),
  )
}

record ProfileReferenceCatalog {
  references: Array<PreviewResolvedReference>,
  resolvedTargets: ProfileSpanIndexes,
  memberReferences: ProfileSpanIndexes,
}

record ProfileModuleContext {
  profile: string,
  languageMode: string,
  moduleIndex: int,
  module: PreviewModuleResult,
  source: Bytes,
  referenceCatalog: ProfileReferenceCatalog,
  childIndexes: DirectChildIndexes,
}

function profileReferenceCatalog(
  references: Array<PreviewResolvedReference>,
) -> ProfileReferenceCatalog {
  let resolvedTargets = ProfileSpanIndexes { byModule: map {} }
  let memberReferences = ProfileSpanIndexes { byModule: map {} }
  let mut referenceIndex = 0
  for reference in references {
    if reference.targetModuleIndex >= 0 {
      insertProfileSpanIndex(
        resolvedTargets,
        reference.moduleIndex,
        reference.lo,
        reference.hi,
        referenceIndex,
      )
    }
    if reference.targetModule != "" {
      insertProfileSpanIndex(
        memberReferences,
        reference.moduleIndex,
        reference.lo,
        reference.hi,
        referenceIndex,
      )
    }
    referenceIndex += 1
  }
  ProfileReferenceCatalog {
    references: references,
    resolvedTargets: resolvedTargets,
    memberReferences: memberReferences,
  }
}

function appendCompositionFinding(
  output: Array<PreviewCheckDiagnostic>,
  context: ProfileModuleContext,
  node: PreviewAstNode,
  ordinal: int,
) -> () {
  if node.kind != "expression/compose" ||
    (context.profile != "agent-pack" && context.profile != "test-profile") {
    return ()
  }
  let span = composeSpan(context.module, context.childIndexes, node, ordinal)
  let rule = "{context.profile}/no-composition"
  insertFinding(
    output,
    finding(
      context.moduleIndex,
      span.lo,
      span.hi,
      rule,
      "function composition is not allowed by profile `{context.profile}`",
      "profile-disallowed `>>`",
      [
        "profile rule: {rule}",
        "use an explicit lambda, or a pipeline only when it preserves the intended semantics",
      ],
    ),
  )
}

function appendIdentifierFinding(
  output: Array<PreviewCheckDiagnostic>,
  context: ProfileModuleContext,
  node: PreviewAstNode,
) -> () {
  if node.kind != "expression/identifier" {
    return ()
  }
  if context.languageMode == "topaz-5.21" && context.profile == "test-profile" {
    match profileSpanIndex(context.referenceCatalog.resolvedTargets, context.moduleIndex, node.lo, node.hi) {
      case Some(index) => {
        let reference = context.referenceCatalog.references[index]
        if reference.targetModule == "std.test" && reference.targetName != "assert" {
          appendTestFramework(output, context.profile, context.moduleIndex, node.lo, node.hi, "test-only std.test function")
        }
      }
      case None => ()
    }
  }
  let name = moduleText(context.source, node.lo, node.hi)
  let unresolved = profileSpanIndex(
    context.referenceCatalog.resolvedTargets,
    context.moduleIndex,
    node.lo,
    node.hi,
  ) == None
  if context.profile == "bootstrap" && unresolved &&
    (name == "print" || name == "input" || name == "open" || name == "assert") {
    insertFinding(
      output,
      sourceFinding(
        context.moduleIndex,
        node.lo,
        node.hi,
        "bootstrap/no-host-leaf",
        "runtime leaf `{name}` is not available to the Bootstrap Profile",
      ),
    )
  } else if context.profile == "agent-pack" && unresolved && name == "assert" {
    insertFinding(
      output,
      finding(
        context.moduleIndex,
        node.lo,
        node.hi,
        "agent-pack/no-assert",
        "`assert` is not allowed by profile `agent-pack`",
        "test-only function reference",
        [
          "profile rule: agent-pack/no-assert",
          "use `--profile test-profile` only for test code, or express the failure with canonical Result/control flow",
        ],
      ),
    )
  }
}

function bootstrapSyntaxDenial(kind: string) -> Option<ProfileDenial> {
  if kind == "expression/float" {
    Some(ProfileDenial {
      rule: "bootstrap/no-float",
      message: "`float` is not available to the deterministic Bootstrap Profile",
    })
  } else if kind == "expression/duration" {
    Some(ProfileDenial {
      rule: "bootstrap/no-duration",
      message: "duration values are not available to the deterministic Bootstrap Profile",
    })
  } else if kind == "expression/concurrent" {
    Some(ProfileDenial {
      rule: "bootstrap/no-concurrency",
      message: "`concurrent` is not available to the deterministic Bootstrap Profile",
    })
  } else if kind == "statement/using" {
    Some(ProfileDenial {
      rule: "bootstrap/no-resource",
      message: "`using` and host resource values are not available to the Bootstrap Profile",
    })
  } else {
    None
  }
}

function appendBootstrapSyntaxFinding(
  output: Array<PreviewCheckDiagnostic>,
  context: ProfileModuleContext,
  node: PreviewAstNode,
) -> () {
  if context.profile != "bootstrap" {
    return ()
  }
  match bootstrapSyntaxDenial(node.kind) {
    case Some(denial) => insertFinding(
      output,
      sourceFinding(
        context.moduleIndex,
        node.lo,
        node.hi,
        denial.rule,
        denial.message,
      ),
    )
    case None => ()
  }
}

function appendImportFinding(
  output: Array<PreviewCheckDiagnostic>,
  context: ProfileModuleContext,
  node: PreviewAstNode,
  ordinal: int,
) -> () {
  if node.kind != "statement/import" {
    return ()
  }
  // The parser nests the module path under the statement's `import-item`.
  let item = match directChildIndex(context.childIndexes, ordinal, "import") {
    case Some(index) => index
    case None => return ()
  }
  let pathIndex = match directChildIndex(context.childIndexes, item, "path") {
    case Some(index) => index
    case None => return ()
  }
  let path = context.module.ast[pathIndex]
  let identity = modulePathIdentity(context, pathIndex)
  if context.profile == "bootstrap" && deniedModule(identity) {
    insertFinding(
      output,
      sourceFinding(
        context.moduleIndex,
        path.lo,
        path.hi,
        "bootstrap/no-host-module",
        "module `{identity}` is not available to the Bootstrap Profile",
      ),
    )
  }
  let mut canonicalAssertion = context.languageMode == "topaz-5.21" && context.profile == "test-profile"
  if canonicalAssertion {
    let mut specIndex = item + 1
    while specIndex < context.module.ast.length {
      let spec = context.module.ast[specIndex]
      if spec.parent == item && spec.kind == "import-spec" {
        match directChildIndex(context.childIndexes, specIndex, "name") {
          case Some(nameIndex) => {
            let name = context.module.ast[nameIndex]
            if moduleText(context.source, name.lo, name.hi) != "assert" { canonicalAssertion = false }
          }
          case None => { canonicalAssertion = false }
        }
      }
      specIndex += 1
    }
  }
  if identity == "std.test" && !canonicalAssertion {
    appendTestFramework(
      output,
      context.profile,
      context.moduleIndex,
      path.lo,
      path.hi,
      "test-only `std.test` import",
    )
  }
}

// Joins the path segments, which directly follow their module path in the
// flattened tree, so spacing or comments between segments keep one identity.
function modulePathIdentity(context: ProfileModuleContext, path: int) -> string {
  let mut segments: Array<string> = []
  let mut index = path + 1
  while index < context.module.ast.length {
    let segment = context.module.ast[index]
    if segment.parent != path {
      break
    }
    segments.push(moduleText(context.source, segment.lo, segment.hi))
    index += 1
  }
  segments.join(".")
}

function appendMemberFinding(
  output: Array<PreviewCheckDiagnostic>,
  context: ProfileModuleContext,
  node: PreviewAstNode,
  ordinal: int,
) -> () {
  if node.kind != "expression/member" && node.kind != "expression/optional-access" {
    return ()
  }
  match [
    directChild(context.module.ast, context.childIndexes, ordinal, "object"),
    directChild(context.module.ast, context.childIndexes, ordinal, "field"),
  ] {
    case [Some(object), Some(field)] => if object.kind == "expression/identifier" {
      let objectName = moduleText(context.source, object.lo, object.hi)
      let fieldName = moduleText(context.source, field.lo, field.hi)
      let objectResolved = profileSpanIndex(
        context.referenceCatalog.resolvedTargets,
        context.moduleIndex,
        object.lo,
        object.hi,
      ) != None
      let resolvedMember = memberReference(
        context.referenceCatalog,
        context.moduleIndex,
        field.lo,
        field.hi,
      )
      let memberResolved = match resolvedMember {
        case Some(_) => true
        case None => false
      }
      let identity = memberIdentity(
        resolvedMember,
        objectName,
        fieldName,
      )
      if context.profile == "bootstrap" &&
        (memberResolved || !objectResolved) && deniedLeaf(identity) {
        insertFinding(
          output,
          sourceFinding(
            context.moduleIndex,
            node.lo,
            node.hi,
            "bootstrap/no-host-leaf",
            "runtime leaf `{identity}` is not available to the Bootstrap Profile",
          ),
        )
      }
      let testNamespace = if memberResolved {
        testFrameworkIdentity(identity)
      } else {
        !objectResolved && objectName == "Test"
      }
      let canonicalStd = context.languageMode == "topaz-5.21" && identityHasHead(identity, "std.test")
      let canonicalAssert = canonicalStd && context.profile == "test-profile" && identity == "std.test::assert"
      if !canonicalAssert && (canonicalStd || (testNamespace && testMember(fieldName))) {
        appendTestFramework(
          output,
          context.profile,
          context.moduleIndex,
          node.lo,
          node.hi,
          "test-only `Test.*` namespace member",
        )
      }
    }
    case _ => ()
  }
}

function appendSourceNodeFindings(
  output: Array<PreviewCheckDiagnostic>,
  context: ProfileModuleContext,
  node: PreviewAstNode,
  ordinal: int,
) -> () {
  appendCompositionFinding(output, context, node, ordinal)
  appendIdentifierFinding(output, context, node)
  appendBootstrapSyntaxFinding(output, context, node)
  appendImportFinding(output, context, node, ordinal)
  appendMemberFinding(output, context, node, ordinal)
}

function appendSourceFindings(
  output: Array<PreviewCheckDiagnostic>,
  profile: string,
  languageMode: string,
  modules: Array<PreviewModuleResult>,
  referenceCatalog: ProfileReferenceCatalog,
) -> () {
  let mut moduleIndex = 0
  for module in modules {
    if module.identity != "std" && !module.identity.startsWith("std.") {
      let context = ProfileModuleContext {
        profile: profile,
        languageMode: languageMode,
        moduleIndex: moduleIndex,
        module: module,
        source: (module.source).encodeUtf8(),
        referenceCatalog: referenceCatalog,
        childIndexes: directChildIndexes(module.ast),
      }
      let mut ordinal = 0
      for node in module.ast {
        appendSourceNodeFindings(output, context, node, ordinal)
        ordinal += 1
      }
    }
    moduleIndex += 1
  }
  ()
}

function appendBootstrapTypedFindings(
  output: Array<PreviewCheckDiagnostic>,
  typedNodes: Array<PreviewTypedNode>,
  typedCalls: Array<PreviewTypedCall>,
  typedCaptures: Array<PreviewTypedCapture>,
) -> () {
  let mut typedOutput: Array<PreviewCheckDiagnostic> = []
  for node in typedNodes {
    if node.ambient {
      insertTypedFinding(
        typedOutput,
        typedFinding(
          node.moduleIndex,
          node.lo,
          node.hi,
          "bootstrap/no-ambient-type",
          "the compiler kernel may not retain an ambient or unexplained type",
        ),
      )
    }
  }
  for call in typedCalls {
    if call.ambient {
      insertTypedFinding(
        typedOutput,
        typedFinding(
          call.moduleIndex,
          call.lo,
          call.hi,
          "bootstrap/no-ambient-type",
          "the compiler kernel may not retain an unexplained callable or result type",
        ),
      )
    }
  }
  for node in typedNodes {
    appendTypeFinding(typedOutput, node.moduleIndex, node.lo, node.hi, node.typeValue)
  }
  for call in typedCalls {
    appendCallTypeFinding(typedOutput, call)
  }
  for capture in typedCaptures {
    appendTypeFinding(
      typedOutput,
      capture.moduleIndex,
      capture.referenceLo,
      capture.referenceHi,
      capture.typeValue,
    )
  }
  for found in typedOutput {
    insertFinding(output, found)
  }
  ()
}

export function checkProfile(
  profile: string,
  modules: Array<PreviewModuleResult>,
  references: Array<PreviewResolvedReference>,
  typedNodes: Array<PreviewTypedNode>,
  typedCalls: Array<PreviewTypedCall>,
  typedCaptures: Array<PreviewTypedCapture>,
  languageMode: string = "topaz-5.20",
) -> Result<Array<PreviewCheckDiagnostic>, string> {
  if profile == "" {
    return Ok([])
  }
  if profile != "agent-pack" &&
    profile != "test-profile" &&
    profile != "bootstrap" {
    return Err("unsupported compiler profile `{profile}`")
  }
  let mut output: Array<PreviewCheckDiagnostic> = []
  let referenceCatalog = profileReferenceCatalog(references)
  appendSourceFindings(output, profile, languageMode, modules, referenceCatalog)
  if profile == "bootstrap" {
    appendBootstrapTypedFindings(output, typedNodes, typedCalls, typedCaptures)
  }
  Ok(output)
}

import literal { stringLayout }
import length { unitName }
import types { PreviewDiagnostic, PreviewToken, RawResult }
import unicode {
  identifierContinueEnd,
  identifierEnd,
  identifierStartWidth,
  utf8Width,
}

function token(kind: string, lo: int, hi: int) -> PreviewToken {
  PreviewToken {
    kind: kind,
    lo: lo,
    hi: hi,
    stream: "raw",
    synthetic: false,
  }
}

function syntheticToken(kind: string, at: int) -> PreviewToken {
  PreviewToken {
    kind: kind,
    lo: at,
    hi: at,
    stream: "raw",
    synthetic: true,
  }
}

function diagnostic(code: string, message: string, lo: int, hi: int) -> PreviewDiagnostic {
  PreviewDiagnostic { code: code, message: message, lo: lo, hi: hi, notes: [] }
}

function byteAt(bytes: Bytes, index: int) -> int {
  match bytes.get(index) {
    case Some(value) => value
    case None => -1
  }
}

function isAsciiSpace(value: int) -> bool {
  value == 32 || value == 9
}

function lineCommentEnd(bytes: Bytes, start: int) -> int {
  let mut index = start + 2
  while index < bytes.length() && byteAt(bytes, index) != 10 {
    index += 1
  }
  index
}

function blockCommentEnd(bytes: Bytes, start: int) -> int {
  let mut index = start + 2
  while index < bytes.length() {
    if byteAt(bytes, index) == 42 && byteAt(bytes, index + 1) == 47 {
      return index + 2
    }
    index += 1
  }
  index
}

function isAsciiDigit(value: int) -> bool {
  value >= 48 && value <= 57
}

export function keywordKind(text: string) -> string {
  match text {
    case "let" => "keyword/let"
    case "mut" => "keyword/mut"
    case "const" => "keyword/const"
    case "type" => "keyword/type"
    case "function" => "keyword/function"
    case "return" => "keyword/return"
    case "if" => "keyword/if"
    case "else" => "keyword/else"
    case "match" => "keyword/match"
    case "case" => "keyword/case"
    case "for" => "keyword/for"
    case "in" => "keyword/in"
    case "by" => "keyword/by"
    case "while" => "keyword/while"
    case "break" => "keyword/break"
    case "continue" => "keyword/continue"
    case "defer" => "keyword/defer"
    case "concurrent" => "keyword/concurrent"
    case "true" => "keyword/true"
    case "false" => "keyword/false"
    case "null" => "keyword/null"
    case "_" => "underscore"
    case _ => "identifier"
  }
}

function decode(bytes: Bytes, lo: int, hi: int) -> string {
  match bytes.slice(lo, hi).decodeUtf8() {
    case Ok(value) => value
    case Err(_) => ""
  }
}

function identifierHeadKind(bytes: Bytes, start: int, end: int) -> string {
  let kind = keywordKind(decode(bytes, start, end))
  if kind == "identifier" && byteAt(bytes, end) == 34 {
    "tagged-string"
  } else {
    kind
  }
}

function punctuation(bytes: Bytes, index: int) -> Option<PreviewToken> {
  let a = byteAt(bytes, index)
  let b = byteAt(bytes, index + 1)
  let c = byteAt(bytes, index + 2)
  match [a, b, c] {
    case [46, 46, 46] => Some(token("ellipsis", index, index + 3))
    case [46, 46, 60] => Some(token("dot-dot-lt", index, index + 3))
    case [63, 63, 61] => Some(token("question-question-eq", index, index + 3))
    case [42, 42, _] => Some(token("star-star", index, index + 2))
    case [46, 46, _] => Some(token("dot-dot", index, index + 2))
    case [63, 46, _] => Some(token("question-dot", index, index + 2))
    case [63, 63, _] => Some(token("question-question", index, index + 2))
    case [60, 61, _] => Some(token("le", index, index + 2))
    case [62, 61, _] => Some(token("ge", index, index + 2))
    case [62, 62, _] => Some(token("gt-gt", index, index + 2))
    case [61, 61, _] => Some(token("eq-eq", index, index + 2))
    case [33, 61, _] => Some(token("not-eq", index, index + 2))
    case [43, 61, _] => Some(token("plus-eq", index, index + 2))
    case [45, 61, _] => Some(token("minus-eq", index, index + 2))
    case [42, 61, _] => Some(token("star-eq", index, index + 2))
    case [47, 61, _] => Some(token("slash-eq", index, index + 2))
    case [37, 61, _] => Some(token("percent-eq", index, index + 2))
    case [38, 38, _] => Some(token("and-and", index, index + 2))
    case [124, 124, _] => Some(token("or-or", index, index + 2))
    case [124, 62, _] => Some(token("pipe-gt", index, index + 2))
    case [61, 62, _] => Some(token("fat-arrow", index, index + 2))
    case [45, 62, _] => Some(token("thin-arrow", index, index + 2))
    case [40, _, _] => Some(token("left-paren", index, index + 1))
    case [41, _, _] => Some(token("right-paren", index, index + 1))
    case [91, _, _] => Some(token("left-bracket", index, index + 1))
    case [93, _, _] => Some(token("right-bracket", index, index + 1))
    case [123, _, _] => Some(token("left-brace", index, index + 1))
    case [125, _, _] => Some(token("right-brace", index, index + 1))
    case [43, _, _] => Some(token("plus", index, index + 1))
    case [45, _, _] => Some(token("minus", index, index + 1))
    case [42, _, _] => Some(token("star", index, index + 1))
    case [47, _, _] => Some(token("slash", index, index + 1))
    case [37, _, _] => Some(token("percent", index, index + 1))
    case [46, _, _] => Some(token("dot", index, index + 1))
    case [63, _, _] => Some(token("question", index, index + 1))
    case [60, _, _] => Some(token("lt", index, index + 1))
    case [62, _, _] => Some(token("gt", index, index + 1))
    case [61, _, _] => Some(token("eq", index, index + 1))
    case [33, _, _] => Some(token("bang", index, index + 1))
    case [126, _, _] => Some(token("tilde", index, index + 1))
    case [124, _, _] => Some(token("pipe", index, index + 1))
    case [44, _, _] => Some(token("comma", index, index + 1))
    case [58, _, _] => Some(token("colon", index, index + 1))
    case [59, _, _] => Some(token("semicolon", index, index + 1))
    case _ => None
  }
}

function isValidEscape(value: int) -> bool {
  value == 110 ||
    value == 116 ||
    value == 114 ||
    value == 92 ||
    value == 34 ||
    value == 123 ||
    value == 125
}

function startsTripleQuote(bytes: Bytes, index: int) -> bool {
  byteAt(bytes, index) == 34 &&
    byteAt(bytes, index + 1) == 34 &&
    byteAt(bytes, index + 2) == 34
}

function multilineIndentDiagnostics(
  bytes: Bytes,
  lineStarts: Array<int>,
  delimiter: int,
) -> Array<PreviewDiagnostic> {
  let mut diagnostics: Array<PreviewDiagnostic> = []
  for line in stringLayout(bytes, 0, delimiter, lineStarts).offending {
    diagnostics.push(diagnostic("TPZ0006", "line does not begin with the closing indent of its multiline string", line.lo, line.hi))
  }
  diagnostics
}

record LexemeScan {
  tokens: Array<PreviewToken>,
  diagnostics: Array<PreviewDiagnostic>,
  next: int,
  propagatedLineBreak: bool,
}

record StringInterpolationOutcome {
  next: int,
  lineBreak: bool,
}

record StringScanState {
  bytes: Bytes,
  tokens: Array<PreviewToken>,
  diagnostics: Array<PreviewDiagnostic>,
  lineStarts: Array<int>,
  quote: int,
  multiline: bool,
  lineBreakForbidden: bool,
}

function stringDelimiterEnd(start: int, multiline: bool) -> int {
  start + if multiline { 3 } else { 1 }
}

function appendStringText(state: StringScanState, start: int, end: int) -> () {
  if end > start {
    let mut tokens = state.tokens
    tokens.push(token("string-text", start, end))
  }
  ()
}

function finishString(state: StringScanState, textStart: int, delimiter: int) -> LexemeScan {
  appendStringText(state, textStart, delimiter)
  let end = stringDelimiterEnd(delimiter, state.multiline)
  let mut tokens = state.tokens
  tokens.push(token("string-end", delimiter, end))
  if state.multiline {
    let mut diagnostics = state.diagnostics
    for found in multilineIndentDiagnostics(state.bytes, state.lineStarts, delimiter) {
      diagnostics.push(found)
    }
  }
  LexemeScan {
    tokens: state.tokens,
    diagnostics: state.diagnostics,
    next: end,
    propagatedLineBreak: false,
  }
}

function scanStringEscape(state: StringScanState, start: int) -> int {
  let mut index = start + 1
  let escaped = byteAt(state.bytes, index)
  if isValidEscape(escaped) {
    return index + 1
  }
  let mut diagnostics = state.diagnostics
  if escaped == 10 || escaped == 13 || escaped == -1 {
    diagnostics.push(diagnostic(
      "TPZ0004",
      "invalid escape: `\\` before the end of the line",
      start,
      index,
    ))
    return index
  }
  let escapedWidth = utf8Width(escaped)
  let consumed = if escapedWidth > 0 { escapedWidth } else { 1 }
  let escapedText = decode(state.bytes, index, index + consumed)
  index += consumed
  diagnostics.push(diagnostic(
    "TPZ0004",
    "invalid escape `\\{escapedText}` in a string literal",
    start,
    index,
  ))
  index
}

function scanStringInterpolation(
  state: StringScanState,
  textStart: int,
  start: int,
) -> StringInterpolationOutcome {
  appendStringText(state, textStart, start)
  let mut tokens = state.tokens
  tokens.push(token("interpolation-start", start, start + 1))
  let interpolation = scanCode(
    state.bytes,
    start + 1,
    true,
    state.lineBreakForbidden || !state.multiline,
  )
  let mut diagnostics = state.diagnostics
  for found in interpolation.tokens {
    tokens.push(found)
  }
  for found in interpolation.diagnostics {
    diagnostics.push(found)
  }
  StringInterpolationOutcome {
    next: interpolation.next,
    lineBreak: interpolation.propagatedLineBreak,
  }
}

function interruptedString(
  state: StringScanState,
  textStart: int,
  end: int,
  message: string,
) -> LexemeScan {
  appendStringText(state, textStart, end)
  let mut diagnostics = state.diagnostics
  diagnostics.push(diagnostic(
    "TPZ0003",
    message,
    state.quote,
    stringDelimiterEnd(state.quote, state.multiline),
  ))
  let mut tokens = state.tokens
  tokens.push(syntheticToken("string-end", end))
  LexemeScan {
    tokens: state.tokens,
    diagnostics: state.diagnostics,
    next: end,
    propagatedLineBreak: false,
  }
}

function propagateStringLineBreak(
  state: StringScanState,
  textStart: int,
  end: int,
) -> LexemeScan {
  appendStringText(state, textStart, end)
  let mut tokens = state.tokens
  tokens.push(syntheticToken("string-end", end))
  LexemeScan {
    tokens: state.tokens,
    diagnostics: state.diagnostics,
    next: end,
    propagatedLineBreak: true,
  }
}

function scanString(
  bytes: Bytes,
  tokenStart: int,
  quote: int,
  tagged: bool,
  lineBreakForbidden: bool,
) -> LexemeScan {
  let multiline = startsTripleQuote(bytes, quote)
  let mut index = stringDelimiterEnd(quote, multiline)
  let mut textStart = index
  let state = StringScanState {
    bytes: bytes,
    tokens: [token(
      "string-start/tagged={tagged}/multiline={multiline}",
      tokenStart,
      index,
    )],
    diagnostics: [],
    lineStarts: [],
    quote: quote,
    multiline: multiline,
    lineBreakForbidden: lineBreakForbidden,
  }
  if multiline && index < bytes.length() && byteAt(bytes, index) != 10 &&
    !(byteAt(bytes, index) == 13 && byteAt(bytes, index + 1) == 10) {
    let mut lineStarts = state.lineStarts
    lineStarts.push(index)
  }
  while index < bytes.length() {
    if (multiline && startsTripleQuote(bytes, index)) ||
      (!multiline && byteAt(bytes, index) == 34) {
      return finishString(state, textStart, index)
    }
    let value = byteAt(bytes, index)
    if value == 92 {
      index = scanStringEscape(state, index)
      continue
    }
    if value == 123 {
      let interpolation = scanStringInterpolation(state, textStart, index)
      if interpolation.lineBreak {
        if state.multiline && state.lineBreakForbidden {
          return propagateStringLineBreak(state, interpolation.next, interpolation.next)
        }
        return interruptedString(
          state,
          interpolation.next,
          interpolation.next,
          "string interpolation in a single-line string cannot contain a line break",
        )
      }
      index = interpolation.next
      textStart = index
      continue
    }
    if multiline && state.lineBreakForbidden &&
      (value == 10 || (value == 13 && byteAt(bytes, index + 1) == 10)) {
      return propagateStringLineBreak(state, textStart, index)
    }
    if !multiline && (value == 10 ||
      (value == 13 && byteAt(bytes, index + 1) == 10)) {
      return interruptedString(
        state,
        textStart,
        index,
        "single-line string literal is not closed before the line break",
      )
    }
    if !multiline && value == 125 {
      let mut diagnostics = state.diagnostics
      diagnostics.push(diagnostic(
        "TPZ0005",
        "unescaped `\}` in a string literal; write `\\\}`",
        index,
        index + 1,
      ))
    }
    if multiline && value == 10 {
      let mut lineStarts = state.lineStarts
      lineStarts.push(index + 1)
    }
    index += 1
  }
  interruptedString(state, textStart, index, "unterminated string literal")
}

function appendScan(
  targetTokens: Array<PreviewToken>,
  targetDiagnostics: Array<PreviewDiagnostic>,
  foundTokens: Array<PreviewToken>,
  foundDiagnostics: Array<PreviewDiagnostic>,
) -> () {
  let mut tokens = targetTokens
  for found in foundTokens {
    tokens.push(found)
  }
  let mut diagnostics = targetDiagnostics
  for found in foundDiagnostics {
    diagnostics.push(found)
  }
  ()
}

function scanComment(bytes: Bytes, start: int) -> LexemeScan {
  let mut index = start + 2
  let mut diagnostics: Array<PreviewDiagnostic> = []
  if byteAt(bytes, start + 1) == 47 {
    index = lineCommentEnd(bytes, start)
  } else {
    index = blockCommentEnd(bytes, start)
    let closed = index >= start + 4 &&
      byteAt(bytes, index - 2) == 42 && byteAt(bytes, index - 1) == 47
    if !closed {
      diagnostics.push(diagnostic("TPZ0002", "unterminated block comment", start, index))
    }
  }
  LexemeScan {
    tokens: [],
    diagnostics: diagnostics,
    next: index,
    propagatedLineBreak: false,
  }
}

function scanNumber(bytes: Bytes, start: int) -> LexemeScan {
  let mut end = start
  while isAsciiDigit(byteAt(bytes,end)) || byteAt(bytes,end) == 95 { end += 1 }
  if byteAt(bytes,end) == 46 && (isAsciiDigit(byteAt(bytes,end+1)) || byteAt(bytes,end+1) == 95) {
    end += 1
    while isAsciiDigit(byteAt(bytes,end)) || byteAt(bytes,end) == 95 { end += 1 }
  }
  let unitEnd = identifierContinueEnd(bytes,end)
  let suffix = decode(bytes,end,unitEnd)
  if unitName(suffix) != "" {
    return LexemeScan { tokens:[token("length/{unitName(suffix)}",start,unitEnd)], diagnostics:[], next:unitEnd, propagatedLineBreak:false }
  }

  if suffix.startsWith("x") || suffix.startsWith("X") || suffix.startsWith("b") || suffix.startsWith("B") || suffix.startsWith("e") || suffix.startsWith("E") {
    let unsupportedExponent = suffix.startsWith("e") || suffix.startsWith("E")
    let mut invalidEnd=end
    while invalidEnd<bytes.length() {
      let b=byteAt(bytes,invalidEnd)
      if isAsciiDigit(b) || (b>=65 && b<=90) || (b>=97 && b<=122) || b==95 {invalidEnd+=1;continue}
      if b==46 && (isAsciiDigit(byteAt(bytes,invalidEnd+1)) || byteAt(bytes,invalidEnd+1)==95) {invalidEnd+=1;continue}
      if (b==43 || b==45) && (byteAt(bytes,invalidEnd-1)==101 || byteAt(bytes,invalidEnd-1)==69) {invalidEnd+=1;continue}
      break
    }
    let suffix=decode(bytes,invalidEnd-2,invalidEnd)
    if unitName(suffix)!="" {return LexemeScan {tokens:[token("length/{unitName(suffix)}",start,invalidEnd)],diagnostics:[],next:invalidEnd,propagatedLineBreak:false}}
    if unsupportedExponent {return LexemeScan {tokens:[token("float",start,invalidEnd)],diagnostics:[],next:invalidEnd,propagatedLineBreak:false}}
  }
  let radix = byteAt(bytes,start)==48 && (byteAt(bytes,start+1)==120 || byteAt(bytes,start+1)==88 || byteAt(bytes,start+1)==98 || byteAt(bytes,start+1)==66)
  let mut index = end
  let mut kind = if decode(bytes,start,end).contains(".") { "float" } else { "integer" }
  if radix {
    index = start + 2
    while isAsciiDigit(byteAt(bytes,index)) || (byteAt(bytes,index)>=65 && byteAt(bytes,index)<=90) || (byteAt(bytes,index)>=97 && byteAt(bytes,index)<=122) || byteAt(bytes,index)==95 { index += 1 }
    if byteAt(bytes,index)==46 && (isAsciiDigit(byteAt(bytes,index+1)) || byteAt(bytes,index+1)==95) {
      index += 1
      while isAsciiDigit(byteAt(bytes,index)) || (byteAt(bytes,index)>=65 && byteAt(bytes,index)<=90) || (byteAt(bytes,index)>=97 && byteAt(bytes,index)<=122) || byteAt(bytes,index)==95 { index += 1 }
    }
    kind = "integer"
  } else if kind == "integer" && (suffix == "ms" || suffix == "s" || suffix == "m") {
    kind = "duration/{suffix}"
    index = unitEnd
  }
  LexemeScan {
    tokens: [token(kind, start, index)],
    diagnostics: [],
    next: index,
    propagatedLineBreak: false,
  }
}

function scanLabel(bytes: Bytes, start: int) -> LexemeScan {
  let identifierStart = start + 1
  let index = identifierEnd(bytes, identifierStart)
  if index == identifierStart {
    return LexemeScan {
      tokens: [],
      diagnostics: [diagnostic(
        "TPZ0001",
        "a `'` begins a loop label `'name`; a bare `'` is not valid",
        start,
        identifierStart,
      )],
      next: identifierStart,
      propagatedLineBreak: false,
    }
  }
  LexemeScan {
    tokens: [token("label", start, index)],
    diagnostics: [],
    next: index,
    propagatedLineBreak: false,
  }
}

function scanIdentifier(bytes: Bytes, start: int, lineBreakForbidden: bool) -> LexemeScan {
  let index = identifierEnd(bytes, start)
  let kind = identifierHeadKind(bytes, start, index)
  if kind == "tagged-string" {
    return scanString(bytes, start, index, true, lineBreakForbidden)
  }
  LexemeScan {
    tokens: [token(kind, start, index)],
    diagnostics: [],
    next: index,
    propagatedLineBreak: false,
  }
}

function scanUnknown(bytes: Bytes, start: int) -> LexemeScan {
  let scalarWidth = utf8Width(byteAt(bytes, start))
  let consumed = if scalarWidth > 0 { scalarWidth } else { 1 }
  let found = decode(bytes, start, start + consumed)
  LexemeScan {
    tokens: [],
    diagnostics: [diagnostic(
      "TPZ0001",
      "unknown character `{found}`",
      start,
      start + consumed,
    )],
    next: start + consumed,
    propagatedLineBreak: false,
  }
}

function scanCode(
  bytes: Bytes,
  startIndex: int,
  interpolation: bool,
  lineBreakForbidden: bool,
) -> LexemeScan {
  let mut tokens: Array<PreviewToken> = []
  let mut diagnostics: Array<PreviewDiagnostic> = []
  let mut index = startIndex
  let mut braceDepth = 0

  while index < bytes.length() {
    let value = byteAt(bytes, index)
    if interpolation && value == 125 {
      if braceDepth == 0 {
        tokens.push(token("interpolation-end", index, index + 1))
        return LexemeScan {
          tokens: tokens,
          diagnostics: diagnostics,
          next: index + 1,
          propagatedLineBreak: false,
        }
      }
      tokens.push(token("right-brace", index, index + 1))
      braceDepth -= 1
      index += 1
      continue
    }
    if interpolation && lineBreakForbidden &&
      (value == 10 || (value == 13 && byteAt(bytes, index + 1) == 10)) {
      tokens.push(syntheticToken("interpolation-end", index))
      return LexemeScan {
        tokens: tokens,
        diagnostics: diagnostics,
        next: index,
        propagatedLineBreak: true,
      }
    }
    if isAsciiSpace(value) {
      index += 1
      continue
    }
    if value == 10 {
      let lo = if index > 0 && byteAt(bytes, index - 1) == 13 { index - 1 } else { index }
      tokens.push(token("newline", lo, index + 1))
      index += 1
      continue
    }
    if value == 13 && byteAt(bytes, index + 1) == 10 {
      tokens.push(token("newline", index, index + 2))
      index += 2
      continue
    }
    if value == 13 {
      index += 1
      continue
    }
    if value == 47 &&
      (byteAt(bytes, index + 1) == 47 || byteAt(bytes, index + 1) == 42) {
      let found = scanComment(bytes, index)
      appendScan(tokens, diagnostics, found.tokens, found.diagnostics)
      index = found.next
      continue
    }
    if value == 34 {
      let result = scanString(bytes, index, index, false, lineBreakForbidden)
      appendScan(tokens, diagnostics, result.tokens, result.diagnostics)
      index = result.next
      if result.propagatedLineBreak {
        tokens.push(syntheticToken("interpolation-end", index))
        return LexemeScan {
          tokens: tokens,
          diagnostics: diagnostics,
          next: index,
          propagatedLineBreak: true,
        }
      }
      continue
    }
    if isAsciiDigit(value) {
      let found = scanNumber(bytes, index)
      appendScan(tokens, diagnostics, found.tokens, found.diagnostics)
      index = found.next
      continue
    }
    if value == 39 {
      let found = scanLabel(bytes, index)
      appendScan(tokens, diagnostics, found.tokens, found.diagnostics)
      index = found.next
      continue
    }
    let startWidth = identifierStartWidth(bytes, index)
    if startWidth > 0 {
      let found = scanIdentifier(bytes, index, lineBreakForbidden)
      appendScan(tokens, diagnostics, found.tokens, found.diagnostics)
      index = found.next
      if found.propagatedLineBreak {
        tokens.push(syntheticToken("interpolation-end", index))
        return LexemeScan {
          tokens: tokens,
          diagnostics: diagnostics,
          next: index,
          propagatedLineBreak: true,
        }
      }
      continue
    }
    match punctuation(bytes, index) {
      case Some(found) => {
        tokens.push(found)
        if interpolation && found.kind == "left-brace" {
          braceDepth += 1
        }
        index = found.hi
      }
      case None => {
        let found = scanUnknown(bytes, index)
        appendScan(tokens, diagnostics, found.tokens, found.diagnostics)
        index = found.next
      }
    }
  }
  if interpolation {
    tokens.push(syntheticToken("interpolation-end", index))
  } else {
    tokens.push(token("eof", bytes.length(), bytes.length()))
  }
  LexemeScan {
    tokens: tokens,
    diagnostics: diagnostics,
    next: index,
    propagatedLineBreak: false,
  }
}

export function lex(source: string) -> RawResult {
  let bytes = (source).encodeUtf8()
  let result = scanCode(bytes, 0, false, false)
  RawResult { tokens: result.tokens, diagnostics: result.diagnostics }
}

// Resolution entry point for the embedded self compiler.
// Graph discovery and scope walking are delegated to resolver leaves; this file
// admits host facts and assembles the public resolved preview.

import types {
  PreviewGeneratedStdModule,
  PreviewHostFact,
  PreviewHostQuery,
  PreviewResolvedDiagnostic,
  ResolveResult,
}
import resolver.graph {
  dependencyOrder,
  diagnoseCycles,
  discoverModuleGraph,
  moduleDependencyCatalog,
  moduleIdentity,
  parseModule,
  pendingResult,
  readEntrySource,
  validateEntryPath,
  validateEntryPhysicalContainment,
}
import resolver.model_facts {
  ResolverInputs,
  ResolverHostFactCatalog,
  addQuery,
  resolverHostFacts,
}
import resolver.modules_tables { buildModuleTables }
import resolver.validation_init {
  rejectedResult,
  resolvedResult,
  validateImportSurfaces,
}

// Resolves an entry module from explicit host facts without performing I/O.
export function resolvePreview(
  entry: string,
  root: string,
  facts: Array<PreviewHostFact>,
  externModules: Array<string>,
  generatedStdModules: Array<PreviewGeneratedStdModule>,
  maxAstNodes: int,
  maxAstDepth: int,
  languageMode: string = "topaz-5.20",
) -> Result<ResolveResult, string> {
  resolveWithFacts(entry, root, resolverHostFacts(facts), externModules,
    generatedStdModules, maxAstNodes, maxAstDepth, languageMode)
}

// The catalog and its callback belong to this invocation. Graph discovery
// continues at each fact request without restarting parsing or resolution.
export function resolveWithFacts(
  entry: string,
  root: string,
  hostFacts: ResolverHostFactCatalog,
  externModules: Array<string>,
  generatedStdModules: Array<PreviewGeneratedStdModule>,
  maxAstNodes: int,
  maxAstDepth: int,
  languageMode: string = "topaz-5.20",
) -> Result<ResolveResult, string> {
  let mut diagnostics: Array<PreviewResolvedDiagnostic> = []
  if !validateEntryPath(entry, root, diagnostics) {
    return Ok(rejectedResult([], [], diagnostics))
  }
  let inputs = ResolverInputs {
    languageMode: languageMode,
    root: root,
    hostFacts: hostFacts,
    externModules: externModules,
    generatedStdModules: generatedStdModules,
    maxAstNodes: maxAstNodes,
    maxAstDepth: maxAstDepth,
  }
  let mut queries: Array<PreviewHostQuery> = []
  addQuery(queries, inputs.hostFacts, "physical-containment", entry)
  addQuery(queries, inputs.hostFacts, "read-source", entry)
  if hostFacts.errors.length > 0 { return Err(hostFacts.errors[0]) }
  if queries.length > 0 {
    return Ok(pendingResult(queries))
  }
  if !validateEntryPhysicalContainment(entry, inputs.hostFacts, diagnostics) {
    return Ok(rejectedResult([], [], diagnostics))
  }
  let entrySource = match readEntrySource(entry, inputs.hostFacts, diagnostics) {
    case Some(source) => source
    case None => return Ok(rejectedResult([], [], diagnostics))
  }

  let entryDraft = parseModule(
    0,
    moduleIdentity(entry, root),
    entry,
    entrySource,
    true,
    false,
    false,
    maxAstNodes,
    maxAstDepth,
    languageMode,
  )?
  let graph = discoverModuleGraph(entryDraft, inputs, queries, diagnostics)?
  if hostFacts.errors.length > 0 { return Err(hostFacts.errors[0]) }
  if queries.length > 0 {
    return Ok(pendingResult(queries))
  }

  let discovered = graph.modules
  let edges = graph.edges
  let dependencies = moduleDependencyCatalog(discovered, edges)
  diagnoseCycles(dependencies, edges, diagnostics)
  let ordered = if diagnostics.length == 0 {
    dependencyOrder(discovered, dependencies)
  } else {
    discovered
  }
  if diagnostics.length > 0 {
    return Ok(rejectedResult(ordered, dependencies.publicEdges, diagnostics))
  }
  let tables = buildModuleTables(ordered, diagnostics)
  validateImportSurfaces(ordered, tables, diagnostics)
  resolvedResult(ordered, dependencies.publicEdges, tables, diagnostics)
}

import common.standard_migration { removedModuleHint }
// Entry admission, module loading, dependency order, and cycle diagnosis.
// Host queries are derived from explicit facts; scope tables and initializer
// validation are left to sibling resolver leaves.

import layout { normalize }
import parser { parse }
import raw { lex }
import types {
  PreviewGeneratedStdModule,
  PreviewHostQuery,
  PreviewImportEdge,
  PreviewModuleResult,
  PreviewResolvedDiagnostic,
  ResolveResult,
}
import unicode { caseFold, nfd }
import resolver.model_facts {
  DiscoveredGraph,
  EdgeDraft,
  ImportDraft,
  ImportPathDisposition,
  ModuleDependencyCatalog,
  ModuleDraft,
  PreparedImport,
  ResolverHostFactCatalog,
  ResolverInputs,
  addQuery,
  appendModuleDiagnostics,
  contains,
  diagnostic,
  hasParentPathSegment,
  pathJoin,
  sortQueries,
  sourceFact,
  stringJoin,
}
import resolver.modules_tables { importDrafts }

function generatedStdModule(
  modules: Array<PreviewGeneratedStdModule>,
  identity: string,
) -> Option<PreviewGeneratedStdModule> {
  for module in modules {
    if module.identity == identity {
      return Some(module)
    }
  }
  None
}

function modulePath(root: string, segments: Array<string>) -> string {
  pathJoin(root, "{stringJoin(segments, "/")}.tpz")
}

export function moduleIdentity(entry: string, root: string) -> string {
  let mut relative = entry
  if root != "" && entry.startsWith("{root}/") {
    let bytes = (entry).encodeUtf8()
    match bytes.slice((root).encodeUtf8().length() + 1, bytes.length()).decodeUtf8() {
      case Ok(value) => {
        relative = value
      }
      case Err(_) => ()
    }
  }
  if relative.endsWith(".tpz") {
    let bytes = (relative).encodeUtf8()
    match bytes.slice(0, bytes.length() - 4).decodeUtf8() {
      case Ok(value) => {
        relative = value
      }
      case Err(_) => ()
    }
  }
  relative.replace("/", ".")
}

export function parseModule(
  sourceOrdinal: int,
  identity: string,
  path: string,
  source: string,
  entry: bool,
  externModule: bool,
  generatedStd: bool,
  maxAstNodes: int,
  maxAstDepth: int,
  languageMode: string = "topaz-5.20",
) -> Result<ModuleDraft, string> {
  let raw = lex(source)
  let layout = normalize(raw.tokens, source)
  let parsed = parse(layout.tokens, source, maxAstNodes, maxAstDepth, languageMode)?
  let mut diagnostics = raw.diagnostics
  for found in layout.diagnostics {
    diagnostics.push(found)
  }
  for found in parsed.diagnostics {
    diagnostics.push(found)
  }
  let sourceBytes = (source).encodeUtf8()
  Ok(ModuleDraft {
    result: PreviewModuleResult {
      sourceOrdinal: sourceOrdinal,
      identity: identity,
      path: path,
      source: source,
      entry: entry,
      extern: externModule,
      generatedStd: generatedStd,
      raw: raw.tokens,
      layout: layout.tokens,
      ast: parsed.nodes,
    },
    source: sourceBytes,
    root: parsed.root,
    imports: importDrafts(parsed.root, sourceBytes),
    diagnostics: diagnostics,
  })
}

function isExtern(externModules: Array<string>, identity: string) -> bool {
  contains(externModules, identity)
}

function isExternNamespace(externModules: Array<string>, identity: string) -> bool {
  let root = match identity.split(".").get(0) {
    case Some(value) => value
    case None => identity
  }
  for module in externModules {
    if module == root || module.startsWith("{root}.") {
      return true
    }
  }
  false
}

function validateSegment(
  facts: ResolverHostFactCatalog,
  dir: string,
  name: string,
  directory: bool,
) -> ImportPathDisposition {
  let fact = match sourceFact(facts, "list-directory", dir) {
    case Some(value) => value
    case None => return ImportPathDisposition { kind: "pending", collisionDetail: "" }
  }
  if fact.status == "unreadable" {
    return ImportPathDisposition {
      kind: "unreadable",
      collisionDetail: fact.reasonCode,
    }
  }
  if fact.status != "present" {
    return ImportPathDisposition { kind: "missing", collisionDetail: "" }
  }
  let mut exact = false
  let mut matches: Array<string> = []
  let normalized = nfd(name)
  let folded = caseFold(normalized)
  for entry in fact.entries {
    let sameKind = (directory && entry.kind == "directory") ||
      (!directory && entry.kind == "file")
    if sameKind {
      if entry.name == name {
        exact = true
      }
      let candidate = nfd(entry.name)
      if candidate == normalized || caseFold(candidate) == folded {
        matches.push(entry.name)
      }
    }
  }
  if matches.length > 1 {
    ImportPathDisposition {
      kind: "collision",
      collisionDetail: ": {stringJoin(matches, " / ")}",
    }
  } else if exact {
    ImportPathDisposition { kind: "ok", collisionDetail: "" }
  } else {
    ImportPathDisposition { kind: "missing", collisionDetail: "" }
  }
}

function prepareImport(
  inputs: ResolverInputs,
  import: ImportDraft,
  generated: Option<PreviewGeneratedStdModule>,
  queries: Array<PreviewHostQuery>,
) -> Result<PreparedImport, ImportPathDisposition> {
  if inputs.languageMode == "topaz-5.21" && import.target == "std.math" { return Err(ImportPathDisposition { kind: "missing", collisionDetail: "" }) }
  match generated {
    case Some(value) => return Ok(PreparedImport {
      path: value.path,
      source: value.source,
      physicalAlias: "",
      generatedStd: true,
    })
    case None => ()
  }
  let first = match import.segments.get(0) {
    case Some(value) => value
    case None => return Err(ImportPathDisposition {
      kind: "missing",
      collisionDetail: "",
    })
  }
  let path = modulePath(if first == "std" { "" } else { inputs.root }, import.segments)
  if first == "std" {
    addQuery(queries, inputs.hostFacts, "read-source", path)
    return match sourceFact(inputs.hostFacts, "read-source", path) {
      case Some(value) => if value.status == "present" {
        Ok(PreparedImport {
          path: path,
          source: value.source,
          physicalAlias: "",
          generatedStd: false,
        })
      } else if value.status == "unreadable" {
        Err(ImportPathDisposition {
          kind: "source-unreadable",
          collisionDetail: value.reasonCode,
        })
      } else if value.status == "invalid-utf8" {
        Err(ImportPathDisposition {
          kind: "source-invalid-utf8",
          collisionDetail: "",
        })
      } else {
        Err(ImportPathDisposition { kind: "missing", collisionDetail: "" })
      }
      case None => Err(ImportPathDisposition {
        kind: "pending",
        collisionDetail: "",
      })
    }
  }
  addQuery(queries, inputs.hostFacts, "physical-containment", path)
  let containment = match sourceFact(inputs.hostFacts, "physical-containment", path) {
    case Some(value) => if value.status == "outside" {
      return Err(ImportPathDisposition { kind: "outside", collisionDetail: "" })
    } else {
      value
    }
    case None => return Err(ImportPathDisposition {
      kind: "pending",
      collisionDetail: "",
    })
  }
  let mut dir = inputs.root
  let mut index = 0
  for segment in import.segments {
    addQuery(queries, inputs.hostFacts, "list-directory", dir)
    let name = if index + 1 == import.segments.length {
      "{segment}.tpz"
    } else {
      segment
    }
    let disposition = validateSegment(
      inputs.hostFacts,
      dir,
      name,
      index + 1 < import.segments.length,
    )
    if disposition.kind != "ok" {
      return Err(disposition)
    }
    if index + 1 < import.segments.length {
      dir = pathJoin(dir, segment)
    }
    index += 1
  }
  addQuery(queries, inputs.hostFacts, "read-source", path)
  match sourceFact(inputs.hostFacts, "read-source", path) {
    case Some(value) => if value.status == "present" {
      Ok(PreparedImport {
        path: path,
        source: value.source,
        physicalAlias: if containment.status == "inside" {
          containment.aliasClass
        } else {
          ""
        },
        generatedStd: false,
      })
    } else if value.status == "unreadable" {
      Err(ImportPathDisposition {
        kind: "source-unreadable",
        collisionDetail: value.reasonCode,
      })
    } else if value.status == "invalid-utf8" {
      Err(ImportPathDisposition {
        kind: "source-invalid-utf8",
        collisionDetail: "",
      })
    } else {
      Err(ImportPathDisposition { kind: "missing", collisionDetail: "" })
    }
    case None => Err(ImportPathDisposition {
      kind: "pending",
      collisionDetail: "",
    })
  }
}

export function dependencyOrder(
  modules: Array<ModuleDraft>,
  catalog: ModuleDependencyCatalog,
) -> Array<ModuleDraft> {
  let mut remaining: Set<string> = set {}
  for identity in catalog.identities {
    remaining.add(identity)
  }
  let mut done: Set<string> = set {}
  let mut output: Array<ModuleDraft> = []
  while output.length < modules.length {
    let mut ready: Option<int> = None
    for identity in catalog.identities {
      if !remaining.contains(identity) {
        continue
      }
      let mut blocked = false
      match catalog.dependencies.get(identity) {
        case Some(targets) => for target in targets {
          if !done.contains(target) {
            blocked = true
          }
        }
        case None => ()
      }
      if !blocked {
        ready = catalog.moduleIndexes.get(identity)
        break
      }
    }
    let selected = match ready {
      case Some(index) => modules[index]
      case None => return modules
    }
    remaining.remove(selected.result.identity)
    output.push(selected)
    done.add(selected.result.identity)
  }
  output
}

export function moduleDependencyCatalog(
  modules: Array<ModuleDraft>,
  edges: Array<EdgeDraft>,
) -> ModuleDependencyCatalog {
  let mut identities: Array<string> = []
  let mut moduleIndexes: Map<string, int> = map {}
  let mut dependencies: Map<string, Set<string>> = map {}
  let mut dependents: Map<string, Set<string>> = map {}
  let mut publicEdges: Array<PreviewImportEdge> = []
  let mut moduleIndexValue = 0
  for module in modules {
    identities.push(module.result.identity)
    moduleIndexes.insert(module.result.identity, moduleIndexValue)
    dependencies.insert(module.result.identity, set {})
    dependents.insert(module.result.identity, set {})
    moduleIndexValue += 1
  }
  identities.sort()
  for edge in edges {
    if moduleIndexes.containsKey(edge.from) && moduleIndexes.containsKey(edge.to) {
      publicEdges.push(PreviewImportEdge { from: edge.from, to: edge.to })
      match dependencies.get(edge.from) {
        case Some(found) => {
          let mut targets = found
          targets.add(edge.to)
        }
        case None => ()
      }
      match dependents.get(edge.to) {
        case Some(found) => {
          let mut sources = found
          sources.add(edge.from)
        }
        case None => ()
      }
    }
  }
  ModuleDependencyCatalog {
    identities: identities,
    moduleIndexes: moduleIndexes,
    dependencies: dependencies,
    dependents: dependents,
    publicEdges: publicEdges,
  }
}

function cycleFrom(
  start: string,
  current: string,
  catalog: ModuleDependencyCatalog,
  path: Array<string>,
  visited: Set<string>,
) -> Option<Array<string>> {
  let mut targets = match catalog.dependencies.get(current) {
    case Some(found) => found.toArray()
    case None => []
  }
  targets.sort()
  let mut activePath = path
  let mut activeVisited = visited
  for target in targets {
    if target == start {
      if path.length == 1 {
        continue
      }
      let mut result: Array<string> = []
      for item in path {
        result.push(item)
      }
      result.push(start)
      return Some(result)
    }
    if activeVisited.contains(target) {
      continue
    }
    activePath.push(target)
    activeVisited.add(target)
    let found = cycleFrom(start, target, catalog, activePath, activeVisited)
    activePath.pop()
    activeVisited.remove(target)
    match found {
      case Some(result) => return Some(result)
      case None => ()
    }
  }
  None
}

function collectReachable(
  current: string,
  graph: Map<string, Set<string>>,
  visited: Set<string>,
) -> () {
  let targets = match graph.get(current) {
    case Some(found) => found
    case None => return ()
  }
  let mut activeVisited = visited
  for next in targets {
    if !activeVisited.contains(next) {
      activeVisited.add(next)
      let _ = collectReachable(next, graph, activeVisited)
    }
  }
  ()
}

function reachableFrom(
  start: string,
  graph: Map<string, Set<string>>,
) -> Set<string> {
  let mut reachable: Set<string> = set {}
  reachable.add(start)
  collectReachable(start, graph, reachable)
  reachable
}

export function diagnoseCycles(
  catalog: ModuleDependencyCatalog,
  edges: Array<EdgeDraft>,
  diagnostics: Array<PreviewResolvedDiagnostic>,
) -> () {
  let mut covered: Set<string> = set {}
  for identity in catalog.identities {
    if covered.contains(identity) {
      continue
    }
    let mut pathVisited: Set<string> = set {}
    pathVisited.add(identity)
    match cycleFrom(identity, identity, catalog, [identity], pathVisited) {
      case Some(path) => {
        let next = path[1]
        let cycleText = stringJoin(path, " -> ")
        for edge in edges {
          if edge.from == identity && edge.to == next {
            diagnostic(
              diagnostics,
              edge.moduleIndex,
              "TPZ3006",
              "import cycle: {cycleText}",
              edge.lo,
              edge.hi,
            )
            break
          }
          ()
        }
        let forward = reachableFrom(identity, catalog.dependencies)
        let reverse = reachableFrom(identity, catalog.dependents)
        for candidate in catalog.identities {
          if forward.contains(candidate) && reverse.contains(candidate) {
            covered.add(candidate)
          }
        }
        ()
      }
      case None => {
        for edge in edges {
          if edge.from == identity && edge.to == identity {
            diagnostic(
              diagnostics,
              edge.moduleIndex,
              "TPZ3006",
              "module imports itself: `{identity}`",
              edge.lo,
              edge.hi,
            )
            covered.add(identity)
            break
          }
          ()
        }
        ()
      }
    }
    ()
  }
  ()
}

export function pendingResult(queries: Array<PreviewHostQuery>) -> ResolveResult {
  ResolveResult {
    queries: sortQueries(queries),
    modules: [],
    edges: [],
    scopes: [],
    declarations: [],
    references: [],
    exports: [],
    diagnostics: [],
  }
}

export function validateEntryPath(
  entry: string,
  root: string,
  diagnostics: Array<PreviewResolvedDiagnostic>,
) -> bool {
  let parentSegment = hasParentPathSegment(entry) || hasParentPathSegment(root)
  let rootIsEntry = root != "" && entry == root
  if parentSegment ||
    rootIsEntry ||
    (root != "" && !entry.startsWith("{root}/")) {
    diagnostic(
      diagnostics,
      0,
      "TPZ3002",
      if parentSegment {
        "entry and root paths must not contain parent (`..`) segments"
      } else if rootIsEntry {
        "the source root `{root}` must be a directory containing the entry, not the entry file itself"
      } else {
        "the root `{root}` does not contain the entry `{entry}`"
      },
      0,
      0,
    )
    return false
  }
  true
}

export function validateEntryPhysicalContainment(
  entry: string,
  facts: ResolverHostFactCatalog,
  diagnostics: Array<PreviewResolvedDiagnostic>,
) -> bool {
  match sourceFact(facts, "physical-containment", entry) {
    case Some(value) => if value.status == "outside" {
      diagnostic(
        diagnostics,
        0,
        "TPZ3005",
        "the entry `{entry}` resolves outside the root (symlink/alias containment)",
        0,
        0,
      )
      false
    } else {
      true
    }
    case None => true
  }
}

export function readEntrySource(
  entry: string,
  facts: ResolverHostFactCatalog,
  diagnostics: Array<PreviewResolvedDiagnostic>,
) -> Option<string> {
  match sourceFact(facts, "read-source", entry) {
    case Some(value) => if value.status == "present" {
      Some(value.source)
    } else if value.status == "unreadable" {
      diagnostic(
        diagnostics,
        0,
        "TPZ3003",
        "cannot load entry `{entry}`: {value.reasonCode}",
        0,
        0,
      )
      None
    } else if value.status == "invalid-utf8" {
      diagnostic(
        diagnostics,
        0,
        "TPZ3003",
        "cannot load entry `{entry}`: source is not valid UTF-8",
        0,
        0,
      )
      None
    } else {
      diagnostic(
        diagnostics,
        0,
        "TPZ3001",
        "entry file `{entry}` does not exist",
        0,
        0,
      )
      None
    }
    case None => {
      diagnostic(
        diagnostics,
        0,
        "TPZ3001",
        "entry file `{entry}` does not exist",
        0,
        0,
      )
      None
    }
  }
}

function validateImportedTopLevel(
  module: ModuleDraft,
  target: string,
  moduleIndexValue: int,
  diagnostics: Array<PreviewResolvedDiagnostic>,
) -> () {
  for statement in module.root.children {
    let allowed = statement.kind == "statement/import" ||
      statement.kind == "statement/export" ||
      statement.kind == "statement/function" ||
      statement.kind == "statement/impl" ||
      statement.kind == "statement/protocol" ||
      statement.kind == "statement/type-alias" ||
      statement.kind == "statement/enum" ||
      statement.kind == "statement/record" ||
      statement.kind == "statement/newtype" ||
      statement.kind == "statement/let" ||
      statement.kind == "statement/const"
    if !allowed {
      diagnostic(
        diagnostics,
        moduleIndexValue,
        "TPZ3007",
        "imported module `{target}` contains a top-level free statement; free statements are entry-only (the same file is valid as an entry)",
        statement.lo,
        statement.hi,
      )
    }
  }
  ()
}

function recordImportEdge(
  module: ModuleDraft,
  moduleIndexValue: int,
  import: ImportDraft,
  importedHere: Array<string>,
  edges: Array<EdgeDraft>,
  diagnostics: Array<PreviewResolvedDiagnostic>,
) -> bool {
  let firstSegment = match import.segments.get(0) {
    case Some(value) => value
    case None => ""
  }
  if firstSegment == "topaz" {
    diagnostic(
      diagnostics,
      moduleIndexValue,
      "TPZ3016",
      "the module path root `topaz` is reserved; user modules cannot live under it",
      import.pathLo,
      import.pathHi,
    )
    return false
  }
  let mut graphEdges = edges
  graphEdges.push(EdgeDraft {
    from: module.result.identity,
    to: import.target,
    moduleIndex: moduleIndexValue,
    lo: import.pathLo,
    hi: import.pathHi,
  })
  if contains(importedHere, import.target) {
    diagnostic(
      diagnostics,
      moduleIndexValue,
      "TPZ3017",
      "`{import.target}` is already imported by this module; a logical module may appear in at most one import item",
      import.pathLo,
      import.pathHi,
    )
    return false
  }
  let mut admitted = importedHere
  admitted.push(import.target)
  true
}

function reportImportDisposition(
  inputs: ResolverInputs,
  import: ImportDraft,
  disposition: ImportPathDisposition,
  moduleIndexValue: int,
  diagnostics: Array<PreviewResolvedDiagnostic>,
) -> () {
  if disposition.kind == "pending" {
    return ()
  }
  if disposition.kind == "outside" {
    diagnostic(
      diagnostics,
      moduleIndexValue,
      "TPZ3005",
      "`{import.target}` resolves outside the root (symlink/alias containment)",
      import.pathLo,
      import.pathHi,
    )
    return ()
  }
  if disposition.kind == "collision" {
    diagnostic(
      diagnostics,
      moduleIndexValue,
      "TPZ3004",
      "the path `{import.target}` collides with another candidate under the module name keys{disposition.collisionDetail}",
      import.pathLo,
      import.pathHi,
    )
    return ()
  }
  if disposition.kind == "unreadable" {
    diagnostic(
      diagnostics,
      moduleIndexValue,
      "TPZ3003",
      "cannot inspect module path for `{import.target}`: {disposition.collisionDetail}",
      import.pathLo,
      import.pathHi,
    )
    return ()
  }
  if disposition.kind == "source-unreadable" ||
    disposition.kind == "source-invalid-utf8" {
    diagnostic(
      diagnostics,
      moduleIndexValue,
      "TPZ3003",
      if disposition.kind == "source-invalid-utf8" {
        "cannot load module `{import.target}`: source is not valid UTF-8"
      } else {
        "cannot load module `{import.target}`: {disposition.collisionDetail}"
      },
      import.pathLo,
      import.pathHi,
    )
    return ()
  }
  if disposition.kind == "missing" {
    let standard = match import.segments.get(0) {
      case Some(value) => value == "std"
      case None => false
    }
    let externNamespace = !standard &&
      isExternNamespace(inputs.externModules, import.target)
    diagnostic(
      diagnostics,
      moduleIndexValue,
      if externNamespace { "TPZ5030" } else { "TPZ3001" },
      if externNamespace {
        "extern module `{import.target}` is not declared in topaz.toml"
      } else if standard {
        "no std module for `{import.target}` (expected virtual `{stringJoin(import.segments, "/")}.tpz`)" + if inputs.languageMode == "topaz-5.21" { removedModuleHint(import.target) } else { "" }
      } else {
        "no module file for `{import.target}` (expected `{modulePath(inputs.root, import.segments)}` by exact scalars)"
      },
      import.pathLo,
      import.pathHi,
    )
  }
  ()
}

function loadImportedModule(
  inputs: ResolverInputs,
  import: ImportDraft,
  prepared: PreparedImport,
  moduleIndexValue: int,
) -> Result<ModuleDraft, string> {
  parseModule(
    moduleIndexValue,
    import.target,
    prepared.path,
    prepared.source,
    false,
    isExtern(inputs.externModules, import.target),
    prepared.generatedStd,
    inputs.maxAstNodes,
    inputs.maxAstDepth,
    inputs.languageMode,
  )
}

export function discoverModuleGraph(
  entryDraft: ModuleDraft,
  inputs: ResolverInputs,
  queries: Array<PreviewHostQuery>,
  diagnostics: Array<PreviewResolvedDiagnostic>,
) -> Result<DiscoveredGraph, string> {
  let mut discovered: Array<ModuleDraft> = [entryDraft]
  let mut queued: Set<string> = set { entryDraft.result.identity }
  let mut physicalIdentities: Map<string, string> = map {}
  match sourceFact(inputs.hostFacts, "physical-containment", entryDraft.result.path) {
    case Some(fact) => if fact.status == "inside" && fact.aliasClass != "" {
      physicalIdentities.insert(fact.aliasClass, entryDraft.result.identity)
    }
    case None => ()
  }
  appendModuleDiagnostics(diagnostics, 0, entryDraft.diagnostics)
  let mut edges: Array<EdgeDraft> = []
  let mut next = 0
  while next < discovered.length {
    let module = discovered[next]
    let mut importedHere: Array<string> = []
    for import in module.imports {
      if !recordImportEdge(
        module,
        next,
        import,
        importedHere,
        edges,
        diagnostics,
      ) {
        continue
      }
      if queued.contains(import.target) {
        continue
      }
      queued.add(import.target)
      let generated = generatedStdModule(inputs.generatedStdModules, import.target)
      match prepareImport(inputs, import, generated, queries) {
        case Ok(prepared) => {
          if prepared.physicalAlias != "" {
            match physicalIdentities.get(prepared.physicalAlias) {
              case Some(existing) => {
                diagnostic(
                  diagnostics,
                  next,
                  "TPZ3004",
                  "the modules `{existing}` and `{import.target}` resolve to the same physical file; one physical file cannot have two module identities",
                  import.pathLo,
                  import.pathHi,
                )
                continue
              }
              case None => physicalIdentities.insert(prepared.physicalAlias, import.target)
            }
          }
          let imported = loadImportedModule(
            inputs,
            import,
            prepared,
            discovered.length,
          )?
          let importedIndex = discovered.length
          appendModuleDiagnostics(diagnostics, importedIndex, imported.diagnostics)
          validateImportedTopLevel(imported, import.target, importedIndex, diagnostics)
          discovered.push(imported)
        }
        case Err(disposition) => {
          reportImportDisposition(
            inputs,
            import,
            disposition,
            next,
            diagnostics,
          )
        }
      }
    }
    next += 1
  }
  Ok(DiscoveredGraph {
    modules: discovered,
    edges: edges,
  })
}

// Data contracts for resolver drafts, tables, host facts, and outputs.
// The records keep graph discovery and scope walking acyclic while the facade
// retains ownership of the public ResolveResult.

import types {
  PreviewDiagnostic,
  PreviewGeneratedStdModule,
  PreviewHostFact,
  PreviewHostQuery,
  PreviewImportEdge,
  PreviewModuleResult,
  PreviewResolvedDeclaration,
  PreviewResolvedDiagnostic,
  PreviewResolvedExport,
  PreviewResolvedReference,
  PreviewResolvedScope,
  SyntaxNode,
}

export record ImportDraft {
  target: string,
  segments: Array<string>,
  pathLo: int,
  pathHi: int,
  selectedNames: Array<string>,
  selectedLos: Array<int>,
  selectedHis: Array<int>,
}

export record EdgeDraft {
  from: string,
  to: string,
  moduleIndex: int,
  lo: int,
  hi: int,
}

export record ModuleDraft {
  result: PreviewModuleResult,
  source: Bytes,
  root: SyntaxNode,
  imports: Array<ImportDraft>,
  diagnostics: Array<PreviewDiagnostic>,
}

export record Binding {
  moduleIndex: int,
  scopeOrdinal: int,
