  scopes: Array<PreviewResolvedScope>,
  declarations: Array<PreviewResolvedDeclaration>,
  references: Array<PreviewResolvedReference>,
  exports: Array<PreviewResolvedExport>,
}

// SPEC v5.2 §17. This phase mirrors Stage 0 init_rule: it scans only
// each imported item's own immediately evaluated positions. Short-circuit RHS,
// optional-call arguments, and function, lambda, defer, branch, arm, and loop
// bodies stay delayed; top-level consts are ready before runtime initialization
// and the entry module has the separate §4 rule.
export record InitViolation {
  name: string,
  lo: int,
  hi: int,
}

export record ReferenceResolution {
  referenceNamespace: string,
  targetModuleIndex: int,
  targetLo: int,
  targetHi: int,
  targetNamespace: string,
  targetModule: string,
  targetName: string,
}

export record ImportPathDisposition {
  kind: string,
  collisionDetail: string,
}

export record PreparedImport {
  path: string,
  source: string,
  physicalAlias: string,
  generatedStd: bool,
}
export function text(source: Bytes, node: SyntaxNode) -> string {
  spanText(source, node.lo, node.hi)
}

export function child(value: SyntaxNode, field: string) -> Option<SyntaxNode> {
  for found in value.children {
    if found.field == field {
      return Some(found)
    }
  }
  None
}

export function children(value: SyntaxNode, field: string) -> Array<SyntaxNode> {
  let mut output: Array<SyntaxNode> = []
  for found in value.children {
    if found.field == field {
      output.push(found)
    }
  }
  output
}

export function attribute(value: SyntaxNode, name: string) -> string {
  for found in value.attributes {
    if found.name == name {
      return found.value
    }
  }
  ""
}

export function boolAttribute(value: SyntaxNode, name: string) -> bool {
  attribute(value, name) == "true"
}

export function contains(values: Array<string>, needle: string) -> bool {
  for value in values {
    if value == needle {
      return true
    }
  }
  false
}

export function hasParentPathSegment(path: string) -> bool {
  for segment in path.split("/") {
    if segment == ".." {
      return true
    }
  }
  false
}

export function isNone<T>(value: Option<T>) -> bool {
  match value {
    case Some(_) => false
    case None => true
  }
}

export function stringJoin(values: Array<string>, separator: string) -> string {
  let mut output = ""
  let mut index = 0
  for value in values {
    if index > 0 {
      output = "{output}{separator}"
    }
    output = "{output}{value}"
    index += 1
  }
  output
}

export function pathJoin(left: string, right: string) -> string {
  if left == "" {
    right
  } else {
    "{left}/{right}"
  }
}

export function resolverHostFacts(
  facts: Array<PreviewHostFact>,
) -> ResolverHostFactCatalog {
  let mut readSources: Map<string, int> = map {}
  let mut directoryListings: Map<string, int> = map {}
  let mut physicalContainments: Map<string, int> = map {}
  let mut index = 0
  for fact in facts {
    if fact.mountId == "root" {
      if fact.kind == "read-source" &&
        !readSources.containsKey(fact.logicalPath) {
        readSources.insert(fact.logicalPath, index)
      } else if fact.kind == "list-directory" &&
        !directoryListings.containsKey(fact.logicalPath) {
        directoryListings.insert(fact.logicalPath, index)
      } else if fact.kind == "physical-containment" &&
        !physicalContainments.containsKey(fact.logicalPath) {
        physicalContainments.insert(fact.logicalPath, index)
      }
    }
    index += 1
  }
  ResolverHostFactCatalog {
    values: facts,
    readSources: readSources,
    directoryListings: directoryListings,
    physicalContainments: physicalContainments,
    provider: None,
    errors: [],
  }
}

export function sourceFact(
  facts: ResolverHostFactCatalog,
  kind: string,
  path: string,
) -> Option<PreviewHostFact> {
  let index = if kind == "read-source" {
    facts.readSources.get(path)
  } else if kind == "list-directory" {
    facts.directoryListings.get(path)
  } else if kind == "physical-containment" {
    facts.physicalContainments.get(path)
  } else {
    None
  }
  match index {
    case Some(value) => Some(facts.values[value])
    case None => None
  }
}

export function addQuery(
  output: Array<PreviewHostQuery>,
  catalog: ResolverHostFactCatalog,
  kind: string,
  path: string,
) -> () {
  let mut facts = catalog
  let mut target = output
  match sourceFact(facts, kind, path) {
    case Some(_) => return ()
    case None => ()
  }
  for query in output {
    if query.kind == kind && query.mountId == "root" && query.logicalPath == path {
      return ()
    }
  }
  let query = PreviewHostQuery {
    kind: kind,
    mountId: "root",
    logicalPath: path,
  }
  match facts.provider {
    case Some(provide) => {
      if facts.errors.length > 0 { return () }
      match provide(query) {
        case Ok(fact) => {
          if fact.kind != query.kind || fact.mountId != query.mountId ||
            fact.logicalPath != query.logicalPath {
            facts.errors.push("host fact does not answer the requested query")
            return ()
          }
          let index = facts.values.length
          facts.values.push(fact)
          if kind == "read-source" {
            facts.readSources.insert(path, index)
          } else if kind == "list-directory" {
            facts.directoryListings.insert(path, index)
          } else {
            facts.physicalContainments.insert(path, index)
          }
        }
        case Err(error) => facts.errors.push(error)
      }
    }
    case None => target.push(query)
  }
}

function queryRank(kind: string) -> int {
  match kind {
    case "read-source" => 0
    case "list-directory" => 1
    case "physical-containment" => 2
    case _ => 3
  }
}

function queryBefore(left: PreviewHostQuery, right: PreviewHostQuery) -> bool {
  let leftRank = queryRank(left.kind)
  let rightRank = queryRank(right.kind)
  leftRank < rightRank ||
    (leftRank == rightRank && left.mountId < right.mountId) ||
    (leftRank == rightRank && left.mountId == right.mountId &&
      left.logicalPath < right.logicalPath)
}

export function sortQueries(values: Array<PreviewHostQuery>) -> Array<PreviewHostQuery> {
  let mut output: Array<PreviewHostQuery> = []
  for value in values {
    let mut inserted = false
    let mut index = 0
    while index < output.length {
      let existing = output[index]
      if queryBefore(value, existing) {
        output.insert(index, value)
        inserted = true
        break
      }
      index += 1
    }
    if !inserted {
      output.push(value)
    }
  }
  output
}

export function diagnostic(
  output: Array<PreviewResolvedDiagnostic>,
  moduleIndex: int,
  code: string,
  message: string,
  lo: int,
  hi: int,
) -> () {
  let mut target = output
  target.push(PreviewResolvedDiagnostic {
    moduleIndex: moduleIndex,
    code: code,
    message: message,
    lo: lo,
    hi: hi,
    notes: [],
  })
}

export function appendModuleDiagnostics(
  output: Array<PreviewResolvedDiagnostic>,
  moduleIndexValue: int,
  values: Array<PreviewDiagnostic>,
) -> () {
  for value in values {
    let mut target = output
    target.push(PreviewResolvedDiagnostic {
      moduleIndex: moduleIndexValue,
      code: value.code,
      message: value.message,
      lo: value.lo,
      hi: value.hi,
      notes: value.notes,
    })
  }
  ()
}

export function spanText(source: Bytes, lo: int, hi: int) -> string {
  match source.slice(lo, hi).decodeUtf8() {
    case Ok(found) => found
    case Err(_) => ""
  }
}

// Import drafts and module binding and export tables.
// Graph discovery provides parsed roots; scope walking consumes the canonical
// table catalog produced here.

import types {
  PreviewResolvedDiagnostic,
  PreviewResolvedExport,
  SyntaxNode,
}
import resolver.model_facts {
  Binding,
  ExportBinding,
  ImportDraft,
  ModuleDraft,
  ModuleTable,
  ModuleTableCatalog,
  boolAttribute,
  child,
  children,
  contains,
  diagnostic,
  isNone,
  stringJoin,
  text,
}

export function importDrafts(root: SyntaxNode, source: Bytes) -> Array<ImportDraft> {
  let mut output: Array<ImportDraft> = []
  for statement in root.children {
    if statement.kind != "statement/import" {
      continue
    }
    let itemOption = child(statement, "import")
    if isNone(itemOption) {
      continue
    }
    let item = match itemOption {
      case Some(value) => value
      case None => statement
    }
    let pathOption = child(item, "path")
    if isNone(pathOption) {
      continue
    }
    let path = match pathOption {
      case Some(value) => value
      case None => item
    }
    let mut segments: Array<string> = []
    for segment in children(path, "segments") {
      segments.push(text(source, segment))
    }
    let mut selectedNames: Array<string> = []
    let mut selectedLos: Array<int> = []
    let mut selectedHis: Array<int> = []
    for spec in children(item, "specs") {
      let nameNode = child(spec, "name")
      let name = match nameNode {
        case Some(value) => text(source, value)
        case None => ""
      }
      selectedNames.push(name)
      selectedLos.push(match nameNode {
        case Some(value) => value.lo
        case None => spec.lo
      })
      selectedHis.push(match nameNode {
        case Some(value) => value.hi
        case None => spec.hi
      })
    }
    output.push(ImportDraft {
      target: stringJoin(segments, "."),
      segments: segments,
      pathLo: path.lo,
      pathHi: path.hi,
      selectedNames: selectedNames,
      selectedLos: selectedLos,
      selectedHis: selectedHis,
    })
  }
  output
}

export function collectPatternBindings(
  pattern: SyntaxNode,
  source: Bytes,
  output: Array<SyntaxNode>,
) -> () {
  let mut target = output
  if pattern.kind == "pattern/binding" || pattern.kind == "pattern/typed" {
    match child(pattern, "name") {
      case Some(name) => target.push(name)
      case None => ()
    }
    return ()
  }
  if pattern.kind == "record-pattern-field" {
    match child(pattern, "pattern") {
      case Some(value) => collectPatternBindings(value, source, output)
      case None => match child(pattern, "name") {
        case Some(name) => target.push(name)
        case None => ()
      }
    }
    return ()
  }
  let mut alternatives: Array<string> = []
  for found in pattern.children {
    if pattern.kind == "pattern/or" && found.field == "alternatives" {
      let mut local: Array<SyntaxNode> = []
      collectPatternBindings(found, source, local)
      let mut seenHere: Array<string> = []
      for binding in local {
        let name = text(source, binding)
        let repeatedHere = contains(seenHere, name)
        let firstAlternative = !contains(alternatives, name)
        if repeatedHere || firstAlternative {
          target.push(binding)
        }
        if !repeatedHere {
          seenHere.push(name)
        }
        if firstAlternative {
          alternatives.push(name)
        }
      }
    } else if found.kind.startsWith("pattern/") ||
      found.kind == "record-pattern-field" ||
      found.kind == "list-pattern/rest" {
      collectPatternBindings(found, source, output)
    }
    ()
  }
  ()
}

export function unwrapExport(statement: SyntaxNode) -> SyntaxNode {
  if statement.kind == "statement/export" {
    return match child(statement, "item") {
      case Some(value) => value
      case None => statement
    }
  }
  statement
}

function importBindings(
  moduleIndexValue: int,
  item: SyntaxNode,
  source: Bytes,
) -> Array<Binding> {
  let mut output: Array<Binding> = []
  let importItem = match child(item, "import") {
    case Some(value) => value
    case None => return output
  }
  let path = match child(importItem, "path") {
    case Some(value) => value
    case None => return output
  }
  let mut segments: Array<string> = []
  for segment in children(path, "segments") {
    segments.push(text(source, segment))
  }
  let target = stringJoin(segments, ".")
  let specs = children(importItem, "specs")
  if specs.length == 0 {
    let nameNode = match child(importItem, "alias") {
      case Some(value) => value
      case None => match path.children.get(path.children.length - 1) {
        case Some(value) => value
        case None => return output
      }
    }
    output.push(Binding {
      moduleIndex: moduleIndexValue,
      scopeOrdinal: 0,
      name: text(source, nameNode),
      namespace: "module",
      declarationKind: "namespace-import",
      lo: nameNode.lo,
      hi: nameNode.hi,
      exported: false,
      targetModule: target,
      targetName: "",
      mutable: false,
    })
    return output
  }
  for spec in specs {
    let sourceName = match child(spec, "name") {
      case Some(value) => text(source, value)
      case None => ""
    }
    let bound = match child(spec, "alias") {
      case Some(value) => Some(value)
      case None => child(spec, "name")
    }
    match bound {
      case Some(name) => output.push(Binding {
        moduleIndex: moduleIndexValue,
        scopeOrdinal: 0,
        name: text(source, name),
        namespace: "value",
        declarationKind: "selected-import",
        lo: name.lo,
        hi: name.hi,
        exported: false,
        targetModule: target,
        targetName: sourceName,
        mutable: false,
      })
      case None => ()
    }
  }
  output
}

function namedStatementBinding(
  moduleIndexValue: int,
  item: SyntaxNode,
  source: Bytes,
  exported: bool,
) -> Option<Binding> {
  let kind = match item.kind {
    case "statement/function" => "function"
    case "statement/type-alias" => "type-alias"
    case "statement/enum" | "statement/record" | "statement/newtype" =>
      "nominal-type"
    case "statement/const" => "const"
    case _ => return None
  }
  let holder = if item.kind == "statement/function" {
    match child(item, "declaration") {
      case Some(value) => value
      case None => item
    }
  } else {
    item
  }
  match child(holder, "name") {
    case Some(name) => Some(Binding {
      moduleIndex: moduleIndexValue,
      scopeOrdinal: 0,
      name: text(source, name),
      namespace: if kind == "type-alias" || kind == "nominal-type" {
        "type"
      } else {
        "value"
      },
      declarationKind: kind,
      lo: name.lo,
      hi: name.hi,
      exported: exported,
      targetModule: "",
      targetName: "",
      mutable: false,
    })
    case None => None
  }
}

function letBindings(
  moduleIndexValue: int,
  item: SyntaxNode,
  source: Bytes,
  exported: bool,
) -> Array<Binding> {
  let mut output: Array<Binding> = []
  let pattern = match child(item, "pattern") {
    case Some(value) => value
    case None => return output
  }
  let mut names: Array<SyntaxNode> = []
  collectPatternBindings(pattern, source, names)
  let mutable = boolAttribute(item, "mutable")
  for name in names {
    output.push(Binding {
      moduleIndex: moduleIndexValue,
      scopeOrdinal: 0,
      name: text(source, name),
      namespace: "value",
      declarationKind: "let",
      lo: name.lo,
      hi: name.hi,
      exported: exported && !mutable,
      targetModule: "",
      targetName: "",
      mutable: mutable,
    })
  }
  output
}

export function bindingForStatement(
  moduleIndexValue: int,
  statement: SyntaxNode,
  source: Bytes,
  exported: bool,
) -> Array<Binding> {
  let item = unwrapExport(statement)
  if item.kind == "statement/import" {
    return importBindings(moduleIndexValue, item, source)
  }
  match namedStatementBinding(moduleIndexValue, item, source, exported) {
    case Some(binding) => return [binding]
    case None => ()
  }
  if item.kind == "statement/let" {
    return letBindings(moduleIndexValue, item, source, exported)
  }
  []
}

function buildTable(
  moduleIndexValue: int,
  module: ModuleDraft,
  diagnostics: Array<PreviewResolvedDiagnostic>,
) -> ModuleTable {
  let source = module.source
  let mut bindings: Array<Binding> = []
  let mut bindingIndexes: Map<string, int> = map {}
  let mut exportedBindings: Map<string, ExportBinding> = map {}
  for statement in module.root.children {
    let exported = statement.kind == "statement/export"
    for binding in bindingForStatement(moduleIndexValue, statement, source, exported) {
      let existingIndex = bindingIndexes.get(binding.name)
      if exported && binding.declarationKind == "let" && binding.mutable {
        diagnostic(
          diagnostics,
          moduleIndexValue,
          "TPZ3011",
          "`export let mut` is a static error: exported bindings are immutable views",
          binding.lo,
          binding.hi,
        )
      }
      if binding.exported {
        let exportIndex = match existingIndex {
          case Some(index) => index
          case None => bindings.length
        }
        exportedBindings.insert(binding.name, ExportBinding {
          bindingIndex: exportIndex,
          namespace: binding.namespace,
        })
      }
      match existingIndex {
        case Some(index) => {
          let firstLo = bindings[index].lo
          diagnostic(
            diagnostics,
            moduleIndexValue,
            "TPZ3008",
            "`{binding.name}` is already bound at this module's top level (first binding at byte {firstLo})",
            binding.lo,
            binding.hi,
          )
        }
        case None => {
          let bindingIndexValue = bindings.length
          bindingIndexes.insert(binding.name, bindingIndexValue)
          bindings.push(binding)
        }
      }
    }
  }
  let mut exportedNames: Array<string> = []
  for binding in bindings {
    if !isNone(exportedBindings.get(binding.name)) {
      exportedNames.push(binding.name)
    }
  }
  exportedNames.sort()
  ModuleTable {
    moduleIndex: moduleIndexValue,
    identity: module.result.identity,
    bindings: bindings,
    bindingIndexes: bindingIndexes,
    exportedBindings: exportedBindings,
    exportedNames: exportedNames,
  }
}

export function catalogTable(
  catalog: ModuleTableCatalog,
  identity: string,
) -> Option<ModuleTable> {
  match catalog.indexes.get(identity) {
    case Some(index) => Some(catalog.tables[index])
    case None => None
  }
}

export function tableBinding(table: ModuleTable, name: string) -> Option<Binding> {
  match table.bindingIndexes.get(name) {
    case Some(index) => Some(table.bindings[index])
    case None => None
  }
}

export function exportedBinding(table: ModuleTable, name: string) -> Option<ExportBinding> {
  table.exportedBindings.get(name)
}

export function exportedNames(
  table: ModuleTable,
  namespace: string,
) -> Array<string> {
  if namespace == "" {
    return table.exportedNames
  }
  let mut candidates: Array<string> = []
  for name in table.exportedNames {
    let namespaceValue = match exportedBinding(table, name) {
      case Some(binding) => binding.namespace
      case None => ""
    }
    if (namespace == "type" && namespaceValue == "type") ||
      (namespace == "value" && namespaceValue != "type") {
      candidates.push(name)
    }
  }
  candidates
}

export function effectiveNamespace(binding: Binding, tables: ModuleTableCatalog) -> string {
  if binding.declarationKind != "selected-import" {
    return binding.namespace
  }
  let targetTable = match catalogTable(tables, binding.targetModule) {
    case Some(found) => found
    case None => return binding.namespace
  }
  match exportedBinding(targetTable, binding.targetName) {
    case Some(found) => found.namespace
    case None => binding.namespace
  }
}

export function buildModuleTables(
  modules: Array<ModuleDraft>,
  diagnostics: Array<PreviewResolvedDiagnostic>,
) -> ModuleTableCatalog {
  let mut tables: Array<ModuleTable> = []
  let mut indexes: Map<string, int> = map {}
  let mut index = 0
  for module in modules {
    indexes.insert(module.result.identity, index)
    tables.push(buildTable(index, module, diagnostics))
    index += 1
  }
  ModuleTableCatalog { tables: tables, indexes: indexes }
}

// Lexical scope construction and resolved-reference traversal.
// Module tables define cross-file bindings, while this leaf owns local scopes,
// declarations, captures, and reference observations.

import raw { keywordKind }
import types {
  PreviewResolvedDeclaration,
  PreviewResolvedExport,
  PreviewResolvedReference,
  PreviewResolvedScope,
  SyntaxNode,
}
import unicode { didYouMean }
import resolver.model_facts {
  Binding,
  LocalScope,
  ModuleTable,
  ReferenceResolution,
  ResolverWalkContext,
  boolAttribute,
  child,
  children,
  diagnostic,
  isNone,
  text,
}
import resolver.modules_tables {
  bindingForStatement,
  catalogTable,
  collectPatternBindings,
  effectiveNamespace,
  exportedBinding,
  exportedNames,
  tableBinding,
}

function localBinding(scopes: Array<LocalScope>, name: string, namespace: string) -> Option<Binding> {
  let mut index = scopes.length
  while index > 0 {
    index -= 1
    let scope = scopes[index]
    let bindings = if namespace == "type" { scope.types } else { scope.values }
    match bindings.get(name) {
      case Some(binding) => return Some(binding)
      case None => ()
    }
  }
  None
}

function currentScope(scopes: Array<LocalScope>) -> int {
  if scopes.length == 0 {
    return 0
  }
  scopes[scopes.length - 1].ordinal
}

export function addDeclaration(
  output: Array<PreviewResolvedDeclaration>,
  binding: Binding,
  namespace: string,
  exported: bool,
) -> () {
  let mut target = output
  target.push(PreviewResolvedDeclaration {
    moduleIndex: binding.moduleIndex,
    scopeOrdinal: binding.scopeOrdinal,
    name: binding.name,
    namespace: namespace,
    declarationKind: binding.declarationKind,
    lo: binding.lo,
    hi: binding.hi,
    exported: exported,
    targetModule: binding.targetModule,
    targetName: binding.targetName,
  })
}

function addLocalBinding(
  scopes: Array<LocalScope>,
  declarations: Array<PreviewResolvedDeclaration>,
  binding: Binding,
) -> () {
  let mut activeScopes = scopes
  let scope = activeScopes[activeScopes.length - 1]
  if binding.namespace == "type" {
    let mut types = scope.types
    types.insert(binding.name, binding)
  } else {
    let mut values = scope.values
    values.insert(binding.name, binding)
  }
  addDeclaration(
    declarations,
    binding,
    binding.namespace,
    binding.exported,
  )
}

export function appendModuleExports(
  output: Array<PreviewResolvedExport>,
  moduleIndexValue: int,
  table: ModuleTable,
) -> () {
  let mut target = output
  for name in exportedNames(table, "") {
    match exportedBinding(table, name) {
      case Some(exported) => {
        let binding = table.bindings[exported.bindingIndex]
        target.push(PreviewResolvedExport {
          moduleIndex: moduleIndexValue,
          name: name,
          namespace: exported.namespace,
          declarationLo: binding.lo,
          declarationHi: binding.hi,
        })
      }
      case None => ()
    }
  }
  ()
}

function unresolvedReference(namespace: string) -> ReferenceResolution {
  ReferenceResolution {
    referenceNamespace: namespace,
    targetModuleIndex: -1,
    targetLo: 0,
    targetHi: 0,
    targetNamespace: "",
    targetModule: "",
    targetName: "",
  }
}

function appendReference(
  context: ResolverWalkContext,
  scopes: Array<LocalScope>,
  name: string,
  role: string,
  lo: int,
  hi: int,
  resolved: ReferenceResolution,
) -> () {
  let mut output = context.referenceOutput
  output.push(PreviewResolvedReference {
    moduleIndex: context.moduleIndex,
    scopeOrdinal: currentScope(scopes),
    name: name,
    namespace: resolved.referenceNamespace,
    role: role,
    lo: lo,
    hi: hi,
    targetModuleIndex: resolved.targetModuleIndex,
    targetLo: resolved.targetLo,
    targetHi: resolved.targetHi,
    targetNamespace: resolved.targetNamespace,
    targetModule: resolved.targetModule,
    targetName: resolved.targetName,
  })
}

function localReferenceResolution(
  context: ResolverWalkContext,
  scopes: Array<LocalScope>,
  name: string,
  namespace: string,
) -> Option<ReferenceResolution> {
  match localBinding(scopes, name, namespace) {
    case Some(target) => Some(ReferenceResolution {
      referenceNamespace: namespace,
      targetModuleIndex: context.moduleIndex,
      targetLo: target.lo,
      targetHi: target.hi,
      targetNamespace: target.namespace,
      targetModule: context.table.identity,
      targetName: name,
    })
    case None => None
  }
}

function moduleReferenceResolution(
  context: ResolverWalkContext,
  found: Binding,
  name: string,
  namespace: string,
  role: string,
) -> ReferenceResolution {
  if found.declarationKind == "selected-import" {
    return ReferenceResolution {
      referenceNamespace: namespace,
      targetModuleIndex: context.moduleIndex,
      targetLo: found.lo,
      targetHi: found.hi,
      targetNamespace: if role == "type" {
        namespace
      } else {
        effectiveNamespace(found, context.tables)
      },
      targetModule: if role == "type" {
        context.table.identity
      } else {
        found.targetModule
      },
      targetName: if role == "type" { name } else { found.targetName },
    }
  } else if found.declarationKind == "namespace-import" {
    return ReferenceResolution {
      referenceNamespace: "module",
      targetModuleIndex: context.moduleIndex,
      targetLo: found.lo,
      targetHi: found.hi,
      targetNamespace: found.namespace,
      targetModule: found.targetModule,
      targetName: "",
    }
  }
  ReferenceResolution {
    referenceNamespace: namespace,
    targetModuleIndex: context.moduleIndex,
    targetLo: found.lo,
    targetHi: found.hi,
    targetNamespace: found.namespace,
    targetModule: context.table.identity,
    targetName: name,
  }
}

function reference(
  context: ResolverWalkContext,
  scopes: Array<LocalScope>,
  name: string,
  namespace: string,
  role: string,
  lo: int,
  hi: int,
) -> Option<Binding> {
  let mut moduleBinding: Option<Binding> = None
  let resolved = match localReferenceResolution(
    context,
    scopes,
    name,
    namespace,
  ) {
    case Some(value) => value
    case None => match tableBinding(context.table, name) {
      case Some(binding) => {
        moduleBinding = Some(binding)
        moduleReferenceResolution(
          context,
          binding,
          name,
          namespace,
          role,
        )
      }
      case None => unresolvedReference(namespace)
    }
  }
  appendReference(context, scopes, name, role, lo, hi, resolved)
  moduleBinding
}

function namespaceMemberResolution(
  context: ResolverWalkContext,
  binding: Binding,
  member: string,
  namespace: string,
  field: SyntaxNode,
) -> ReferenceResolution {
  let targetTable = match catalogTable(context.tables, binding.targetModule) {
    case Some(found) => found
    case None => return unresolvedReference(namespace)
  }
  let targetBinding = tableBinding(targetTable, member)
  let targetExport = exportedBinding(targetTable, member)
  let targetNamespace = match targetExport {
    case Some(exported) => exported.namespace
    case None => ""
  }
  let memberExported = !isNone(targetExport)
  let keywordNamed = namespace == "value" &&
    keywordKind(member).startsWith("keyword/")
  if keywordNamed {
    diagnostic(
      context.diagnostics,
      context.moduleIndex,
      "TPZ3013",
      "namespace members are exported declarations and cannot be keyword-named (`{binding.name}.{member}`)",
      field.lo,
      field.hi,
    )
  } else if !memberExported {
    let mut recordDefaultPrivateValue = false
    if namespace == "value" && context.recordDefaultStack.length > 0 {
      match targetBinding {
        case Some(privateBinding) => if privateBinding.declarationKind == "let" &&
          !privateBinding.mutable && !privateBinding.exported {
          recordDefaultPrivateValue = true
        }
        case None => ()
      }
    }
    if !recordDefaultPrivateValue {
      let hint = didYouMean(
        member,
        exportedNames(targetTable, namespace),
      )
      diagnostic(
        context.diagnostics,
        context.moduleIndex,
        "TPZ3009",
        "`{member}` is not exported by `{binding.targetModule}`{hint}",
        field.lo,
        field.hi,
      )
    }
  }
  let target = match targetBinding {
    case Some(found) => found
    case None => return unresolvedReference(namespace)
  }
  // Nominal constructor heads retain their type-space declaration identity.
  // Pure aliases remain forbidden as values; construction is checked later.
  if !keywordNamed && memberExported && namespace == "value" &&
    targetNamespace == "type" && target.declarationKind != "nominal-type" {
    diagnostic(
      context.diagnostics,
      context.moduleIndex,
      "TPZ3013",
      "`{member}` is an exported type alias of `{binding.targetModule}`, not a value; use it in type position",
      field.lo,
      field.hi,
    )
  } else if !keywordNamed && memberExported && namespace == "type" &&
    targetNamespace != "type" {
    diagnostic(
      context.diagnostics,
      context.moduleIndex,
      "TPZ3013",
      "`{member}` is exported by `{binding.targetModule}` but is not a type alias",
      field.lo,
      field.hi,
    )
  }
  ReferenceResolution {
    referenceNamespace: namespace,
    targetModuleIndex: target.moduleIndex,
    targetLo: target.lo,
    targetHi: target.hi,
    targetNamespace: if namespace == "type" || targetNamespace == "type" {
      "type"
    } else {
      "value"
    },
    targetModule: binding.targetModule,
    targetName: member,
  }
}

function namespaceMember(
  context: ResolverWalkContext,
  scopes: Array<LocalScope>,
  object: SyntaxNode,
  field: SyntaxNode,
  namespace: string,
  role: string,
) -> bool {
  let head = text(context.source, object)
  if match localBinding(scopes, head, "value") {
    case Some(_) => true
    case None => false
  } {
    return false
  }
  let binding = match tableBinding(context.table, head) {
    case Some(found) => found
    case None => return false
  }
  if binding.declarationKind != "namespace-import" {
    return false
  }
  let member = text(context.source, field)
  let resolved = namespaceMemberResolution(
    context,
    binding,
    member,
    namespace,
    field,
  )
  appendReference(
    context,
    scopes,
    "{head}.{member}",
    role,
    field.lo,
    field.hi,
    resolved,
  )
  true
}

function pushScope(
  moduleIndexValue: int,
  owner: SyntaxNode,
  kind: string,
  scopes: Array<LocalScope>,
  nextScope: Array<int>,
  output: Array<PreviewResolvedScope>,
) -> int {
  let ordinal = nextScope[0]
  let mut nextScopeBox = nextScope
  nextScopeBox[0] = ordinal + 1
  let mut rows = output
  rows.push(PreviewResolvedScope {
    moduleIndex: moduleIndexValue,
    ordinal: ordinal,
    parentOrdinal: currentScope(scopes),
    kind: kind,
    lo: owner.lo,
    hi: owner.hi,
  })
  let mut active = scopes
  active.push(LocalScope {
    ordinal: ordinal,
    values: map {},
    types: map {},
  })
  ordinal
}

function popScope(scopes: Array<LocalScope>) -> () {
  let mut activeScopes = scopes
  match activeScopes.pop() {
    case Some(_) => ()
    case None => ()
  }
}

function bindPattern(
  moduleIndexValue: int,
  pattern: SyntaxNode,
  source: Bytes,
  declarationKind: string,
  scopes: Array<LocalScope>,
  declarations: Array<PreviewResolvedDeclaration>,
) -> () {
  let mut names: Array<SyntaxNode> = []
  collectPatternBindings(pattern, source, names)
  for name in names {
    addLocalBinding(scopes, declarations, Binding {
      moduleIndex: moduleIndexValue,
      scopeOrdinal: currentScope(scopes),
      name: text(source, name),
      namespace: "value",
      declarationKind: declarationKind,
      lo: name.lo,
      hi: name.hi,
      exported: false,
      targetModule: "",
      targetName: "",
      mutable: false,
    })
  }
  ()
}

function walkProtocolStatement(
  context: ResolverWalkContext,
  node: SyntaxNode,
  scopes: Array<LocalScope>,
) -> () {
  match child(node, "name") {
    case Some(name) => {
      let protocolName = text(context.source, name)
      let alreadyBound = match localBinding(scopes, protocolName, "type") {
        case Some(binding) => binding.scopeOrdinal == currentScope(scopes) &&
          binding.lo == name.lo && binding.hi == name.hi
        case None => false
      }
      if !alreadyBound {
        let mut declarations = context.declarationOutput
        declarations.push(PreviewResolvedDeclaration {
          moduleIndex: context.moduleIndex,
          scopeOrdinal: currentScope(scopes),
          name: protocolName,
          namespace: "type",
          declarationKind: "protocol",
          lo: name.lo,
          hi: name.hi,
          exported: false,
          targetModule: "",
          targetName: "",
        })
      }
    }
    case None => ()
  }
  for method in children(node, "methods") {
    for parameter in children(method, "parameters") {
      match child(parameter, "type") {
        case Some(parameterType) => walkNode(context, parameterType, scopes)
        case None => ()
      }
    }
    match child(method, "returnType") {
      case Some(returnType) => walkNode(context, returnType, scopes)
      case None => ()
    }
  }
  ()
}

function walkUsingStatement(
  context: ResolverWalkContext,
  node: SyntaxNode,
  scopes: Array<LocalScope>,
) -> () {
  match child(node, "value") {
    case Some(value) => walkNode(context, value, scopes)
    case None => ()
  }
  match child(node, "body") {
    case Some(body) => {
      pushScope(
        context.moduleIndex,
        body,
        "using",
        scopes,
        context.nextScope,
        context.scopeOutput,
      )
      match child(node, "name") {
        case Some(name) => addLocalBinding(
          scopes,
          context.declarationOutput,
          Binding {
            moduleIndex: context.moduleIndex,
            scopeOrdinal: currentScope(scopes),
            name: text(context.source, name),
            namespace: "value",
            declarationKind: "using",
            lo: name.lo,
            hi: name.hi,
            exported: false,
            targetModule: "",
            targetName: "",
            mutable: false,
          },
        )
        case None => ()
      }
      walkNode(context, body, scopes)
      popScope(scopes)
    }
    case None => ()
  }
  ()
}

function walkComprehensionExpression(
  context: ResolverWalkContext,
  node: SyntaxNode,
  scopes: Array<LocalScope>,
) -> () {
  let mut opened = 0
  for clause in children(node, "clauses") {
    if clause.kind == "comprehension-clause/for" {
      match child(clause, "iterator") {
        case Some(iterator) => walkNode(context, iterator, scopes)
        case None => ()
      }
      match child(clause, "pattern") {
        case Some(pattern) => {
          pushScope(
            context.moduleIndex,
            pattern,
            "comprehension",
            scopes,
            context.nextScope,
            context.scopeOutput,
          )
          bindPattern(
            context.moduleIndex,
            pattern,
            context.source,
            "pattern",
            scopes,
            context.declarationOutput,
          )
          walkNode(context, pattern, scopes)
          opened += 1
        }
        case None => ()
      }
    } else {
      for part in clause.children {
        walkNode(context, part, scopes)
      }
    }
  }
  for found in node.children {
    if found.field == "body" || found.field == "bodyKey" ||
      found.field == "bodyValue" {
      walkNode(context, found, scopes)
    }
  }
  while opened > 0 {
    popScope(scopes)
    opened -= 1
  }
  ()
}

function openPatternScope(
  context: ResolverWalkContext,
  pattern: SyntaxNode,
  scopes: Array<LocalScope>,
) -> () {
  walkNode(context, pattern, scopes)
  pushScope(
    context.moduleIndex,
    pattern,
    "pattern",
    scopes,
    context.nextScope,
    context.scopeOutput,
  )
  bindPattern(
    context.moduleIndex,
    pattern,
    context.source,
    "pattern",
    scopes,
    context.declarationOutput,
  )
  ()
}

function walkMatchCase(
  context: ResolverWalkContext,
  node: SyntaxNode,
  scopes: Array<LocalScope>,
) -> () {
  let mut opened = false
  match child(node, "pattern") {
    case Some(pattern) => {
      openPatternScope(context, pattern, scopes)
      opened = true
    }
    case None => ()
  }
  for found in node.children {
    if found.field != "pattern" {
      walkNode(context, found, scopes)
    }
  }
  if opened {
    popScope(scopes)
  }
  ()
}

function walkForExpression(
  context: ResolverWalkContext,
  node: SyntaxNode,
  scopes: Array<LocalScope>,
) -> () {
  match child(node, "iterator") {
    case Some(iterator) => walkNode(context, iterator, scopes)
    case None => ()
  }
  let mut opened = false
  match child(node, "pattern") {
    case Some(pattern) => {
      openPatternScope(context, pattern, scopes)
      opened = true
    }
    case None => ()
  }
  for found in node.children {
    if found.field != "iterator" && found.field != "pattern" {
      walkNode(context, found, scopes)
    }
  }
  if opened {
    popScope(scopes)
  }
  ()
}

function resolveAssignmentIdentifier(
  context: ResolverWalkContext,
  target: SyntaxNode,
  scopes: Array<LocalScope>,
) -> () {
  let name = text(context.source, target)
  let binding = match reference(
    context,
    scopes,
    name,
    "value",
    "write",
    target.lo,
    target.hi,
  ) {
    case Some(found) => found
    case None => return ()
  }
  if binding.declarationKind == "selected-import" {
    diagnostic(
      context.diagnostics,
      context.moduleIndex,
      "TPZ3015",
      "`{name}` is an imported binding and cannot be assigned",
      target.lo,
      target.hi,
    )
  } else if binding.declarationKind == "namespace-import" {
    diagnostic(
      context.diagnostics,
      context.moduleIndex,
      "TPZ3012",
      "`{name}` is a namespace, not a value; it may appear only as `{name}.member`",
      target.lo,
      target.hi,
    )
  }
  ()
}

function rejectNamespaceAssignment(
  context: ResolverWalkContext,
  target: SyntaxNode,
  scopes: Array<LocalScope>,
) -> bool {
  if target.kind != "expression/member" {
    return false
  }
  let object = match child(target, "object") {
    case Some(found) => found
    case None => return false
  }
  if object.kind != "expression/identifier" {
    return false
  }
  let name = text(context.source, object)
  if !isNone(localBinding(scopes, name, "value")) {
    return false
  }
  let binding = match tableBinding(context.table, name) {
    case Some(found) => found
    case None => return false
  }
  if binding.declarationKind != "namespace-import" {
    return false
  }
  let member = match child(target, "field") {
    case Some(field) => text(context.source, field)
    case None => ""
  }
  diagnostic(
    context.diagnostics,
    context.moduleIndex,
    "TPZ3015",
    "`{name}.{member}` is an exported binding viewed through a namespace and cannot be assigned",
    target.lo,
    target.hi,
  )
  true
}

function walkAssignmentStatement(
  context: ResolverWalkContext,
  node: SyntaxNode,
  scopes: Array<LocalScope>,
) -> () {
  match child(node, "target") {
    case Some(target) => if target.kind == "expression/identifier" {
      resolveAssignmentIdentifier(context, target, scopes)
    } else if !rejectNamespaceAssignment(context, target, scopes) {
      walkNode(context, target, scopes)
    }
    case None => ()
  }
  match child(node, "value") {
    case Some(value) => walkNode(context, value, scopes)
    case None => ()
  }
  ()
}

function resolveNamedTypeReference(
  context: ResolverWalkContext,
  node: SyntaxNode,
  scopes: Array<LocalScope>,
) -> () {
  match child(node, "name") {
    case Some(name) => {
      reference(
        context,
        scopes,
        text(context.source, name),
        "type",
        "type",
        name.lo,
        name.hi,
      )
      ()
    }
    case None => ()
  }
  ()
}

function resolveQualifiedTypeReference(
  context: ResolverWalkContext,
  node: SyntaxNode,
  scopes: Array<LocalScope>,
) -> () {
  match child(node, "namespace") {
    case Some(namespaceNode) => match child(node, "name") {
      case Some(name) => if !namespaceMember(
        context,
        scopes,
        namespaceNode,
        name,
        "type",
        "type",
      ) {
        diagnostic(
          context.diagnostics,
          context.moduleIndex,
          "TPZ3013",
          "the head of a qualified type must be a namespace binding; `{text(context.source, namespaceNode)}` is not one here",
          namespaceNode.lo,
          namespaceNode.hi,
        )
      }
      case None => ()
    }
    case None => ()
  }
  ()
}

function resolveValueIdentifier(
  context: ResolverWalkContext,
  node: SyntaxNode,
  scopes: Array<LocalScope>,
) -> () {
  let name = text(context.source, node)
  let binding = match reference(
    context,
    scopes,
    name,
    "value",
    "read",
    node.lo,
    node.hi,
  ) {
    case Some(found) => found
    case None => return ()
  }
  if binding.declarationKind == "namespace-import" {
    diagnostic(
      context.diagnostics,
      context.moduleIndex,
      "TPZ3012",
      "`{name}` is a namespace, not a value; it may appear only as `{name}.member`",
      node.lo,
      node.hi,
    )
  }
  ()
}

function resolveNamespaceMemberReference(
  context: ResolverWalkContext,
  node: SyntaxNode,
  scopes: Array<LocalScope>,
) -> bool {
  if node.kind != "expression/member" {
    return false
  }
  match child(node, "object") {
    case Some(object) => match child(node, "field") {
      case Some(field) => object.kind == "expression/identifier" &&
        namespaceMember(
          context,
          scopes,
          object,
          field,
          "value",
          "namespace-member",
        )
      case None => false
    }
    case None => false
  }
}

function walkCallableSignature(
  context: ResolverWalkContext,
  node: SyntaxNode,
  scopes: Array<LocalScope>,
) -> () {
  if node.kind != "function-declaration" &&
    node.kind != "expression/lambda" {
    return ()
  }
  for parameter in children(node, "parameters") {
    for part in parameter.children {
      if part.field == "type" || part.field == "default" {
        walkNode(context, part, scopes)
      }
    }
  }
  match child(node, "returnType") {
    case Some(returnType) => walkNode(context, returnType, scopes)
    case None => ()
  }
  ()
}

function openNodeScope(
  context: ResolverWalkContext,
  node: SyntaxNode,
  scopes: Array<LocalScope>,
) -> bool {
  let kind = match node.kind {
    case "function-declaration" => "function"
    case "expression/lambda" => "lambda"
    case "block" => "block"
    case _ => ""
  }
  if kind == "" {
    return false
  }
  let ordinal = pushScope(
    context.moduleIndex,
    node,
    kind,
    scopes,
    context.nextScope,
    context.scopeOutput,
  )
  if node.kind == "function-declaration" ||
    node.kind == "expression/lambda" {
    for parameter in children(node, "parameters") {
      match child(parameter, "name") {
        case Some(name) => addLocalBinding(
          scopes,
          context.declarationOutput,
          Binding {
            moduleIndex: context.moduleIndex,
            scopeOrdinal: ordinal,
            name: text(context.source, name),
            namespace: "value",
            declarationKind: "parameter",
            lo: name.lo,
            hi: name.hi,
            exported: false,
            targetModule: "",
            targetName: "",
            mutable: false,
          },
        )
        case None => ()
      }
    }
  }
  true
}

function prebindChildDeclaration(
  context: ResolverWalkContext,
  childNode: SyntaxNode,
  scopes: Array<LocalScope>,
) -> () {
  if scopes.length == 0 {
    return ()
  }
  for candidate in bindingForStatement(
    context.moduleIndex,
    childNode,
    context.source,
    false,
  ) {
    if candidate.declarationKind != "let" &&
      candidate.declarationKind != "const" &&
      candidate.declarationKind != "namespace-import" &&
      candidate.declarationKind != "selected-import" {
      addLocalBinding(
        scopes,
        context.declarationOutput,
        Binding {
          moduleIndex: context.moduleIndex,
          scopeOrdinal: currentScope(scopes),
          name: candidate.name,
          namespace: candidate.namespace,
          declarationKind: candidate.declarationKind,
          lo: candidate.lo,
          hi: candidate.hi,
          exported: false,
          targetModule: "",
          targetName: "",
          mutable: candidate.mutable,
        },
      )
    }
  }
  ()
}

function bindStatementAfterWalk(
  context: ResolverWalkContext,
  node: SyntaxNode,
  scopes: Array<LocalScope>,
) -> () {
  if node.kind == "statement/let" {
    match child(node, "pattern") {
      case Some(pattern) => {
        let mut names: Array<SyntaxNode> = []
        collectPatternBindings(pattern, context.source, names)
        for name in names {
          addLocalBinding(
            scopes,
            context.declarationOutput,
            Binding {
              moduleIndex: context.moduleIndex,
              scopeOrdinal: currentScope(scopes),
              name: text(context.source, name),
              namespace: "value",
              declarationKind: "let",
              lo: name.lo,
              hi: name.hi,
              exported: false,
              targetModule: "",
              targetName: "",
              mutable: boolAttribute(node, "mutable"),
            },
          )
        }
      }
      case None => ()
    }
  } else if node.kind == "statement/const" && scopes.length > 0 {
    match child(node, "name") {
      case Some(name) => addLocalBinding(
        scopes,
        context.declarationOutput,
        Binding {
          moduleIndex: context.moduleIndex,
          scopeOrdinal: currentScope(scopes),
          name: text(context.source, name),
          namespace: "value",
          declarationKind: "const",
          lo: name.lo,
          hi: name.hi,
          exported: false,
          targetModule: "",
          targetName: "",
          mutable: false,
        },
      )
      case None => ()
    }
  }
  ()
}

function walkNodeChildren(
  context: ResolverWalkContext,
  node: SyntaxNode,
  scopes: Array<LocalScope>,
) -> () {
  if node.kind == "block" {
    for statement in children(node, "statements") {
      if statement.kind == "statement/function" {
        prebindChildDeclaration(context, statement, scopes)
      }
    }
  }
  for found in node.children {
    if found.kind == "identifier" {
      continue
    }
    // Explicit call type arguments need the same declaration references as an
    // annotation. In particular, a namespace-qualified nominal must retain its
    // defining module rather than falling through to an opaque foreign type.
    if (node.kind == "function-declaration" ||
      node.kind == "expression/lambda") &&
      (found.field == "parameters" || found.field == "returnType") {
      continue
    }
    if !(node.kind == "block" && found.kind == "statement/function") {
      prebindChildDeclaration(context, found, scopes)
    }
    let recordDefault = node.kind == "record-field-declaration" &&
      found.field == "default"
    if recordDefault {
      let mut stack = context.recordDefaultStack
      stack.push(true)
    }
    walkNode(context, found, scopes)
    if recordDefault {
      let mut stack = context.recordDefaultStack
      stack.pop()
    }
    bindStatementAfterWalk(context, found, scopes)
  }
  ()
}

export function walkNode(
  context: ResolverWalkContext,
  nodeValue: SyntaxNode,
  scopes: Array<LocalScope>,
) -> () {
  let mut activeScopes = scopes
  if nodeValue.kind == "identifier" {
    return ()
  }
  if nodeValue.kind == "statement/protocol" {
    walkProtocolStatement(context, nodeValue, activeScopes)
    return ()
  }
  if nodeValue.kind == "statement/using" {
    walkUsingStatement(context, nodeValue, activeScopes)
    return ()
  }
  if nodeValue.kind == "expression/comprehension" {
    walkComprehensionExpression(context, nodeValue, activeScopes)
    return ()
  }
  if nodeValue.kind == "match-case" {
    walkMatchCase(context, nodeValue, activeScopes)
    return ()
  }
  if nodeValue.kind == "expression/for" {
    walkForExpression(context, nodeValue, activeScopes)
    return ()
  }
  if nodeValue.kind == "statement/assign" {
    walkAssignmentStatement(context, nodeValue, scopes)
    return ()
  }
  if nodeValue.kind == "type/named" {
    resolveNamedTypeReference(context, nodeValue, scopes)
  } else if nodeValue.kind == "pattern/nominal-record" {
    resolveNamedTypeReference(context, nodeValue, scopes)
  } else if nodeValue.kind == "type/qualified" {
    resolveQualifiedTypeReference(context, nodeValue, scopes)
  } else if nodeValue.kind == "expression/identifier" {
    resolveValueIdentifier(context, nodeValue, scopes)
  } else if resolveNamespaceMemberReference(context, nodeValue, scopes) {
    return ()
  }

  walkCallableSignature(context, nodeValue, scopes)
  let opened = openNodeScope(context, nodeValue, activeScopes)
  walkNodeChildren(context, nodeValue, activeScopes)
  if opened {
    popScope(activeScopes)
  }
}

// Public type-surface checks and top-level initialization analysis.
// It consumes completed module and scope catalogs, then assembles accepted or
// rejected resolver outputs for the facade.

import types {
  PreviewImportEdge,
  PreviewModuleResult,
  PreviewResolvedDeclaration,
  PreviewResolvedDiagnostic,
  PreviewResolvedExport,
  PreviewResolvedReference,
  PreviewResolvedScope,
  ResolveResult,
  SyntaxNode,
}
import unicode { didYouMean }
import resolver.model_facts {
  InitViolation,
  LocalScope,
  ModuleDraft,
  ModuleTable,
  ModuleTableCatalog,
  ResolverOutputs,
  ResolverWalkContext,
  attribute,
  child,
  children,
  diagnostic,
  isNone,
  spanText,
  stringJoin,
  text,
}
import resolver.modules_tables {
  catalogTable,
  effectiveNamespace,
  exportedBinding,
  exportedNames,
  tableBinding,
  unwrapExport,
}
import resolver.scopes_walk {
  addDeclaration,
  appendModuleExports,
  walkNode,
}

function privatePublicSurfaceTypeBinding(
  table: ModuleTable,
  name: string,
) -> bool {
  let binding = match tableBinding(table, name) {
    case Some(found) => found
    case None => return false
  }
  binding.namespace == "type" &&
    !binding.exported &&
    (binding.declarationKind == "type-alias" ||
      binding.declarationKind == "nominal-type")
}

function validatePublicTypeTree(
  source: Bytes,
  nodeValue: SyntaxNode,
  table: ModuleTable,
  diagnostics: Array<PreviewResolvedDiagnostic>,
) -> () {
  if nodeValue.kind == "type/named" {
    match child(nodeValue, "name") {
      case Some(name) => {
        let nameText = text(source, name)
        if privatePublicSurfaceTypeBinding(table, nameText) {
          diagnostic(
            diagnostics,
            table.moduleIndex,
            "TPZ3014",
            "`{nameText}` is a module-private type and may not appear in an exported public surface; export the type or use an inline structural type",
            name.lo,
            name.hi,
          )
        }
      }
      case None => ()
    }
  }
  for found in nodeValue.children {
    validatePublicTypeTree(source, found, table, diagnostics)
  }
  ()
}

function validateExportSignature(
  source: Bytes,
  statement: SyntaxNode,
  table: ModuleTable,
  diagnostics: Array<PreviewResolvedDiagnostic>,
) -> () {
  if statement.kind != "statement/export" {
    return ()
  }
  let item = unwrapExport(statement)
  if item.kind == "statement/function" {
    match child(item, "declaration") {
      case Some(declaration) => {
        for parameter in children(declaration, "parameters") {
          match child(parameter, "type") {
            case Some(typeNode) =>
              validatePublicTypeTree(source, typeNode, table, diagnostics)
            case None => ()
          }
        }
        match child(declaration, "returnType") {
          case Some(typeNode) =>
            validatePublicTypeTree(source, typeNode, table, diagnostics)
          case None => ()
        }
      }
      case None => ()
    }
    return ()
  }
  if item.kind == "statement/type-alias" {
    match child(item, "type") {
      case Some(typeNode) => validatePublicTypeTree(source, typeNode, table, diagnostics)
      case None => ()
    }
    return ()
  }
  if item.kind == "statement/enum" {
    for variant in children(item, "variants") {
      for typeNode in children(variant, "payload") {
        validatePublicTypeTree(source, typeNode, table, diagnostics)
      }
    }
    return ()
  }
  if item.kind == "statement/record" {
    for field in children(item, "fields") {
      match child(field, "type") {
        case Some(typeNode) => validatePublicTypeTree(source, typeNode, table, diagnostics)
        case None => ()
      }
    }
    return ()
  }
  if item.kind == "statement/newtype" {
    match child(item, "base") {
      case Some(typeNode) => validatePublicTypeTree(source, typeNode, table, diagnostics)
      case None => ()
    }
    return ()
  }
  if item.kind == "statement/let" {
    match child(item, "type") {
      case Some(typeNode) => validatePublicTypeTree(source, typeNode, table, diagnostics)
      case None => ()
    }
  }
  ()
}

function validateExportSignatures(
  module: ModuleDraft,
  table: ModuleTable,
  diagnostics: Array<PreviewResolvedDiagnostic>,
) -> () {
  let source = module.source
  for statement in module.root.children {
    validateExportSignature(source, statement, table, diagnostics)
  }
  ()
}

export function validateImportSurfaces(
  modules: Array<ModuleDraft>,
  tables: ModuleTableCatalog,
  diagnostics: Array<PreviewResolvedDiagnostic>,
) -> () {
  let mut importingIndex = 0
  for module in modules {
    for import in module.imports {
      match catalogTable(tables, import.target) {
        case Some(targetTable) => if targetTable.exportedNames.length == 0 {
          diagnostic(
            diagnostics,
            importingIndex,
            "TPZ3010",
            "`{import.target}` exports nothing; v5.2 has no side-effect-only imports",
            import.pathLo,
            import.pathHi,
          )
        } else {
          let mut selectedIndex = 0
          for selected in import.selectedNames {
            if isNone(exportedBinding(targetTable, selected)) {
              let hint = didYouMean(
                selected,
                exportedNames(targetTable, ""),
              )
              diagnostic(
                diagnostics,
                importingIndex,
                "TPZ3009",
                "`{selected}` is not exported by `{import.target}`{hint}",
                import.selectedLos[selectedIndex],
                import.selectedHis[selectedIndex],
              )
            }
            selectedIndex += 1
          }
        }
        case None => ()
      }
    }
    validateExportSignatures(module, tables.tables[importingIndex], diagnostics)
    importingIndex += 1
  }
  ()
}

function resolveModuleFacts(
  module: ModuleDraft,
  index: int,
  tables: ModuleTableCatalog,
  outputs: ResolverOutputs,
  diagnostics: Array<PreviewResolvedDiagnostic>,
) -> () {
  let mut moduleResults = outputs.modules
  moduleResults.push(module.result)
  let mut scopes = outputs.scopes
  scopes.push(PreviewResolvedScope {
    moduleIndex: index,
    ordinal: 0,
    parentOrdinal: -1,
    kind: "module",
    lo: module.root.lo,
    hi: module.root.hi,
  })
  let table = tables.tables[index]
  for binding in table.bindings {
    if binding.declarationKind != "protocol" {
      addDeclaration(
        outputs.declarations,
        binding,
        effectiveNamespace(binding, tables),
        !isNone(exportedBinding(table, binding.name)),
      )
    }
  }
  appendModuleExports(outputs.exports, index, table)
  let mut localScopes: Array<LocalScope> = []
  let mut nextScope: Array<int> = [1]
  let walkContext = ResolverWalkContext {
    moduleIndex: index,
    source: module.source,
    table: table,
    tables: tables,
    nextScope: nextScope,
    scopeOutput: outputs.scopes,
    declarationOutput: outputs.declarations,
    referenceOutput: outputs.references,
    diagnostics: diagnostics,
    recordDefaultStack: [],
  }
  for statement in module.root.children {
    let item = unwrapExport(statement)
    if item.kind != "statement/import" {
      walkNode(walkContext, item, localScopes)
    }
  }
  ()
}

function initPatternNames(
  pattern: SyntaxNode,
  source: Bytes,
  output: Array<string>,
) -> () {
  if pattern.kind == "pattern/binding" || pattern.kind == "pattern/typed" {
    match child(pattern, "name") {
      case Some(name) => {
        let mut names = output
        names.push(text(source, name))
      }
      case None => ()
    }
    return ()
  }
  if pattern.kind == "pattern/or" {
    for alternative in children(pattern, "alternatives") {
      initPatternNames(alternative, source, output)
    }
    return ()
  }
  if pattern.kind == "pattern/constructor" {
    for argument in children(pattern, "arguments") {
      initPatternNames(argument, source, output)
    }
    return ()
  }
  if pattern.kind == "pattern/list" {
    for element in children(pattern, "elements") {
      if element.kind == "list-pattern/rest" {
        match element.children.get(0) {
          case Some(binding) => initPatternNames(binding, source, output)
          case None => ()
        }
      } else {
        initPatternNames(element, source, output)
      }
    }
    return ()
  }
  if pattern.kind == "pattern/record" ||
    pattern.kind == "pattern/nominal-record" {
    for field in children(pattern, "fields") {
      match child(field, "pattern") {
        case Some(found) => initPatternNames(found, source, output)
        case None => match child(field, "name") {
          case Some(name) => {
            let mut names = output
            names.push(text(source, name))
          }
          case None => ()
        }
      }
    }
  }
  ()
}

function initItemNames(item: SyntaxNode, source: Bytes) -> Array<string> {
  let mut output: Array<string> = []
  if item.kind == "statement/let" {
    match child(item, "pattern") {
      case Some(pattern) => initPatternNames(pattern, source, output)
      case None => ()
    }
  } else if item.kind == "statement/function" {
    match child(item, "declaration") {
      case Some(declaration) => match child(declaration, "name") {
        case Some(name) => output.push(text(source, name))
        case None => ()
      }
      case None => ()
    }
  }
  output
}

function initLocalContains(locals: Array<string>, name: string) -> bool {
  for local in locals {
    if local == name {
      return true
    }
  }
  false
}

function initObserveReference(
  node: SyntaxNode,
  source: Bytes,
  table: ModuleTable,
  itemLo: int,
  locals: Array<string>,
  violation: Array<InitViolation>,
) -> () {
  if violation.length > 0 {
    return ()
  }
  let name = text(source, node)
  if initLocalContains(locals, name) {
    return ()
  }
  // ModuleTable already owns every unique top-level binding. Since item spans
  // are ordered and non-overlapping, declaration byte >= current item byte is
  // the self-host form of Stage 0's textual binding index >= item index rule.
  let binding = match tableBinding(table, name) {
    case Some(found) => found
    case None => return ()
  }
  if (binding.declarationKind == "let" ||
    binding.declarationKind == "function") && binding.lo >= itemLo {
    let mut found = violation
    found.push(InitViolation { name: name, lo: node.lo, hi: node.hi })
  }
  ()
}

function initScanChild(
  owner: SyntaxNode,
  field: string,
  source: Bytes,
  table: ModuleTable,
  itemLo: int,
  locals: Array<string>,
  violation: Array<InitViolation>,
) -> () {
  match child(owner, field) {
    case Some(found) => initScanExpression(
      found,
      source,
      table,
      itemLo,
      locals,
      violation,
    )
    case None => ()
  }
  ()
}

function initScanTwoChildren(
  owner: SyntaxNode,
  first: string,
  second: string,
  source: Bytes,
  table: ModuleTable,
  itemLo: int,
  locals: Array<string>,
  violation: Array<InitViolation>,
) -> () {
  initScanChild(owner, first, source, table, itemLo, locals, violation)
  initScanChild(owner, second, source, table, itemLo, locals, violation)
  ()
}

function initScanThreeChildren(
  owner: SyntaxNode,
  first: string,
  second: string,
  third: string,
  source: Bytes,
  table: ModuleTable,
  itemLo: int,
  locals: Array<string>,
  violation: Array<InitViolation>,
) -> () {
  initScanTwoChildren(
    owner,
    first,
    second,
    source,
    table,
    itemLo,
    locals,
    violation,
  )
  initScanChild(owner, third, source, table, itemLo, locals, violation)
  ()
}

function initScanExpression(
  expression: SyntaxNode,
  source: Bytes,
  table: ModuleTable,
  itemLo: int,
  locals: Array<string>,
  violation: Array<InitViolation>,
) -> () {
  if expression.kind == "expression/identifier" {
    return initObserveReference(
      expression,
      source,
      table,
      itemLo,
      locals,
      violation,
    )
  }
  if expression.kind == "expression/call" {
    let mut argumentsImmediate = true
    match child(expression, "callee") {
      case Some(callee) => {
        if callee.kind == "expression/optional-access" {
          argumentsImmediate = false
        }
        if callee.kind == "expression/identifier" {
          initObserveReference(callee, source, table, itemLo, locals, violation)
        } else if callee.kind != "expression/lambda" {
          initScanExpression(callee, source, table, itemLo, locals, violation)
        }
      }
      case None => ()
    }
    if argumentsImmediate {
      for argument in children(expression, "arguments") {
        if argument.kind == "call-argument/spread" ||
          argument.kind == "call-argument/named" {
          initScanChild(argument, "value", source, table, itemLo, locals, violation)
        } else {
          initScanExpression(argument, source, table, itemLo, locals, violation)
        }
      }
    }
    return ()
  }
  if expression.kind == "expression/lambda" {
    return ()
  }
  if expression.kind == "expression/block" {
    match child(expression, "block") {
      case Some(block) => initScanBlock(block, source, table, itemLo, locals, violation)
      case None => ()
    }
    return ()
  }
  let immediateField = match expression.kind {
    case "expression/if" => "condition"
    case "expression/match" => "scrutinee"
    case "expression/for" => "iterator"
    case "expression/concurrent" => "timeout"
    case "expression/unary" | "expression/try" => "operand"
    case "expression/member" | "expression/optional-access" => "object"
    case _ => ""
  }
  if immediateField != "" {
    initScanChild(
      expression,
      immediateField,
      source,
      table,
      itemLo,
      locals,
      violation,
    )
    return ()
  }
  if expression.kind == "expression/comprehension" {
    match children(expression, "clauses").get(0) {
      case Some(clause) => if clause.kind == "comprehension-clause/for" {
        initScanChild(clause, "iterator", source, table, itemLo, locals, violation)
      }
      case None => ()
    }
    return ()
  }
  if expression.kind == "expression/parenthesized" {
    match expression.children.get(0) {
      case Some(inner) => initScanExpression(
        inner,
        source,
        table,
        itemLo,
        locals,
        violation,
      )
      case None => ()
    }
    return ()
  }
  if expression.kind == "expression/index" {
    initScanTwoChildren(
      expression,
      "object",
      "index",
      source,
      table,
      itemLo,
      locals,
      violation,
    )
    return ()
  }
  if expression.kind == "expression/binary" {
    initScanChild(expression, "left", source, table, itemLo, locals, violation)
    let operator = attribute(expression, "operator")
    if operator != "and" && operator != "or" && operator != "coalesce" {
      initScanChild(expression, "right", source, table, itemLo, locals, violation)
    }
    return ()
  }
  if expression.kind == "expression/compose" {
    initScanTwoChildren(
      expression,
      "left",
      "right",
      source,
      table,
      itemLo,
      locals,
      violation,
    )
    return ()
  }
  if expression.kind == "expression/range" {
    initScanThreeChildren(
      expression,
      "low",
      "high",
      "step",
      source,
      table,
      itemLo,
      locals,
      violation,
    )
    return ()
  }
  if expression.kind == "expression/pipe" {
    initScanTwoChildren(
      expression,
      "left",
      "right",
      source,
      table,
      itemLo,
      locals,
      violation,
    )
    return ()
  }
  if expression.kind == "expression/record-update" {
    initScanTwoChildren(
      expression,
      "base",
      "spread",
      source,
      table,
      itemLo,
      locals,
      violation,
    )
  }
  if expression.kind == "expression/record-literal" ||
    expression.kind == "expression/record-update" {
    for field in children(expression, "fields") {
      initScanChild(field, "value", source, table, itemLo, locals, violation)
    }
    return ()
  }
  if expression.kind == "expression/array" || expression.kind == "expression/set" {
    for element in children(expression, "elements") {
      if element.kind == "array-element/spread" {
        initScanChild(element, "value", source, table, itemLo, locals, violation)
      } else {
        initScanExpression(element, source, table, itemLo, locals, violation)
      }
    }
    return ()
  }
  if expression.kind == "expression/map" {
    for entry in children(expression, "entries") {
      initScanTwoChildren(
        entry,
        "key",
        "value",
        source,
        table,
        itemLo,
        locals,
        violation,
      )
    }
    return ()
  }
  if expression.kind == "expression/string" || expression.kind == "expression/template" {
    for part in children(expression, "parts") {
      if part.kind == "string-part/interpolation" {
        initScanChild(part, "value", source, table, itemLo, locals, violation)
      }
    }
  }
  ()
}

function initBindPattern(
  pattern: SyntaxNode,
  source: Bytes,
  locals: Array<string>,
) -> () {
  let mut bound: Array<string> = []
  initPatternNames(pattern, source, bound)
  let mut active = locals
  for name in bound {
    active.push(name)
  }
  ()
}

function initScanBlock(
  block: SyntaxNode,
  source: Bytes,
  table: ModuleTable,
  itemLo: int,
  locals: Array<string>,
  violation: Array<InitViolation>,
) -> () {
  let priorLocalCount = locals.length
  let mut active = locals
  for statement in children(block, "statements") {
    if statement.kind == "statement/function" {
      match child(statement, "declaration") {
        case Some(declaration) => match child(declaration, "name") {
          case Some(name) => active.push(text(source, name))
          case None => ()
        }
        case None => ()
      }
    } else if statement.kind == "statement/let" {
      initScanChild(statement, "value", source, table, itemLo, active, violation)
      match child(statement, "pattern") {
        case Some(pattern) => initBindPattern(pattern, source, active)
        case None => ()
      }
    } else if statement.kind == "statement/const" {
      initScanChild(statement, "value", source, table, itemLo, active, violation)
      match child(statement, "name") {
        case Some(name) => active.push(text(source, name))
        case None => ()
      }
    } else if statement.kind == "statement/using" {
      initScanChild(statement, "value", source, table, itemLo, active, violation)
      let priorUsingLocalCount = active.length
      match child(statement, "name") {
        case Some(name) => active.push(text(source, name))
        case None => ()
      }
      match child(statement, "body") {
        case Some(body) => initScanBlock(
          body,
          source,
          table,
          itemLo,
          active,
          violation,
        )
        case None => ()
      }
      while active.length > priorUsingLocalCount {
        active.pop()
      }
    } else if statement.kind == "statement/assign" {
      match child(statement, "target") {
        case Some(target) => if target.kind == "expression/identifier" {
          initObserveReference(target, source, table, itemLo, active, violation)
        } else {
          initScanExpression(target, source, table, itemLo, active, violation)
        }
        case None => ()
      }
      initScanChild(statement, "value", source, table, itemLo, active, violation)
    } else if statement.kind == "statement/return" ||
      statement.kind == "statement/expression" {
      initScanChild(statement, "value", source, table, itemLo, active, violation)
    } else if statement.kind == "statement/while" {
      initScanChild(statement, "condition", source, table, itemLo, active, violation)
    }
  }
  initScanChild(block, "tail", source, table, itemLo, active, violation)
  while active.length > priorLocalCount {
    active.pop()
  }
  ()
}

function initScanItem(
  item: SyntaxNode,
  source: Bytes,
  table: ModuleTable,
  violation: Array<InitViolation>,
) -> () {
  let mut locals: Array<string> = []
  if item.kind == "statement/let" || item.kind == "statement/expression" ||
    item.kind == "statement/return" {
    initScanChild(item, "value", source, table, item.lo, locals, violation)
  } else if item.kind == "statement/assign" {
    initScanTwoChildren(
      item,
      "target",
      "value",
      source,
      table,
      item.lo,
      locals,
      violation,
    )
  } else if item.kind == "statement/while" {
    initScanChild(item, "condition", source, table, item.lo, locals, violation)
  }
  ()
}

function validateImportedInitializers(
  modules: Array<ModuleDraft>,
  tables: ModuleTableCatalog,
  diagnostics: Array<PreviewResolvedDiagnostic>,
) -> () {
  let mut moduleIndexValue = 0
  for module in modules {
    if !module.result.entry {
      let source = module.source
      let table = tables.tables[moduleIndexValue]
      for statement in module.root.children {
        let item = unwrapExport(statement)
        let mut violation: Array<InitViolation> = []
        initScanItem(item, source, table, violation)
        match violation.get(0) {
          case Some(found) => {
            let owners = initItemNames(item, source)
            let owner = if owners.length == 0 {
              spanText(source, found.lo, found.hi)
            } else {
              stringJoin(owners, ", ")
            }
            diagnostic(
              diagnostics,
              moduleIndexValue,
              "TPZ3018",
              "the initializer of `{owner}` reaches `{found.name}`, whose initializer has not completed (v5.2 defines no partially initialized module binding)",
              found.lo,
              found.hi,
            )
          }
          case None => ()
        }
      }
    }
    moduleIndexValue += 1
  }
  ()
}

export function resolvedResult(
  modules: Array<ModuleDraft>,
  publicEdges: Array<PreviewImportEdge>,
  tables: ModuleTableCatalog,
  diagnostics: Array<PreviewResolvedDiagnostic>,
) -> Result<ResolveResult, string> {
  let outputs = ResolverOutputs {
    modules: [],
    scopes: [],
    declarations: [],
    references: [],
    exports: [],
  }
  let mut index = 0
  for module in modules {
    resolveModuleFacts(module, index, tables, outputs, diagnostics)
    index += 1
  }
  if diagnostics.length == 0 {
    validateImportedInitializers(modules, tables, diagnostics)
  }
  Ok(ResolveResult {
    queries: [],
    modules: outputs.modules,
    edges: publicEdges,
    scopes: outputs.scopes,
    declarations: outputs.declarations,
    references: outputs.references,
    exports: outputs.exports,
    diagnostics: diagnostics,
  })
}

export function rejectedResult(
  modules: Array<ModuleDraft>,
  publicEdges: Array<PreviewImportEdge>,
  diagnostics: Array<PreviewResolvedDiagnostic>,
) -> ResolveResult {
  let mut moduleResults: Array<PreviewModuleResult> = []
  for module in modules {
    moduleResults.push(module.result)
  }
  ResolveResult {
    queries: [],
    modules: moduleResults,
    edges: publicEdges,
    scopes: [],
    declarations: [],
    references: [],
    exports: [],
    diagnostics: diagnostics,
  }
}

